DECLARE packet jsonb := $staging_copy${"passages":[{"id":"87726f17-4efc-48db-b08b-d4fea2de8efe","slug":"completion-how-a-battery-works","title":"Completion — How a Battery Works","library":"l2_skill","status":"published","body_markdown":"The battery is so ordinary that most people never wonder how it works, yet the basic idea was settled more than two centuries ago. In 1800 the Italian scientist Alessandro Volta built the first true battery, stacking discs of two different metals separated by cloth soaked in salty water. His invention proved something remarkable: a carefully arranged chemical reaction could produce a steady flow of electricity, rather than the brief sparks people had seen before.\n\nEvery battery cell is built around the same three parts. There are two terminals, called electrodes, made of different materials. The negative electrode is known as the *anode*, and the positive one is the *cathode*. Between them sits a chemical paste or liquid called the *electrolyte*, which allows charged particles to pass from one electrode to the other while keeping the metals apart.\n\nThe electricity itself comes from chemistry. When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons. Because electrons are pushed away from the negative electrode and pulled towards the positive one, they flow steadily along the wire and through whatever device is attached — a torch bulb, perhaps, or a phone. This continuous movement of electrons is what we call an electric current, and it is the current that does the useful work.\n\nNothing, however, lasts forever. As the cell is used, the chemicals inside are gradually consumed, and the reaction slows until it can no longer push electrons around the circuit. At that point the battery goes flat, or dead in everyday speech. In a rechargeable battery, an outside electrical supply can reverse the reaction and restore the chemicals, though even these cells weaken over time. Exactly how to store energy more cheaply and cleanly is a question that researchers are still working to answer.","metadata":{"grammar_focus":[{"tip":"Bài completion về quy trình đầy câu bị động — khi điền từ, bám vào động từ bị động để xác định 'cái gì bị làm gì', đó thường là bước của tiến trình.","point":"Câu bị động trong văn quy trình + lược tác nhân","review":"Bị động: S + be + V3 (+ by O). Trong văn quy trình hầu hết lược 'by…' vì tác nhân hiển nhiên hoặc không quan trọng. Trạng từ (gradually) chen giữa be và V3.","example":"As the cell is used, the chemicals inside **are gradually consumed**, and the reaction slows.","analysis":"'are consumed' (be + V3) là bị động hiện tại đơn; tác nhân 'by ai/cái gì' bị lược bỏ vì điều quan trọng là chuyện gì XẢY RA với hóa chất, không phải ai làm. Đây là đặc trưng của văn miêu tả quy trình/khoa học: chủ thể hành động thường bị ẩn đi."},{"tip":"Mệnh đề 'which…' giải thích chức năng của bộ phận — trong bài table/flowchart completion, nó thường khớp với cột 'What it does'.","point":"Mệnh đề quan hệ xác định 'which' chỉ vật","review":"Mệnh đề quan hệ chỉ vật: N + which/that + V. allow/enable + O + to V = cho phép ai/cái gì làm gì.","example":"Between them sits a chemical paste or liquid called the electrolyte, **which allows** charged particles to pass from one electrode to the other.","analysis":"'which' thay cho 'the electrolyte' (vật) và làm chủ ngữ của 'allows'. Mệnh đề bổ sung chức năng của chất điện phân. Cấu trúc 'allow + O + to V' (allows particles to pass) là mẫu động từ + tân ngữ + to-infinitive."},{"tip":"Mệnh đề 'Because…' đầu câu là nguyên nhân của cả câu — hữu ích cho câu hỏi cause-effect và để hiểu vì sao một bước trong quy trình xảy ra.","point":"Mệnh đề trạng ngữ chỉ nguyên nhân với 'Because' (mang nghĩa bị động)","review":"Because + mệnh đề (có thể là bị động: S + be + V3). Khi đặt đầu câu thì có dấu phẩy. Cấu trúc song song: are pushed … and pulled (lược 'are' lần hai).","example":"**Because electrons are pushed** away from the negative electrode and pulled towards the positive one, they flow steadily along the wire.","analysis":"Mệnh đề 'Because + S + be + V3' (are pushed … and pulled) ở thể bị động, nêu nguyên nhân; mệnh đề chính 'they flow…' nêu kết quả. Mệnh đề 'Because' đứng đầu nên có dấu phẩy ngăn cách. Hai phân từ 'pushed' và 'pulled' dùng chung trợ động từ 'are' (cấu trúc song song)."}],"translation_vi":"Pin quen thuộc đến mức hầu hết mọi người không bao giờ tự hỏi nó hoạt động ra sao, dù nguyên lý cơ bản đã được xác lập hơn hai thế kỷ trước. Năm 1800, nhà khoa học người Ý Alessandro Volta chế tạo viên pin thực sự đầu tiên bằng cách xếp chồng các đĩa làm từ hai kim loại khác nhau, ngăn cách bởi vải ngâm nước muối. Phát minh của ông chứng minh một điều đáng chú ý: phản ứng hóa học được bố trí cẩn thận có thể tạo ra dòng điện ổn định, thay cho những tia lửa thoáng qua mà trước đó người ta từng thấy.\n\nMỗi tế bào pin đều được cấu tạo từ ba bộ phận cơ bản giống nhau. Có hai đầu cực, gọi là điện cực, được làm từ các vật liệu khác nhau. Điện cực âm được gọi là anode, còn điện cực dương là cathode. Giữa chúng là một chất dạng hồ hoặc chất lỏng gọi là chất điện phân; chất này cho phép các hạt mang điện đi từ điện cực này sang điện cực kia, đồng thời giữ các kim loại tách biệt.\n\nBản thân dòng điện được tạo ra nhờ quá trình hóa học. Khi dây dẫn nối hai điện cực thành một mạch điện, phản ứng bắt đầu ở anode và giải phóng những hạt nhỏ mang điện tích âm gọi là electron. Do bị đẩy khỏi điện cực âm và hút về điện cực dương, các electron chuyển động liên tục dọc theo dây dẫn và qua bất kỳ thiết bị nào được nối vào, chẳng hạn bóng đèn pin hoặc điện thoại. Chuyển động liên tục này của electron được gọi là dòng điện, và chính dòng điện thực hiện công việc hữu ích.\n\nTuy vậy, không có gì tồn tại mãi mãi. Khi tế bào pin được sử dụng, các hóa chất bên trong dần bị tiêu hao, và phản ứng chậm lại cho đến khi không còn đẩy được electron đi quanh mạch điện. Lúc đó pin hết điện, hay theo cách nói hằng ngày là pin chết. Với pin sạc, nguồn điện bên ngoài có thể đảo ngược phản ứng và khôi phục các hóa chất, dù ngay cả những tế bào pin này cũng yếu đi theo thời gian. Làm thế nào để lưu trữ năng lượng rẻ hơn và sạch hơn vẫn là câu hỏi mà các nhà nghiên cứu đang tìm lời giải.","practice_support":{"schema_version":1,"source_sha256":"fc7c310ee4dc51e1ac8a66a70b173167a942362aa9f5fa45c71f37135a19cf67","translation_sha256":"d499b8f1cd751a7c89d5c267456f5137f474a71dcf9582db0879d879f81b5506","units":[{"id":"p1-s1","source":"The battery is so ordinary that most people never wonder how it works, yet the basic idea was settled more than two centuries ago.","translation_vi":"Pin quen thuộc đến mức hầu hết mọi người không bao giờ tự hỏi nó hoạt động ra sao, dù nguyên lý cơ bản đã được xác lập hơn hai thế kỷ trước.","precision":"sentence","phrases":[{"source":"so ordinary","target":"quen thuộc đến mức"},{"source":"the basic idea","target":"nguyên lý cơ bản"}]},{"id":"p1-s2","source":"In 1800 the Italian scientist Alessandro Volta built the first true battery, stacking discs of two different metals separated by cloth soaked in salty water.","translation_vi":"Năm 1800, nhà khoa học người Ý Alessandro Volta chế tạo viên pin thực sự đầu tiên bằng cách xếp chồng các đĩa làm từ hai kim loại khác nhau, ngăn cách bởi vải ngâm nước muối.","precision":"sentence","phrases":[{"source":"stacking discs","target":"xếp chồng các đĩa"},{"source":"cloth soaked in salty water","target":"vải ngâm nước muối"}]},{"id":"p1-s3","source":"His invention proved something remarkable: a carefully arranged chemical reaction could produce a steady flow of electricity, rather than the brief sparks people had seen before.","translation_vi":"Phát minh của ông chứng minh một điều đáng chú ý: phản ứng hóa học được bố trí cẩn thận có thể tạo ra dòng điện ổn định, thay cho những tia lửa thoáng qua mà trước đó người ta từng thấy.","precision":"sentence","phrases":[{"source":"a steady flow of electricity","target":"dòng điện ổn định"},{"source":"brief sparks","target":"những tia lửa thoáng qua"}]},{"id":"p2-s1","source":"Every battery cell is built around the same three parts.","translation_vi":"Mỗi tế bào pin đều được cấu tạo từ ba bộ phận cơ bản giống nhau.","precision":"sentence","phrases":[{"source":"battery cell","target":"tế bào pin"},{"source":"three parts","target":"ba bộ phận"}]},{"id":"p2-s2","source":"There are two terminals, called electrodes, made of different materials.","translation_vi":"Có hai đầu cực, gọi là điện cực, được làm từ các vật liệu khác nhau.","precision":"sentence","phrases":[{"source":"two terminals","target":"hai đầu cực"},{"source":"electrodes","target":"điện cực"}]},{"id":"p2-s3","source":"The negative electrode is known as the anode, and the positive one is the cathode.","translation_vi":"Điện cực âm được gọi là anode, còn điện cực dương là cathode.","precision":"sentence","phrases":[{"source":"negative electrode","target":"Điện cực âm"},{"source":"positive one","target":"điện cực dương"}]},{"id":"p2-s4","source":"Between them sits a chemical paste or liquid called the electrolyte, which allows charged particles to pass from one electrode to the other while keeping the metals apart.","translation_vi":"Giữa chúng là một chất dạng hồ hoặc chất lỏng gọi là chất điện phân; chất này cho phép các hạt mang điện đi từ điện cực này sang điện cực kia, đồng thời giữ các kim loại tách biệt.","precision":"sentence","phrases":[{"source":"the electrolyte","target":"chất điện phân"},{"source":"charged particles","target":"các hạt mang điện"},{"source":"keeping the metals apart","target":"giữ các kim loại tách biệt"}]},{"id":"p3-s1","source":"The electricity itself comes from chemistry.","translation_vi":"Bản thân dòng điện được tạo ra nhờ quá trình hóa học.","precision":"sentence","phrases":[{"source":"comes from chemistry","target":"được tạo ra nhờ quá trình hóa học"}]},{"id":"p3-s2","source":"When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons.","translation_vi":"Khi dây dẫn nối hai điện cực thành một mạch điện, phản ứng bắt đầu ở anode và giải phóng những hạt nhỏ mang điện tích âm gọi là electron.","precision":"sentence","phrases":[{"source":"form a circuit","target":"thành một mạch điện"},{"source":"releases","target":"giải phóng"},{"source":"electrons","target":"electron"}]},{"id":"p3-s3","source":"Because electrons are pushed away from the negative electrode and pulled towards the positive one, they flow steadily along the wire and through whatever device is attached — a torch bulb, perhaps, or a phone.","translation_vi":"Do bị đẩy khỏi điện cực âm và hút về điện cực dương, các electron chuyển động liên tục dọc theo dây dẫn và qua bất kỳ thiết bị nào được nối vào, chẳng hạn bóng đèn pin hoặc điện thoại.","precision":"sentence","phrases":[{"source":"pushed away","target":"bị đẩy khỏi"},{"source":"pulled towards","target":"hút về"},{"source":"flow steadily","target":"chuyển động liên tục"}]},{"id":"p3-s4","source":"This continuous movement of electrons is what we call an electric current, and it is the current that does the useful work.","translation_vi":"Chuyển động liên tục này của electron được gọi là dòng điện, và chính dòng điện thực hiện công việc hữu ích.","precision":"sentence","phrases":[{"source":"what we call an electric current","target":"được gọi là dòng điện"},{"source":"useful work","target":"công việc hữu ích"}]},{"id":"p4-s1","source":"Nothing, however, lasts forever.","translation_vi":"Tuy vậy, không có gì tồn tại mãi mãi.","precision":"sentence","phrases":[{"source":"lasts forever","target":"tồn tại mãi mãi"}]},{"id":"p4-s2","source":"As the cell is used, the chemicals inside are gradually consumed, and the reaction slows until it can no longer push electrons around the circuit.","translation_vi":"Khi tế bào pin được sử dụng, các hóa chất bên trong dần bị tiêu hao, và phản ứng chậm lại cho đến khi không còn đẩy được electron đi quanh mạch điện.","precision":"sentence","phrases":[{"source":"gradually consumed","target":"dần bị tiêu hao"},{"source":"the reaction slows","target":"phản ứng chậm lại"}]},{"id":"p4-s3","source":"At that point the battery goes flat, or dead in everyday speech.","translation_vi":"Lúc đó pin hết điện, hay theo cách nói hằng ngày là pin chết.","precision":"sentence","phrases":[{"source":"goes flat","target":"hết điện"},{"source":"dead","target":"chết"}]},{"id":"p4-s4","source":"In a rechargeable battery, an outside electrical supply can reverse the reaction and restore the chemicals, though even these cells weaken over time.","translation_vi":"Với pin sạc, nguồn điện bên ngoài có thể đảo ngược phản ứng và khôi phục các hóa chất, dù ngay cả những tế bào pin này cũng yếu đi theo thời gian.","precision":"sentence","phrases":[{"source":"a rechargeable battery","target":"pin sạc"},{"source":"reverse the reaction","target":"đảo ngược phản ứng"},{"source":"weaken over time","target":"yếu đi theo thời gian"}]},{"id":"p4-s5","source":"Exactly how to store energy more cheaply and cleanly is a question that researchers are still working to answer.","translation_vi":"Làm thế nào để lưu trữ năng lượng rẻ hơn và sạch hơn vẫn là câu hỏi mà các nhà nghiên cứu đang tìm lời giải.","precision":"sentence","phrases":[{"source":"store energy","target":"lưu trữ năng lượng"},{"source":"more cheaply and cleanly","target":"rẻ hơn và sạch hơn"}]}],"illustrations":[],"question_evidence":{"1":{"question_sha256":"f87c217314267c351e6f1cce446d93b9293f8bf4574b28bc4068e0e189c6b959","source":"Between them sits a chemical paste or liquid called the electrolyte, which allows charged particles to pass from one electrode to the other while keeping the metals apart.","precision":"quote","illustrations":[]},"2":{"question_sha256":"4e337bf334935273e9e128d0226850d1a8164f20db0444a968e544b94bd3e7a9","source":"When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons.","precision":"quote","illustrations":[]},"3":{"question_sha256":"fb844c1ed3c945774b1db3370162c8d7e515f0b11f7f02c82bc81db4f6a95963","source":"In 1800 the Italian scientist Alessandro Volta built the first true battery, stacking discs of two different metals separated by cloth soaked in salty water.","precision":"quote","illustrations":[]},"4":{"question_sha256":"ca47ed38d7520c27165688f25a80a811094013afbf65379d2fbe6fd09c1de2da","source":"The negative electrode is known as the anode, and the positive one is the cathode.","precision":"quote","illustrations":[{"src":"/reading-illustrations/battery-anode.svg","alt":"Điện cực âm là anode.","caption":"Minh hoạ tế bào pin khi phóng điện theo bài đọc. Mũi tên mô tả chiều electron, không phải chiều dòng điện quy ước."}]},"5":{"question_sha256":"c2587afedaa316ea61ad7f2395f903e533b3e3fc2357871cca4810a0d7bd70a1","source":"The negative electrode is known as the anode, and the positive one is the cathode.","precision":"quote","illustrations":[{"src":"/reading-illustrations/battery-cathode.svg","alt":"Điện cực dương là cathode.","caption":"Minh hoạ tế bào pin khi phóng điện theo bài đọc. Mũi tên mô tả chiều electron, không phải chiều dòng điện quy ước."}]},"6":{"question_sha256":"7a6d4d71c8d35d03ac0e9364ad12d40a36e9027dc21d4e3c05cf921a157915d6","source":"When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons.","precision":"quote","illustrations":[{"src":"/reading-illustrations/battery-electrons.svg","alt":"Electron đi qua dây dẫn và thiết bị.","caption":"Minh hoạ tế bào pin khi phóng điện theo bài đọc. Mũi tên mô tả chiều electron, không phải chiều dòng điện quy ước."}]},"7":{"question_sha256":"2b87247e70920a83c271b6516c91142af0da2494e306509c25bd6d50d71e2759","source":"This continuous movement of electrons is what we call an electric current, and it is the current that does the useful work.","precision":"quote","illustrations":[{"src":"/reading-illustrations/battery-current.svg","alt":"Chuyển động liên tục của electron tạo thành dòng điện.","caption":"Minh hoạ tế bào pin khi phóng điện theo bài đọc. Mũi tên mô tả chiều electron, không phải chiều dòng điện quy ước."}]},"8":{"question_sha256":"751bf954e845f87cc188e75bd644fb135c2f41dd5ca67c4f77f8543f1316f0d6","source":"At that point the battery goes flat, or dead in everyday speech.","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"electrode","definition":"điện cực","aliases":["electrodes"],"example":"There are two terminals, called electrodes, made of different materials."},{"term":"anode","definition":"điện cực âm trong tế bào pin được mô tả","aliases":[],"example":"The negative electrode is known as the anode, and the positive one is the cathode."},{"term":"cathode","definition":"điện cực dương trong tế bào pin được mô tả","aliases":[],"example":"The negative electrode is known as the anode, and the positive one is the cathode."},{"term":"electrolyte","definition":"chất điện phân","aliases":[],"example":"Between them sits a chemical paste or liquid called the electrolyte, which allows charged particles to pass from one electrode to the other while keeping the metals apart."},{"term":"charged particles","definition":"các hạt mang điện","aliases":[],"example":"Between them sits a chemical paste or liquid called the electrolyte, which allows charged particles to pass from one electrode to the other while keeping the metals apart."},{"term":"circuit","definition":"mạch điện","aliases":[],"example":"When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons."},{"term":"electron","definition":"electron; hạt mang điện tích âm","aliases":["electrons"],"example":"When a wire connects the two electrodes to form a circuit, a reaction begins at the anode that releases tiny negative particles called electrons."},{"term":"current","definition":"dòng điện","aliases":[],"example":"This continuous movement of electrons is what we call an electric current, and it is the current that does the useful work."},{"term":"rechargeable","definition":"có thể sạc lại","aliases":[],"example":"In a rechargeable battery, an outside electrical supply can reverse the reaction and restore the chemicals, though even these cells weaken over time."},{"term":"goes flat","definition":"hết điện","aliases":[],"example":"At that point the battery goes flat, or dead in everyday speech."}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["science","technology"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"59bd33e8-ead5-4edf-8d3f-8c480eb04348","slug":"inference-psychology-of-colour","title":"Inference & Multiple Choice — The Psychology of Colour","library":"l2_skill","status":"published","body_markdown":"When the British designer of a well-known soft-drink can chose a deep red, the decision was not only about taste. Red is loud, warm and impossible to ignore, and marketers have long believed it pushes shoppers towards quick, energetic choices. The psychology of colour tries to test such hunches, and the results are more tangled than the confident claims on advertising blogs suggest.\n\nSome patterns do appear with reasonable consistency. People shown the colour blue often report feeling calmer and better able to concentrate, which may help explain why so many offices, classrooms and hospital wards are painted in cool, pale shades rather than bold, saturated ones. Warm colours such as orange and yellow, by contrast, tend to feel stimulating, and they are common in restaurants, gyms and other places that want customers to feel awake, hungry and active.\n\nOther findings are far less settled. One widely reported study of combat sports suggested that athletes wearing red won slightly more often than those in blue, hinting that the colour signals dominance and may unsettle opponents. Yet the effect has not always reappeared when other researchers repeat the experiment, and small differences in crowd size, sport or measurement can easily account for the modest gap that remains.\n\nPart of the difficulty is that colour rarely acts alone. Its meaning shifts from one culture to another: white suggests purity at many Western weddings but mourning at some Asian funerals. The same red that excites a shopper may warn a driver to stop. A colour, in other words, can pull in different directions depending on where it appears and who is looking. Whether colour truly steers our behaviour, or merely nudges it within limits we set elsewhere, remains an open and rather stubborn question.","metadata":{"grammar_focus":[{"tip":"Yes/No/Not Given và inference soi đúng các từ rào đón: nếu câu hỏi bỏ 'may/tend to' và khẳng định chắc nịch trong khi bài rào đón, đáp án thường KHÔNG khớp (NO/NOT GIVEN).","point":"Rào đón (hedging) bằng 'tend to' và 'may'","review":"Hedging: tend to / may / might / appear to / seem to + V làm nhẹ phát biểu. 'may' sau đó là V nguyên mẫu (may unsettle).","example":"Warm colours such as orange and yellow … **tend to** feel stimulating … the colour signals dominance and **may** unsettle opponents.","analysis":"'tend to + V' (có xu hướng) và modal 'may + V' (có thể) hạ mức cam kết của phát biểu: tác giả không khẳng định chắc chắn mà chỉ nêu xu hướng/khả năng. Đây là giọng điệu thận trọng đặc trưng của văn học thuật, tránh kết luận tuyệt đối."},{"tip":"'by contrast/however' báo hiệu tác giả đang lật sang ý đối lập — chỗ chuyển ý này hay là nơi đặt câu hỏi so sánh hai nhóm/hai quan điểm.","point":"Trạng từ/cụm nối tương phản 'by contrast'","review":"Cụm nối tương phản: by contrast, however, on the other hand, in contrast — đứng đầu hoặc chèn giữa câu, ngăn bằng dấu phẩy. Khác liên từ 'but' (nối trong cùng câu).","example":"Warm colours such as orange and yellow, **by contrast**, tend to feel stimulating.","analysis":"'by contrast' là cụm trạng từ nối, chèn giữa câu (ngăn bằng hai dấu phẩy), báo hiệu sự đối lập với ý trước đó (màu xanh dịu >< màu ấm kích thích). Nó nối ý giữa hai câu/đoạn chứ không nối hai mệnh đề như liên từ 'but'."},{"tip":"Cụm '…, V-ing that…' (hinting/suggesting/indicating that) thường nêu KẾT LUẬN tác giả rút ra — đọc kỹ để trả lời câu hỏi suy luận về quan điểm/ý ngầm.","point":"Mệnh đề phân từ hiện tại (-ing) nêu hệ quả/bổ sung ý","review":"Participle clause: …, V-ing… rút gọn cho 'and + S + V' hoặc nêu hệ quả. Chủ ngữ ngầm phải khớp mệnh đề chính.","example":"athletes wearing red won slightly more often than those in blue, **hinting that** the colour signals dominance.","analysis":"Cụm phân từ 'hinting that…' đứng sau mệnh đề chính, không có chủ ngữ riêng — chủ ngữ logic là cả ý đứng trước (= and this hints that…). Nó diễn tả hệ quả/diễn giải mà sự việc gợi ra. 'hinting' bản thân cũng là một động từ rào đón (gợi ý, chứ không khẳng định)."}],"translation_vi":"Khi nhà thiết kế người Anh chọn màu đỏ đậm cho một lon nước giải khát nổi tiếng, quyết định đó không chỉ liên quan đến hương vị. Màu đỏ nổi bật, ấm áp và khó có thể bỏ qua; từ lâu, giới tiếp thị tin rằng nó thúc đẩy người mua đưa ra những lựa chọn nhanh chóng và đầy năng lượng. Tâm lý học màu sắc tìm cách kiểm nghiệm những linh cảm như vậy, và kết quả phức tạp hơn những lời khẳng định đầy tự tin trên các blog quảng cáo.\n\nMột số xu hướng thực sự xuất hiện khá nhất quán. Người được cho xem màu xanh lam thường nói rằng họ thấy bình tĩnh hơn và dễ tập trung hơn. Điều này có thể giải thích vì sao nhiều văn phòng, lớp học và phòng bệnh được sơn màu dịu, nhạt thay vì những màu đậm, rực rỡ. Ngược lại, các màu ấm như cam và vàng thường tạo cảm giác kích thích; chúng phổ biến ở nhà hàng, phòng tập và những nơi muốn khách cảm thấy tỉnh táo, đói bụng và năng động.\n\nNhững phát hiện khác còn kém chắc chắn hơn nhiều. Một nghiên cứu về thể thao đối kháng được nhắc đến rộng rãi cho thấy vận động viên mặc đỏ thắng thường xuyên hơn một chút so với người mặc xanh lam. Điều này gợi ý rằng màu đỏ thể hiện sự áp đảo và có thể khiến đối thủ bất an. Tuy nhiên, hiệu ứng này không phải lúc nào cũng xuất hiện lại khi các nhà nghiên cứu khác lặp lại thí nghiệm; những khác biệt nhỏ về số khán giả, môn thể thao hoặc cách đo có thể dễ dàng giải thích khoảng cách khiêm tốn còn lại.\n\nMột phần khó khăn nằm ở chỗ màu sắc hiếm khi tác động riêng lẻ. Ý nghĩa của màu sắc thay đổi giữa các nền văn hóa: màu trắng gợi sự thuần khiết trong nhiều đám cưới phương Tây, nhưng gợi sự tang tóc trong một số đám tang ở châu Á. Cũng màu đỏ khiến người mua hào hứng ấy lại có thể cảnh báo người lái xe phải dừng lại. Nói cách khác, một màu có thể tạo ra những tác động khác nhau tùy nơi nó xuất hiện và người đang nhìn nó. Màu sắc thực sự điều khiển hành vi của chúng ta hay chỉ tác động nhẹ trong những giới hạn được xác lập bởi các yếu tố khác vẫn là câu hỏi bỏ ngỏ và khá khó giải quyết.","practice_support":{"schema_version":1,"source_sha256":"035f97d77e7704596f668ec84ee83c1835e0ddd9c8112747cac312b13f9760d6","translation_sha256":"29416a6eef3f912b04476f0ee03a1004c34ed340706975552e42c73b8caa94fe","units":[{"id":"p1-s1","source":"When the British designer of a well-known soft-drink can chose a deep red, the decision was not only about taste.","translation_vi":"Khi nhà thiết kế người Anh chọn màu đỏ đậm cho một lon nước giải khát nổi tiếng, quyết định đó không chỉ liên quan đến hương vị.","precision":"sentence","phrases":[{"source":"a deep red","target":"màu đỏ đậm"},{"source":"not only about taste","target":"không chỉ liên quan đến hương vị"}]},{"id":"p1-s2","source":"Red is loud, warm and impossible to ignore, and marketers have long believed it pushes shoppers towards quick, energetic choices.","translation_vi":"Màu đỏ nổi bật, ấm áp và khó có thể bỏ qua; từ lâu, giới tiếp thị tin rằng nó thúc đẩy người mua đưa ra những lựa chọn nhanh chóng và đầy năng lượng.","precision":"sentence","phrases":[{"source":"impossible to ignore","target":"khó có thể bỏ qua"},{"source":"pushes shoppers","target":"thúc đẩy người mua"}]},{"id":"p1-s3","source":"The psychology of colour tries to test such hunches, and the results are more tangled than the confident claims on advertising blogs suggest.","translation_vi":"Tâm lý học màu sắc tìm cách kiểm nghiệm những linh cảm như vậy, và kết quả phức tạp hơn những lời khẳng định đầy tự tin trên các blog quảng cáo.","precision":"sentence","phrases":[{"source":"such hunches","target":"những linh cảm như vậy"},{"source":"more tangled","target":"phức tạp hơn"}]},{"id":"p2-s1","source":"Some patterns do appear with reasonable consistency.","translation_vi":"Một số xu hướng thực sự xuất hiện khá nhất quán.","precision":"sentence","phrases":[{"source":"reasonable consistency","target":"khá nhất quán"}]},{"id":"p2-s2","source":"People shown the colour blue often report feeling calmer and better able to concentrate, which may help explain why so many offices, classrooms and hospital wards are painted in cool, pale shades rather than bold, saturated ones.","translation_vi":"Người được cho xem màu xanh lam thường nói rằng họ thấy bình tĩnh hơn và dễ tập trung hơn. Điều này có thể giải thích vì sao nhiều văn phòng, lớp học và phòng bệnh được sơn màu dịu, nhạt thay vì những màu đậm, rực rỡ.","precision":"sentence","phrases":[{"source":"calmer","target":"bình tĩnh hơn"},{"source":"better able to concentrate","target":"dễ tập trung hơn"},{"source":"may help explain","target":"có thể giải thích"},{"source":"cool, pale shades","target":"màu dịu, nhạt"}]},{"id":"p2-s3","source":"Warm colours such as orange and yellow, by contrast, tend to feel stimulating, and they are common in restaurants, gyms and other places that want customers to feel awake, hungry and active.","translation_vi":"Ngược lại, các màu ấm như cam và vàng thường tạo cảm giác kích thích; chúng phổ biến ở nhà hàng, phòng tập và những nơi muốn khách cảm thấy tỉnh táo, đói bụng và năng động.","precision":"sentence","phrases":[{"source":"by contrast","target":"Ngược lại"},{"source":"stimulating","target":"kích thích"},{"source":"awake, hungry and active","target":"tỉnh táo, đói bụng và năng động"}]},{"id":"p3-s1","source":"Other findings are far less settled.","translation_vi":"Những phát hiện khác còn kém chắc chắn hơn nhiều.","precision":"sentence","phrases":[{"source":"far less settled","target":"kém chắc chắn hơn nhiều"}]},{"id":"p3-s2","source":"One widely reported study of combat sports suggested that athletes wearing red won slightly more often than those in blue, hinting that the colour signals dominance and may unsettle opponents.","translation_vi":"Một nghiên cứu về thể thao đối kháng được nhắc đến rộng rãi cho thấy vận động viên mặc đỏ thắng thường xuyên hơn một chút so với người mặc xanh lam. Điều này gợi ý rằng màu đỏ thể hiện sự áp đảo và có thể khiến đối thủ bất an.","precision":"sentence","phrases":[{"source":"combat sports","target":"thể thao đối kháng"},{"source":"slightly more often","target":"thường xuyên hơn một chút"},{"source":"signals dominance","target":"thể hiện sự áp đảo"},{"source":"may unsettle opponents","target":"có thể khiến đối thủ bất an"}]},{"id":"p3-s3","source":"Yet the effect has not always reappeared when other researchers repeat the experiment, and small differences in crowd size, sport or measurement can easily account for the modest gap that remains.","translation_vi":"Tuy nhiên, hiệu ứng này không phải lúc nào cũng xuất hiện lại khi các nhà nghiên cứu khác lặp lại thí nghiệm; những khác biệt nhỏ về số khán giả, môn thể thao hoặc cách đo có thể dễ dàng giải thích khoảng cách khiêm tốn còn lại.","precision":"sentence","phrases":[{"source":"has not always reappeared","target":"không phải lúc nào cũng xuất hiện lại"},{"source":"repeat the experiment","target":"lặp lại thí nghiệm"},{"source":"the modest gap","target":"khoảng cách khiêm tốn"}]},{"id":"p4-s1","source":"Part of the difficulty is that colour rarely acts alone.","translation_vi":"Một phần khó khăn nằm ở chỗ màu sắc hiếm khi tác động riêng lẻ.","precision":"sentence","phrases":[{"source":"rarely acts alone","target":"hiếm khi tác động riêng lẻ"}]},{"id":"p4-s2","source":"Its meaning shifts from one culture to another: white suggests purity at many Western weddings but mourning at some Asian funerals.","translation_vi":"Ý nghĩa của màu sắc thay đổi giữa các nền văn hóa: màu trắng gợi sự thuần khiết trong nhiều đám cưới phương Tây, nhưng gợi sự tang tóc trong một số đám tang ở châu Á.","precision":"sentence","phrases":[{"source":"purity","target":"sự thuần khiết"},{"source":"mourning","target":"sự tang tóc"}]},{"id":"p4-s3","source":"The same red that excites a shopper may warn a driver to stop.","translation_vi":"Cũng màu đỏ khiến người mua hào hứng ấy lại có thể cảnh báo người lái xe phải dừng lại.","precision":"sentence","phrases":[{"source":"excites a shopper","target":"khiến người mua hào hứng"},{"source":"warn a driver to stop","target":"cảnh báo người lái xe phải dừng lại"}]},{"id":"p4-s4","source":"A colour, in other words, can pull in different directions depending on where it appears and who is looking.","translation_vi":"Nói cách khác, một màu có thể tạo ra những tác động khác nhau tùy nơi nó xuất hiện và người đang nhìn nó.","precision":"sentence","phrases":[{"source":"depending on","target":"tùy"},{"source":"who is looking","target":"người đang nhìn nó"}]},{"id":"p4-s5","source":"Whether colour truly steers our behaviour, or merely nudges it within limits we set elsewhere, remains an open and rather stubborn question.","translation_vi":"Màu sắc thực sự điều khiển hành vi của chúng ta hay chỉ tác động nhẹ trong những giới hạn được xác lập bởi các yếu tố khác vẫn là câu hỏi bỏ ngỏ và khá khó giải quyết.","precision":"sentence","phrases":[{"source":"steers our behaviour","target":"điều khiển hành vi của chúng ta"},{"source":"merely nudges it","target":"chỉ tác động nhẹ"},{"source":"an open and rather stubborn question","target":"câu hỏi bỏ ngỏ và khá khó giải quyết"}]}],"illustrations":[],"question_evidence":{"1":{"question_sha256":"e8efaa67b39c630c2cd08f09f7473b0f612b76a872e9c9b74f345eafbd91336f","source":"Yet the effect has not always reappeared when other researchers repeat the experiment, and small differences in crowd size, sport or measurement can easily account for the modest gap that remains.","precision":"quote","illustrations":[]},"2":{"question_sha256":"d647be7db045f1250d0271a6ddd4bd0bb09812ec6168e8b6f19107f4a343268b","source":"People shown the colour blue often report feeling calmer and better able to concentrate, which may help explain why so many offices, classrooms and hospital wards are painted in cool, pale shades rather than bold, saturated ones.","precision":"quote","illustrations":[]},"3":{"question_sha256":"cdd7dbeb8db52103dfdf13af7aab02c264e82118558cc78d629d96a89723c5a8","source":"Its meaning shifts from one culture to another: white suggests purity at many Western weddings but mourning at some Asian funerals. The same red that excites a shopper may warn a driver to stop. A colour, in other words, can pull in different directions depending on where it appears and who is looking.","precision":"quote","illustrations":[{"src":"/reading-illustrations/colour-review.svg","alt":"Cùng màu đỏ: một nhãn hàng có thể làm người mua hào hứng; biển dừng yêu cầu người lái dừng lại.","caption":"Màu sắc có ý nghĩa phụ thuộc bối cảnh; sơ đồ minh hoạ ví dụ trong bài, không khẳng định một tác động luôn xảy ra."}]}}}},"glossary":[{"term":"hunch","definition":"linh cảm, nhận định chưa được kiểm chứng","aliases":["hunches"],"example":"The psychology of colour tries to test such hunches, and the results are more tangled than the confident claims on advertising blogs suggest."},{"term":"consistency","definition":"tính nhất quán","aliases":[],"example":"Some patterns do appear with reasonable consistency."},{"term":"stimulating","definition":"gây kích thích, làm tỉnh táo","aliases":[],"example":"Warm colours such as orange and yellow, by contrast, tend to feel stimulating, and they are common in restaurants, gyms and other places that want customers to feel awake, hungry and active."},{"term":"dominance","definition":"sự áp đảo, ưu thế","aliases":[],"example":"One widely reported study of combat sports suggested that athletes wearing red won slightly more often than those in blue, hinting that the colour signals dominance and may unsettle opponents."},{"term":"unsettle","definition":"làm ai bất an","aliases":[],"example":"One widely reported study of combat sports suggested that athletes wearing red won slightly more often than those in blue, hinting that the colour signals dominance and may unsettle opponents."},{"term":"mourning","definition":"sự tang tóc, đau buồn khi có người qua đời","aliases":[],"example":"Its meaning shifts from one culture to another: white suggests purity at many Western weddings but mourning at some Asian funerals."},{"term":"nudge","definition":"tác động nhẹ, thúc đẩy một chút","aliases":["nudges"],"example":"Whether colour truly steers our behaviour, or merely nudges it within limits we set elsewhere, remains an open and rather stubborn question."},{"term":"saturated","definition":"đậm và rực (nói về màu)","aliases":[],"example":"People shown the colour blue often report feeling calmer and better able to concentrate, which may help explain why so many offices, classrooms and hospital wards are painted in cool, pale shades rather than bold, saturated ones."},{"term":"modest","definition":"nhỏ, không lớn (nói về mức chênh lệch)","aliases":[],"example":"Yet the effect has not always reappeared when other researchers repeat the experiment, and small differences in crowd size, sport or measurement can easily account for the modest gap that remains."},{"term":"open question","definition":"câu hỏi còn bỏ ngỏ","aliases":[],"example":""}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["psychology","science"],"skill_focus":"inference","word_count":null,"estimated_minutes":10},{"id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","slug":"matching-ancient-wonders","title":"Matching — The Seven Ancient Wonders","library":"l2_skill","status":"published","body_markdown":"**A**  More than two thousand years ago, Greek writers drew up a list of seven remarkable\nstructures that every traveller hoped to see: the Seven Wonders of the Ancient World. Of\nthese seven, only one still stands today. The Great Pyramid of Giza, built in Egypt\naround 2560 BC as a tomb for a king, is the oldest wonder of all and the only one that\nhas survived into modern times.\n\n**B**  Far to the east stood the Hanging Gardens of Babylon, said to rise in green\nterraces above the desert city, with trees and flowers spilling over high walls. Yet no\nfirm trace of the gardens has ever been found, and some historians doubt whether they\nexisted at all.\n\n**C**  On the coast of Egypt, the Lighthouse of Alexandria guided ships safely into the\nbusy harbour. A great fire burned at its top, and a polished mirror is thought to have\nthrown the light far out to sea. It was one of the tallest structures in the ancient\nworld.\n\n**D**  Guarding another harbour was the Colossus of Rhodes, a giant bronze statue of the\nsun god Helios. It was built to celebrate a victory over an invading army. The statue\nstood for only a few decades, however, before an earthquake snapped it at the knees and\nbrought it crashing down.","metadata":{"grammar_focus":[{"tip":"Câu sentence-endings thường giữ nguyên dạng bị động 'was built to…' — bám cụm này để nối đúng mục đích của từng kỳ quan.","point":"Bị động quá khứ đơn (was/were + V3)","review":"Bị động quá khứ đơn: S + was/were + V3 (+ by O). Có thể rút gọn thành cụm phân từ (built…, made…) để bổ nghĩa cho danh từ.","example":"The Great Pyramid of Giza, **built** in Egypt around 2560 BC as a tomb for a king...","analysis":"'built' ở đây là phân từ quá khứ rút gọn của mệnh đề bị động (= which was built). Dạng đầy đủ 'was built' = was (be quá khứ) + built (V3 của build); tác nhân bị lược vì không quan trọng. Bị động quá khứ rất phổ biến khi kể về công trình cổ."},{"tip":"'the only one that has survived' = duy nhất còn lại — đúng dạng dữ kiện cho câu matching information số 1.","point":"Mệnh đề quan hệ 'that' + hiện tại hoàn thành (have/has + V3)","review":"Mệnh đề quan hệ: N + that/which + V…. Hiện tại hoàn thành: have/has + V3, dùng cho việc bắt đầu trong quá khứ và còn liên quan đến hiện tại.","example":"...the only one **that has survived** into modern times.","analysis":"'that has survived' là mệnh đề quan hệ xác định bổ nghĩa cho 'the only one'; 'that' làm chủ ngữ. 'has survived' là hiện tại hoàn thành, nối quá khứ với hiện tại (tồn tại từ xưa đến nay)."},{"tip":"Mỗi beginning trong matching sentence endings đều theo mẫu 'was built/designed/created to…' — nối với ending bắt đầu bằng động từ nguyên mẫu (serve, help, celebrate).","point":"Cụm chỉ mục đích 'to + V' (built to / designed to)","review":"Chỉ mục đích: to + V / in order to + V. Sau 'be built/designed/created' thường nối 'to + V' để nêu mục đích.","example":"It **was built to celebrate** a victory over an invading army.","analysis":"'to celebrate…' là cụm động từ nguyên mẫu (to-infinitive) chỉ mục đích, đứng sau động từ bị động 'was built', cho biết công trình được dựng nhằm mục đích gì. 'to + V nguyên mẫu' trả lời cho câu hỏi 'để làm gì'."}],"translation_vi":"**A**  Hơn hai nghìn năm trước, các nhà văn Hy Lạp đã lập một danh sách bảy công trình đáng kinh ngạc mà mọi lữ khách đều mong được tận mắt nhìn thấy: Bảy Kỳ Quan của Thế Giới Cổ Đại. Trong số bảy kỳ quan ấy, chỉ còn một cái vẫn đứng vững đến ngày nay. Đại Kim Tự Tháp Giza, được xây ở Ai Cập vào khoảng năm 2560 trước Công nguyên làm lăng mộ cho một vị vua, là kỳ quan lâu đời nhất trong tất cả và là kỳ quan duy nhất còn tồn tại đến thời hiện đại.\n\n**B**  Xa về phía đông là Vườn Treo Babylon, được cho là vươn lên thành những bậc thềm xanh tươi phía trên thành phố sa mạc, với cây cối và hoa lá tràn ra ngoài những bức tường cao. Thế nhưng chưa từng tìm thấy dấu vết chắc chắn nào của khu vườn, và một số nhà sử học còn nghi ngờ liệu nó có thực sự tồn tại hay không.\n\n**C**  Trên bờ biển Ai Cập, Hải Đăng Alexandria đã dẫn các con tàu vào cảng đông đúc một cách an toàn. Một ngọn lửa lớn cháy trên đỉnh của nó, và người ta cho rằng một tấm gương được đánh bóng đã hắt ánh sáng ra xa ngoài biển. Nó là một trong những công trình cao nhất của thế giới cổ đại.\n\n**D**  Canh giữ một bến cảng khác là Tượng Khổng Lồ Rhodes, một bức tượng đồng khổng lồ của thần mặt trời Helios. Nó được dựng lên để ăn mừng chiến thắng trước một đạo quân xâm lược. Tuy nhiên, bức tượng chỉ đứng được vài thập kỷ trước khi một trận động đất bẻ gãy nó ngang đầu gối và làm nó đổ sập xuống.","practice_support":{"schema_version":1,"source_sha256":"944ce3c055312afa0871ecedad48e7a79565ef996966d5febecc57d5dcb54993","translation_sha256":"e8e6040c376ca0219301a57cd148fa11aafbcafd33e60ae2dad6ba80bca9cd74","units":[],"illustrations":[],"question_evidence":{"5":{"question_sha256":"10cb204a4a43c75cf0d05cc079bb29e3dec9f4268d8caa8189eeb04d6ca8d108","source":"built in Egypt around 2560 BC as a tomb for a king","precision":"quote","illustrations":[]},"6":{"question_sha256":"f2dff5b76632b65b93a873081252122899ae371bf28460b044fb9a92ef1c1834","source":"A great fire burned at its top","precision":"quote","illustrations":[]},"7":{"question_sha256":"129401c7ce43d3326b4910a0db78c415a298e7834ebeaa435a60441efc7db140","source":"It was built to celebrate a victory over an invading army","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"tomb","definition":"lăng mộ","example":"The Great Pyramid of Giza, built in Egypt around 2560 BC as a tomb for a king, is the oldest wonder of all and the only one that has survived into modern times.","aliases":[]},{"term":"terraces","definition":"các tầng hoặc bậc cao xếp nối nhau","example":"B Far to the east stood the Hanging Gardens of Babylon, said to rise in green terraces above the desert city, with trees and flowers spilling over high walls.","aliases":[]},{"term":"harbour","definition":"cảng, bến tàu","example":"C On the coast of Egypt, the Lighthouse of Alexandria guided ships safely into the busy harbour.","aliases":[]},{"term":"bronze","definition":"đồng thiếc","example":"D Guarding another harbour was the Colossus of Rhodes, a giant bronze statue of the sun god Helios.","aliases":[]},{"term":"invading","definition":"đang xâm lược","example":"It was built to celebrate a victory over an invading army.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["history"],"skill_focus":"scanning","word_count":null,"estimated_minutes":9},{"id":"723850ff-85db-4ecd-b43e-992a6d1ee340","slug":"matching-animal-communication","title":"Matching tasks — Decoding Animal Communication","library":"l2_skill","status":"published","body_markdown":"**A**  For much of the twentieth century, biologists were reluctant to credit animals\nwith anything resembling true, structured communication. Calls, songs and gestures\nwere treated as simple reflexes — automatic responses to hunger or fear, not messages\ncarrying meaning. A handful of patient researchers overturned that assumption, and in\ndoing so reshaped how we think about the minds of other species.\n\n**B**  The pioneer was the Austrian zoologist Karl von Frisch. Watching honeybees\nreturn to the hive, he realised that a returning forager performs a precise \"waggle\ndance\", and that the angle and length of the dance encode the direction and distance\nof a food source. The claim was initially met with scepticism — many found it hard to\nbelieve an insect could pass on such specific information — but careful experiments\nconfirmed it, and von Frisch shared a Nobel Prize for the discovery in 1973.\n\n**C**  Decades later, the psychologist Irene Pepperberg pushed the question further\nwith a single African grey parrot named Alex. Over thirty years, Alex learned to use\nspoken English labels for objects, colours and shapes, and could even identify small\nquantities. Pepperberg argued that the bird was not merely imitating sounds but\nattaching them to concepts — using words, in a limited but real sense, to name the\nworld.\n\n**D**  The biologist Con Slobodchikoff found comparable sophistication in an unlikely\nanimal: the prairie dog. By recording and analysing thousands of alarm calls, he\nshowed that these rodents do not simply signal \"danger\". Their calls appear to encode\nthe type of predator, its size, and even details such as the colour of a passing\nhuman's clothing — a remarkably detailed description packed into a brief squeak.\n\n**E**  Finally, the researcher Katy Payne uncovered an entire channel of communication\nthat humans had simply failed to notice. Studying elephants, she discovered that they\nproduce powerful infrasound — vibrations too low for the human ear — which can travel\nfor kilometres across the savannah, allowing distant herds to coordinate their\nmovements.\n\nTaken together, the work of these researchers suggests that the gap between human and\nanimal communication may be narrower than once believed. How much meaning truly passes\nbetween animals is still debated, but the old picture of mindless reflex is gone for\ngood.","metadata":{"grammar_focus":[{"tip":"Cụm V-ing đầu câu phải cùng chủ thể với mệnh đề chính — đọc tới chủ ngữ chính để xác nhận, tránh 'dangling participle'.","point":"Mệnh đề phân từ rút gọn đầu câu (-ing) chỉ thời gian/đồng thời","review":"While/When + S + V-ing → V-ing… (rút gọn khi cùng chủ ngữ). Động từ tri giác: watch/see/hear + O + V (bare) = chứng kiến trọn hành động.","example":"**Watching honeybees return to the hive**, he realised that a returning forager performs a precise \"waggle dance\"","analysis":"Cụm phân từ hiện tại 'Watching…' đứng đầu câu, rút gọn từ 'While he was watching…'. Chủ ngữ logic của 'Watching' trùng chủ ngữ mệnh đề chính 'he'. Bên trong có cấu trúc tri giác 'watch + O + V-bare' (watch honeybees return). Mệnh đề chính lại chứa mệnh đề danh ngữ 'that…' làm tân ngữ của 'realised'."},{"tip":"Trong matching/features, 'not merely X but Y' báo hiệu đặc trưng cốt lõi là Y — chính là chi tiết để ghép, X là phần dễ gây nhiễu.","point":"Cấu trúc tương quan song song 'not merely A but B'","review":"not merely/only A but (also) B = không chỉ A mà còn B. Hai vế phải song song từ loại (V-ing // V-ing).","example":"the bird was **not merely imitating** sounds **but attaching** them to concepts","analysis":"Cấu trúc tương phản 'not merely A but B' nâng cấp từ 'not only … but also', nhấn mạnh B quan trọng hơn A. Hai vế song song dùng V-ing ('imitating' // 'attaching') sau trợ động từ 'was', giữ cân đối ngữ pháp. 'merely' (= chỉ đơn thuần) tăng sắc thái nhượng bộ."},{"tip":"Dấu hai chấm và gạch ngang giới thiệu phần làm rõ — trong matching information, đây thường là 'thông tin cụ thể' mà câu hỏi tìm.","point":"Cụm đồng vị (appositive) sau dấu hai chấm/gạch ngang","review":"Cụm đồng vị: N1 (: hoặc , hoặc —) N2 → N2 giải thích/cụ thể hoá N1. Dấu hai chấm thường dẫn ví dụ/làm rõ.","example":"found comparable sophistication in an unlikely animal: **the prairie dog**","analysis":"Sau dấu hai chấm, 'the prairie dog' là cụm đồng vị, nêu danh tính cụ thể cho 'an unlikely animal'. Cuối đoạn còn một đồng vị khác sau gạch ngang: '— a remarkably detailed description packed into a brief squeak' (có mệnh đề quan hệ rút gọn bị động 'packed…')."},{"tip":"Câu kết 'narrower than once believed' chính là ý tổng kết → khớp với sentence-ending 'narrower than once believed' (q8); để ý cấu trúc lược từ khi đối chiếu.","point":"So sánh hơn + 'than once believed' (lược mệnh đề)","review":"adj-er + than (+ once/previously/expected) — có thể lược 'it was/than people' khi nghĩa đã rõ. may = phán đoán dè dặt.","example":"the gap between human and animal communication may be **narrower than once believed**","analysis":"So sánh hơn 'narrower than…' với vế sau 'than once believed' đã lược chủ ngữ + trợ động từ ('than [it was] once believed [to be]'). 'may be' là hedging dè dặt. Đây là kiểu lược từ (ellipsis) trong cấu trúc so sánh, rất gọn và trang trọng."}],"translation_vi":"**A**  Trong phần lớn thế kỷ hai mươi, các nhà sinh học miễn cưỡng thừa nhận động vật có bất cứ điều gì giống như sự giao tiếp đích thực, có cấu trúc. Những tiếng kêu, bài hát và cử chỉ được xem như những phản xạ đơn giản — những phản ứng tự động trước cơn đói hay nỗi sợ, không phải những thông điệp mang ý nghĩa. Một số ít các nhà nghiên cứu kiên nhẫn đã lật đổ giả định đó, và khi làm vậy đã định hình lại cách chúng ta nghĩ về tâm trí của những loài khác.\n\n**B**  Người tiên phong là nhà động vật học người Áo Karl von Frisch. Khi quan sát những con ong mật trở về tổ, ông nhận ra rằng một con ong kiếm ăn trở về thực hiện một \"điệu nhảy lắc\" chính xác, và rằng góc độ cùng độ dài của điệu nhảy mã hóa hướng và khoảng cách của một nguồn thức ăn. Tuyên bố này ban đầu vấp phải sự hoài nghi — nhiều người thấy khó tin rằng một con côn trùng có thể truyền đạt thông tin cụ thể đến vậy — nhưng những thí nghiệm cẩn thận đã xác nhận nó, và von Frisch đã đồng nhận giải Nobel cho khám phá này vào năm 1973.\n\n**C**  Nhiều thập kỷ sau, nhà tâm lý học Irene Pepperberg đẩy câu hỏi đi xa hơn với một con vẹt xám châu Phi duy nhất tên là Alex. Trong hơn ba mươi năm, Alex đã học cách sử dụng những nhãn tiếng Anh nói cho các vật thể, màu sắc và hình dạng, và thậm chí có thể nhận diện những số lượng nhỏ. Pepperberg lập luận rằng con chim không chỉ đơn thuần bắt chước âm thanh mà còn gắn chúng với các khái niệm — sử dụng các từ ngữ, theo một nghĩa hạn chế nhưng có thật, để gọi tên thế giới.\n\n**D**  Nhà sinh học Con Slobodchikoff tìm thấy sự tinh vi tương đương ở một con vật khó ngờ tới: con cầy thảo nguyên. Bằng cách ghi âm và phân tích hàng nghìn tiếng kêu báo động, ông cho thấy những loài gặm nhấm này không chỉ đơn giản phát tín hiệu \"nguy hiểm\". Những tiếng kêu của chúng dường như mã hóa loại kẻ săn mồi, kích thước của nó, và thậm chí những chi tiết như màu sắc quần áo của một con người đang đi qua — một mô tả chi tiết đến đáng kinh ngạc được nén vào một tiếng kêu ngắn ngủi.\n\n**E**  Cuối cùng, nhà nghiên cứu Katy Payne đã phát hiện ra cả một kênh giao tiếp mà con người đơn giản là đã không nhận ra. Khi nghiên cứu loài voi, bà phát hiện rằng chúng tạo ra hạ âm mạnh mẽ — những rung động quá thấp đối với tai người — có thể truyền đi nhiều kilômét khắp đồng cỏ savan, cho phép những đàn voi ở xa nhau phối hợp các chuyển động của chúng.\n\nGộp lại với nhau, công trình của những nhà nghiên cứu này gợi ý rằng khoảng cách giữa giao tiếp của con người và động vật có thể hẹp hơn so với từng được tin tưởng. Bao nhiêu ý nghĩa thực sự truyền đi giữa các loài động vật thì vẫn còn được tranh luận, nhưng bức tranh cũ về phản xạ vô thức đã biến mất vĩnh viễn.","practice_support":{"schema_version":1,"source_sha256":"86da4d273f29e5254f3c2df8337581ad80239efe7d392a492dcb386f3e99f55b","translation_sha256":"5ad51e380e113ca6b3628cdfcd16dd896f90ce9eb901b4961d5acbac1590e727","units":[],"illustrations":[],"question_evidence":{"4":{"question_sha256":"205dd69c545d5b0f30466dbc52786b78aecda3f5ab9c02e150ce670fce3f8ca8","source":"Alex learned to use spoken English labels for objects, colours and shapes","precision":"quote","illustrations":[]},"5":{"question_sha256":"729da4e364645e3eefd1de6df34cba2d6e0d5c9909bd64283cd603706bf8911b","source":"the angle and length of the dance encode the direction and distance of a food source","precision":"quote","illustrations":[]},"6":{"question_sha256":"fa129e5849f7bb89142696d2d60f66af245f96791f0243ec5d076be0bc9a309e","source":"vibrations too low for the human ear","precision":"quote","illustrations":[]},"7":{"question_sha256":"f4ece9a05d216b1339716c79e70fb3bcbaadc7d8191532e7bfad6a7ab8fae19b","source":"biologists were reluctant to credit animals with anything resembling true, structured communication","precision":"quote","illustrations":[]},"8":{"question_sha256":"fb3c3571f47ac9263c7f4c7a6925f28c842895dc5e037dfadc6369fc6ea67337","source":"the gap between human and animal communication may be narrower than once believed","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"reluctant","definition":"ngần ngại, không sẵn lòng tin hoặc chấp nhận","example":"A For much of the twentieth century, biologists were reluctant to credit animals with anything resembling true, structured communication.","aliases":[]},{"term":"reflexes","definition":"các phản xạ tự động","example":"Calls, songs and gestures were treated as simple reflexes — automatic responses to hunger or fear, not messages carrying meaning.","aliases":[]},{"term":"encode","definition":"mã hoá, thể hiện thông tin bằng tín hiệu","example":"Watching honeybees return to the hive, he realised that a returning forager performs a precise \"waggle dance\", and that the angle and length of the dance encode the direction and distance of a food source.","aliases":[]},{"term":"scepticism","definition":"sự hoài nghi","example":"The claim was initially met with scepticism — many found it hard to believe an insect could pass on such specific information — but careful experiments confirmed it, and von Frisch shared a Nobel Prize for the discovery in 1973.","aliases":[]},{"term":"infrasound","definition":"hạ âm, âm thanh có tần số thấp hơn ngưỡng nghe của con người","example":"Studying elephants, she discovered that they produce powerful infrasound — vibrations too low for the human ear — which can travel for kilometres across the savannah, allowing distant herds to coordinate their movements.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["science","animals"],"skill_focus":"scanning","word_count":null,"estimated_minutes":11},{"id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","slug":"matching-explorers-and-discoveries","title":"Matching — Explorers and Their Discoveries","library":"l2_skill","status":"published","body_markdown":"**A**  Almost a hundred years before European sailors began their famous voyages, a Chinese admiral named Zheng He was already crossing the seas. Between 1405 and 1433 he led seven great expeditions across the Indian Ocean, reaching India, Arabia and East Africa. His fleets were enormous — hundreds of ships carrying thousands of sailors — far larger than anything Europe could build at the time.\n\n**B**  In 1519 the Portuguese captain Ferdinand Magellan set sail from Spain with five small ships, hoping to reach Asia by travelling west. Magellan himself never finished it: he was killed in a battle in the Philippines in 1521. Yet his surviving crew sailed on, and by the time a single battered ship returned home in 1522, they had completed the first voyage in history to travel all the way around the world.\n\n**C**  Not all explorers travelled by sea. In the 1300s, a young man called Ibn Battuta left Morocco and spent around thirty years journeying across Africa, the Middle East, India and China. When he returned, he dictated a famous book describing the lands, peoples and customs he had seen, and it is still read by historians today.\n\n**D**  Centuries later, the great unknown was no longer the ocean but the frozen ends of the Earth. In December 1911, Norwegian explorer Roald Amundsen and four companions became the first people ever to stand at the South Pole, the planet's most southern point.","metadata":{"grammar_focus":[{"tip":"Trong bài lịch sử, past perfect báo hiệu trình tự thời gian — phân biệt 'việc nào xảy ra trước' khi làm matching/ordering.","point":"Quá khứ hoàn thành (past perfect) diễn tả việc hoàn tất trước một mốc quá khứ","review":"Past perfect: had + V3, dùng cho việc xảy ra/hoàn tất trước một mốc quá khứ khác (thường đi cùng quá khứ đơn).","example":"By the time a single battered ship returned home in 1522, they **had completed** the first voyage in history to travel all the way around the world.","analysis":"'had completed' = past perfect (had + V3) diễn tả hành động hoàn tất TÍNH ĐẾN mốc quá khứ 'returned' (quá khứ đơn), được đánh dấu rõ bằng 'by the time'. Past perfect nhấn mạnh kết quả đã đạt được tính đến mốc quá khứ đó."},{"tip":"Bị động che giấu chủ thể → câu hỏi 'ai đã làm gì' dễ thành NOT GIVEN nếu bài không nêu 'by ai'.","point":"Bị động quá khứ đơn không nêu tác nhân (was + V3)","review":"Bị động quá khứ đơn: S + was/were + V3 (+ by O). Lược 'by…' khi tác nhân không cần thiết.","example":"Magellan himself never finished it: he **was killed** in a battle in the Philippines in 1521.","analysis":"'was killed' = bị động quá khứ đơn (was + V3 'killed'); tác nhân (ai giết) bị lược bỏ vì không rõ/không quan trọng, trọng tâm là điều xảy ra với Magellan. Đối lập với mệnh đề chủ động 'never finished' ngay trước."},{"tip":"'the first … to …' thường gắn với một thành tựu độc nhất — chính là chi tiết hay được hỏi trong matching (đáp án iii 'reached the southernmost point').","point":"Cấu trúc 'the first … to + V' (to-infinitive sau số thứ tự/so sánh nhất)","review":"the first/only/last + N + to-infinitive: dùng to + V bổ nghĩa cho danh từ đứng sau số thứ tự hoặc so sánh nhất.","example":"Roald Amundsen and four companions became **the first people ever to stand** at the South Pole","analysis":"Sau cụm 'the first people' dùng to-infinitive 'to stand' để bổ nghĩa, chỉ hành động mà họ là những người đầu tiên thực hiện. Mẫu 'the first/last/only/best + N + to + V' rất phổ biến."}],"translation_vi":"**A**  Gần một trăm năm trước khi các thủy thủ châu Âu bắt đầu những chuyến hải hành nổi tiếng của họ, một đô đốc người Trung Quốc tên là Zheng He đã vượt biển. Giữa năm 1405 và 1433, ông dẫn đầu bảy cuộc viễn chinh lớn qua Ấn Độ Dương, đến tận Ấn Độ, Ả Rập và Đông Phi. Hạm đội của ông khổng lồ — hàng trăm con tàu chở hàng nghìn thủy thủ — lớn hơn nhiều so với bất cứ thứ gì mà châu Âu có thể đóng vào thời đó.\n\n**B**  Năm 1519, thuyền trưởng người Bồ Đào Nha Ferdinand Magellan giương buồm rời Tây Ban Nha với năm con tàu nhỏ, hy vọng đến châu Á bằng cách đi về phía tây. Bản thân Magellan không bao giờ hoàn thành nó: ông bị giết trong một trận chiến ở Philippines vào năm 1521. Thế nhưng đoàn thủy thủ còn sống sót vẫn tiếp tục giương buồm, và đến khi một con tàu duy nhất rách nát trở về quê hương vào năm 1522, họ đã hoàn thành chuyến hải hành đầu tiên trong lịch sử đi vòng quanh toàn thế giới.\n\n**C**  Không phải tất cả các nhà thám hiểm đều đi bằng đường biển. Vào những năm 1300, một thanh niên tên là Ibn Battuta rời Morocco và dành khoảng ba mươi năm rong ruổi khắp châu Phi, Trung Đông, Ấn Độ và Trung Quốc. Khi trở về, ông đọc cho người khác chép lại một cuốn sách nổi tiếng mô tả các vùng đất, dân tộc và phong tục mà ông đã thấy, và nó vẫn được các nhà sử học đọc cho đến ngày nay.\n\n**D**  Nhiều thế kỷ sau, vùng đất chưa được biết đến lớn lao không còn là đại dương mà là những vùng đầu cực băng giá của Trái Đất. Vào tháng 12 năm 1911, nhà thám hiểm người Na Uy Roald Amundsen và bốn người đồng hành trở thành những người đầu tiên từng đứng tại Nam Cực, điểm cực nam nhất trên hành tinh.","practice_support":{"schema_version":1,"source_sha256":"05a4bf2c2887d55aae229d0931a389d45276ee9939fb813f6f2ce01ef1bf1c2e","translation_sha256":"d779c8c0b3d722fbd24ba6575aad64e042614e30e376e5b9491d532f7a377ce5","units":[],"illustrations":[],"question_evidence":{"5":{"question_sha256":"2deaf377c73b38f4ac58ae202d8c678494381d9932c2c4a36679cf7c516219e9","source":"far larger than anything Europe could build at the time","precision":"quote","illustrations":[]},"6":{"question_sha256":"edc96b4a34571678ef6b5514225dd05bd8cf9aac4139d2693f1865263377bdfb","source":"completed the first voyage in history to travel all the way around the world","precision":"quote","illustrations":[]},"7":{"question_sha256":"d0830f886b659e8f2c5a1e8c12e476c5de1741051381ca0679f3e24b3f2c067e","source":"became the first people ever to stand at the South Pole","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"admiral","definition":"đô đốc","example":"A Almost a hundred years before European sailors began their famous voyages, a Chinese admiral named Zheng He was already crossing the seas.","aliases":[]},{"term":"expeditions","definition":"các chuyến thám hiểm","example":"Between 1405 and 1433 he led seven great expeditions across the Indian Ocean, reaching India, Arabia and East Africa.","aliases":[]},{"term":"fleets","definition":"các đội tàu","example":"His fleets were enormous — hundreds of ships carrying thousands of sailors — far larger than anything Europe could build at the time.","aliases":[]},{"term":"surviving crew","definition":"những thành viên thủy thủ đoàn còn sống","example":"Yet his surviving crew sailed on, and by the time a single battered ship returned home in 1522, they had completed the first voyage in history to travel all the way around the world.","aliases":[]},{"term":"dictated","definition":"đọc để người khác ghi lại","example":"When he returned, he dictated a famous book describing the lands, peoples and customs he had seen, and it is still read by historians today.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["history","geography"],"skill_focus":"scanning","word_count":null,"estimated_minutes":9},{"id":"136fda06-cba5-4e1a-881d-bc821f0312ff","slug":"matching-explorers-of-the-sea","title":"Matching — Explorers of the Sea","library":"l2_skill","status":"published","body_markdown":"**A**  Long before reliable maps or satellites, brave sailors set out across the open sea\nwith little idea of what lay ahead. Some went in search of new land, some sought riches,\nand some simply wanted to know how large the world really was. Three of the most famous\nexplorers of the sea lived in very different times and places.\n\n**B**  In the early fifteenth century, the Chinese admiral Zheng He commanded a huge\nfleet of \"treasure ships\" for the emperor of China. These ships were among the largest\nwooden vessels ever built, and they carried silk, gold and gifts to build friendship\nwith faraway kingdoms across Asia and Africa. Rather than conquer, Zheng He aimed to\nshow the strength and wealth of his country.\n\n**C**  A century later, the Portuguese explorer Ferdinand Magellan set off in 1519 with a\nbold plan: to sail around the entire world. The voyage took about 1,080 days and was\nextremely dangerous. Magellan himself was killed before the journey was over, and only a\nfew of his crew came home. Yet the ships he had started became the first fleet ever to\nsail right around the world, proving that the Earth was round so that later sailors no\nlonger feared falling off its edge.\n\n**D**  Nearly two and a half centuries after that, the British captain James Cook sailed\ninto the Pacific Ocean. He was a skilled map-maker, and he drew careful maps of the\ncoasts of New Zealand and eastern Australia. Cook's work was so careful that many of his\nmaps were still used years after his death, helping later sailors cross these waters in\nsafety.","metadata":{"grammar_focus":[{"tip":"Cụm 'the largest/first … ever built' báo hiệu một kỷ lục hay 'cái đầu tiên' — chính là chỗ ra câu hỏi matching features về thành tựu nổi bật.","point":"Bị động hoàn thành (have/had been + V3) tả thành tựu","review":"Bị động hoàn thành: have/had been + V3. Có thể rút gọn thành cụm phân từ '(ever) built/made' đứng sau danh từ.","example":"These ships were among the largest wooden vessels **ever built**.","analysis":"'ever built' là cụm phân từ quá khứ rút gọn từ bị động hoàn thành (= that had ever been built), bổ nghĩa cho 'vessels'. 'ever' nhấn mạnh phạm vi 'từ trước tới nay'. Cụm 'among the largest' là so sánh nhất chỉ một trong những thứ lớn nhất."},{"tip":"Phần sau 'proving/leading/making…' thường chứa hệ quả quan trọng — bám vào đây để trả lời câu hỏi 'tại sao/kết quả là gì' (matching information).","point":"Cụm phân từ chỉ kết quả (V-ing) ở cuối câu","review":"Cụm phân từ V-ing đặt sau dấu phẩy ở cuối câu để nêu kết quả/hệ quả của hành động chính (= and this + V).","example":"the ships he had started became the first fleet ever to sail right around the world, **proving** that the Earth was round","analysis":"'proving that…' là cụm phân từ hiện tại rút gọn nêu hệ quả của mệnh đề chính (= and this proved that…). Chủ ngữ ngầm của 'proving' là cả sự việc đi vòng quanh thế giới. 'the first … to sail' dùng to-infinitive sau so sánh nhất."},{"tip":"'so…that…' nối nguyên nhân (mức độ) với kết quả trong cùng câu — chi tiết được hỏi thường nằm ở vế sau 'that'.","point":"Cấu trúc kết quả 'so + tính từ + that'","review":"so + adj + that + clause = quá… đến nỗi… Vế sau 'that' luôn là một mệnh đề đầy đủ (S + V).","example":"Cook's work was **so careful that** many of his maps were still used years after his death.","analysis":"'so + tính từ (careful) + that + mệnh đề' diễn tả mức độ cao dẫn tới kết quả. Vế sau 'that' là mệnh đề bị động 'many of his maps were still used' nêu hệ quả của sự tỉ mỉ. 'years after his death' là cụm trạng ngữ thời gian."}],"translation_vi":"**A**  Rất lâu trước khi có bản đồ đáng tin cậy hay vệ tinh, những thủy thủ dũng cảm đã giương buồm ra biển khơi mà gần như không biết điều gì đang chờ phía trước. Một số người đi tìm vùng đất mới, một số tìm của cải, và một số chỉ đơn giản muốn biết thế giới rộng lớn đến đâu. Ba trong số những nhà thám hiểm biển nổi tiếng nhất đã sống ở những thời đại và những vùng đất rất khác nhau.\n\n**B**  Vào đầu thế kỷ mười lăm, nhà đô đốc người Trung Quốc Zheng He đã chỉ huy một hạm đội khổng lồ gồm những \"tàu báu vật\" cho hoàng đế Trung Hoa. Những con tàu này nằm trong số những con tàu bằng gỗ lớn nhất từng được đóng, và chúng chở theo lụa, vàng và quà tặng để gây dựng tình hữu nghị với những vương quốc xa xôi khắp châu Á và châu Phi. Thay vì chinh phục, Zheng He tìm cách thể hiện sức mạnh và sự giàu có của đất nước mình.\n\n**C**  Một thế kỷ sau, nhà thám hiểm người Bồ Đào Nha Ferdinand Magellan khởi hành vào năm 1519 với một kế hoạch táo bạo: đi vòng quanh toàn bộ thế giới. Chuyến đi kéo dài khoảng 1.080 ngày và vô cùng nguy hiểm. Bản thân Magellan bị giết trước khi hành trình kết thúc, và chỉ một số ít thủy thủ của ông trở về nhà. Tuy nhiên, những con tàu mà ông khởi xướng đã trở thành hạm đội đầu tiên đi vòng quanh thế giới, chứng minh rằng Trái Đất hình tròn để các thủy thủ về sau không còn sợ rơi khỏi rìa của nó.\n\n**D**  Gần hai thế kỷ rưỡi sau đó, thuyền trưởng người Anh James Cook giương buồm vào Thái Bình Dương. Ông là một nhà vẽ bản đồ lành nghề, và ông đã vẽ những tấm bản đồ cẩn thận về bờ biển New Zealand và miền đông Australia. Công trình của Cook tỉ mỉ đến mức nhiều tấm bản đồ của ông vẫn còn được sử dụng nhiều năm sau khi ông qua đời, giúp những thủy thủ về sau đi qua những vùng nước này một cách an toàn.","practice_support":{"schema_version":1,"source_sha256":"8398370dc52b81a8c0b2f262901eec8e4456d49cdcbdf8065149613abee5a1b2","translation_sha256":"753dfd27f60c520755f6ae5d6a0a7aa6bb1ee1f8d339f3a5c78200a3c0640663","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"278201b4199055430331dd99f7c2364995c3c01f3b6a1ea8b33e5e16767f094c","source":"Magellan himself was killed before the journey was over","precision":"quote","illustrations":[]},"2":{"question_sha256":"919a62d7c6190657c37ee7448b182e24f49103f92f1b2e5216c45e689c974c44","source":"they carried silk, gold and gifts to build friendship","precision":"quote","illustrations":[]},"3":{"question_sha256":"9e545333f820265a945e9c94435ac9c3bb71a431aae3b7817b58871a7278918f","source":"many of his maps were still used years after his death","precision":"quote","illustrations":[]},"4":{"question_sha256":"0b64afec1e399b52bfbbce72b47cdb5f80315f122dd3be5da02402cea1f66647","source":"only a few of his crew came home","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"reliable","definition":"đáng tin cậy","example":"A Long before reliable maps or satellites, brave sailors set out across the open sea with little idea of what lay ahead.","aliases":[]},{"term":"fleet","definition":"đội tàu","example":"B In the early fifteenth century, the Chinese admiral Zheng He commanded a huge fleet of \"treasure ships\" for the emperor of China.","aliases":[]},{"term":"vessels","definition":"tàu thuyền","example":"These ships were among the largest wooden vessels ever built, and they carried silk, gold and gifts to build friendship with faraway kingdoms across Asia and Africa.","aliases":[]},{"term":"conquer","definition":"chinh phục bằng vũ lực","example":"Rather than conquer, Zheng He aimed to show the strength and wealth of his country.","aliases":[]},{"term":"coasts","definition":"các vùng bờ biển","example":"He was a skilled map-maker, and he drew careful maps of the coasts of New Zealand and eastern Australia.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["history"],"skill_focus":"detail","word_count":null,"estimated_minutes":9},{"id":"91b89f32-5d37-4408-924b-392a904cbd3a","slug":"matching-famous-architects","title":"Matching — Three Famous Architects","library":"l2_skill","status":"published","body_markdown":"**A** A building can be a purely practical thing — four walls and a roof. Yet sometimes\nan architect turns those walls into something closer to a sculpture that can be walked\ninside. Three figures, working in very different times and places, show how far bold\ndesigners can stretch the idea of what a structure should look like.\n\n**B** Antoni Gaudí worked in Barcelona in the late nineteenth and early twentieth\ncenturies. He drew his flowing curves from plants, shells and skeletons, so that his\nbuildings look almost grown rather than built. His great church, the Sagrada Família,\nwith its spires rising like stone stalagmites, remains incomplete more than a century\nafter work began, and today's craftsmen still follow his designs.\n\n**C** Across the Atlantic, the American architect Frank Lloyd Wright pursued a very\ndifferent idea. Rather than reaching for the sky, many of his homes stretch low across\nthe landscape in long, level lines that seem to grow out of the ground. He called this\napproach organic architecture, believing a structure should blend with its setting\ninstead of imposing on it. His prairie houses, hugging the earth, are still among his\nbest-known work.\n\n**D** Closer to our own time, the British-Iraqi architect Zaha Hadid pushed form even\nfurther. Her buildings curve and flow in ways earlier builders could not have raised;\nit was only with new computer tools that such sweeping shapes became possible. In 2004\nshe became the first woman to win the field's most respected award, the Pritzker Prize,\nopening up a profession long dominated by men.\n\n**E** All three designers were mocked at some point. Gaudí's curves were called bizarre,\nWright's low roofs were thought strange, and Hadid's forms were dismissed by some as\nimpractical. It took time for the public to catch up with their vision.\n\n**F** What bound them was not a shared style — their styles could not be more different\n— but a willingness to treat a building as a question to be answered freshly, rather\nthan a pattern to be copied. Exactly how much each changed architecture is still\ndebated, but their influence is hard to overlook.","metadata":{"grammar_focus":[{"tip":"'so that' nối nguyên nhân với đặc điểm nổi bật của công trình — chính đặc điểm này (look almost grown) là cụm cần đối chiếu khi làm matching features.","point":"Mệnh đề trạng ngữ chỉ kết quả với 'so that'","review":"so that + S + V = khiến cho/để cho (kết quả hoặc mục đích). rather than + N/V3 = thay vì, dùng để tương phản hai lựa chọn.","example":"He drew his flowing curves from plants, shells and skeletons, **so that his buildings look almost grown** rather than built","analysis":"'so that his buildings look almost grown rather than built' là mệnh đề trạng ngữ chỉ kết quả (= đến mức/khiến cho các công trình trông như được mọc lên). 'rather than built' đối lập hai phân từ 'grown' >< 'built'. Danh sách 'plants, shells and skeletons' là cấu trúc song song."},{"tip":"Câu chẻ 'It was only with X that…' nhấn mạnh điều kiện then chốt — chi tiết bị làm nổi bật này (công cụ máy tính) thường là chìa khóa cho matching features về Hadid.","point":"Cleft sentence nhấn mạnh với 'It was only with … that'","review":"Câu chẻ: It is/was + [phần nhấn mạnh] + that + [phần còn lại]. Dùng để làm nổi bật một thành phần (chủ ngữ, trạng ngữ, tân ngữ).","example":"**it was only with new computer tools that** such sweeping shapes became possible","analysis":"Đây là câu chẻ (cleft) nhấn mạnh trạng ngữ: 'It was only with new computer tools' tách phần nhấn mạnh ra trước 'that', làm nổi bật điều kiện. Phần còn lại 'such sweeping shapes became possible' là mệnh đề bổ sung sau 'that'. 'only' tăng cường sự nhấn mạnh."},{"tip":"Cụm 'could not be more different' khẳng định sự khác biệt tuyệt đối — hữu ích cho câu hỏi True/False về việc ba kiến trúc sư có 'cùng phong cách' hay không (sẽ là FALSE).","point":"So sánh phủ định cực cấp (could not be more + adj)","review":"could not be + more + adj = không thể… hơn được nữa (= cực kỳ). What + S + V + be… là dạng câu chẻ giả (pseudo-cleft) nhấn mạnh.","example":"What bound them was not a shared style — **their styles could not be more different** — but a willingness to treat a building as a question","analysis":"'their styles could not be more different' là so sánh phủ định mang nghĩa cực cấp (= khác nhau đến mức tột cùng), chèn giữa hai dấu gạch ngang. Câu dùng cấu trúc chẻ 'What bound them was…' kết hợp cặp tương phản 'not … but …' (không phải… mà là…)."}],"translation_vi":"**A** Một tòa nhà có thể là một thứ thuần túy thực dụng — bốn bức tường và một mái che. Thế nhưng đôi khi một kiến trúc sư biến những bức tường ấy thành một thứ gần với một tác phẩm điêu khắc mà ta có thể bước vào trong. Ba nhân vật, làm việc ở những thời điểm và nơi chốn rất khác nhau, cho thấy những nhà thiết kế táo bạo có thể nới rộng đến đâu ý niệm về việc một công trình nên trông như thế nào.\n\n**B** Antoni Gaudí làm việc ở Barcelona vào cuối thế kỷ mười chín và đầu thế kỷ hai mươi. Ông rút những đường cong uốn lượn của mình từ cây cối, vỏ sò và bộ xương, để các công trình của ông trông như được mọc lên hơn là được xây dựng. Nhà thờ vĩ đại của ông, Sagrada Família, với những tháp nhọn vươn cao tựa măng đá, vẫn còn dang dở hơn một thế kỷ sau khi công việc bắt đầu, và những người thợ ngày nay vẫn tiếp tục theo các thiết kế của ông.\n\n**C** Bên kia Đại Tây Dương, kiến trúc sư người Mỹ Frank Lloyd Wright theo đuổi một ý tưởng rất khác. Thay vì vươn lên trời, nhiều ngôi nhà của ông trải dài thấp ngang qua phong cảnh bằng những đường dài, bằng phẳng dường như mọc ra từ mặt đất. Ông gọi cách tiếp cận này là kiến trúc hữu cơ, tin rằng một công trình phải hòa hợp với khung cảnh quanh nó thay vì áp đặt lên nó. Những ngôi nhà thảo nguyên của ông, ẩn mình sát mặt đất, vẫn là một trong những công trình nổi tiếng nhất của ông.\n\n**D** Gần thời chúng ta hơn, kiến trúc sư người Anh gốc Iraq Zaha Hadid đẩy hình khối đi xa hơn nữa. Các công trình của bà uốn lượn và trôi chảy theo những cách mà những người thợ trước đó hẳn không thể nào dựng nổi; chỉ với những công cụ máy tính mới mà những hình dạng quét rộng như vậy mới trở nên khả thi. Năm 2004, bà trở thành người phụ nữ đầu tiên giành được giải thưởng được kính trọng nhất trong lĩnh vực này, giải Pritzker, mở ra một nghề nghiệp vốn từ lâu do nam giới thống trị.\n\n**E** Cả ba nhà thiết kế đều bị chế giễu vào một thời điểm nào đó. Những đường cong của Gaudí bị gọi là kỳ quặc, những mái nhà thấp của Wright bị coi là lạ lùng, và những hình khối của Hadid bị một số người chê là phi thực tế. Phải mất thời gian thì công chúng mới đuổi kịp tầm nhìn của họ.\n\n**F** Cái gắn kết họ lại không phải là một phong cách chung — phong cách của họ không thể nào khác nhau hơn được nữa — mà là sự sẵn lòng coi một tòa nhà như một câu hỏi cần được trả lời theo cách mới, thay vì một khuôn mẫu cần được sao chép. Chính xác mỗi người đã thay đổi kiến trúc đến mức nào thì vẫn còn được tranh luận, nhưng ảnh hưởng của họ thì khó có thể bị bỏ qua.","practice_support":{"schema_version":1,"source_sha256":"0925170aa8e3dc5789610478dc464f83f1f948c5d187b3a6576b86ef906fef4f","translation_sha256":"295e6079b2f7acc41b792aa4bf1bdba130c376d01f30dca9e3d2ff7494049930","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"76c35f0458fc9b8ab30e38ed77d2ce3beef0753553a07f11ef19c23289e7b33f","source":"He drew his flowing curves from plants, shells and skeletons","precision":"quote","illustrations":[]},"2":{"question_sha256":"7fac5796cfe896a0e6d7112cb750811fff632ef919d0a0f5d58189c013394744","source":"a structure should blend with its setting instead of imposing on it","precision":"quote","illustrations":[]},"3":{"question_sha256":"4f03bd3ca669a5409333765669a5bcc927cd77f3c66114e02049802fcad59c08","source":"it was only with new computer tools that such sweeping shapes became possible","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"sculpture","definition":"tác phẩm điêu khắc","example":"Yet sometimes an architect turns those walls into something closer to a sculpture that can be walked inside.","aliases":[]},{"term":"flowing curves","definition":"những đường cong mềm mại, liên tục","example":"He drew his flowing curves from plants, shells and skeletons, so that his buildings look almost grown rather than built.","aliases":[]},{"term":"craftsmen","definition":"những người thợ thủ công lành nghề","example":"His great church, the Sagrada Família, with its spires rising like stone stalagmites, remains incomplete more than a century after work began, and today's craftsmen still follow his designs.","aliases":[]},{"term":"blend with","definition":"hoà hợp với","example":"He called this approach organic architecture, believing a structure should blend with its setting instead of imposing on it.","aliases":[]},{"term":"impractical","definition":"không khả thi hoặc khó áp dụng trong thực tế","example":"Gaudí's curves were called bizarre, Wright's low roofs were thought strange, and Hadid's forms were dismissed by some as impractical.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["arts","history"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"fa34aa45-7083-495c-9c81-0a141987a9f6","slug":"matching-festivals-around-the-world","title":"Matching — Festivals around the World","library":"l2_skill","status":"published","body_markdown":"**A**  Each spring, towns across India burst into colour for the festival of Holi. Often\ncalled the festival of colours, Holi celebrates the end of winter and the victory of good\nover evil. During the festival, crowds cover one another in clouds of bright coloured\npowder and splash water, until faces and clothes turn every shade imaginable. Strangers\nand friends dance together in the streets.\n\n**B**  Months later, in autumn, another great Indian festival lights up the night. Diwali,\nthe festival of lights, lasts for several days. Families across India light rows of small\noil lamps around their homes to welcome good luck and a fresh start. People also share\nsweets, wear new clothes and set off fireworks.\n\n**C**  Across the world, in Mexico, another colourful festival honours not life but memory.\nDuring the Day of the Dead, families gather to remember relatives who have passed away.\nThey build small altars with flowers, photographs and the favourite foods of the dead.\nFar from a sad occasion, the festival is full of music, colour and stories.\n\n**D**  Perhaps the most widely celebrated festival is Chinese New Year. Its date follows\nthe moon, so it falls on a different day each year, usually in late January or February.\nFamilies gather for huge meals, hand each other lucky red envelopes, and watch energetic\ndragon dances. However different they are, these festivals all show the same thing: the\ndeep human need to come together and celebrate.","metadata":{"grammar_focus":[{"tip":"'called / known as + tên' giới thiệu biệt danh của sự vật — hữu ích để khớp đoạn trong matching ('the festival of colours' → Holi).","point":"Bị động vô nhân xưng với 'is often called' (được gọi là)","review":"Bị động: S + be + V3. Có thể rút gọn 'which is called…' thành cụm phân từ 'called…' đặt đầu câu, ngăn cách bằng dấu phẩy.","example":"Often **called** the festival of colours, Holi celebrates the end of winter.","analysis":"'Often called the festival of colours' là cụm phân từ quá khứ rút gọn từ bị động 'which is often called…', đứng đầu câu để bổ nghĩa cho chủ ngữ 'Holi'. Tác nhân (người gọi) được lược bỏ vì là cách gọi chung."},{"tip":"Cụm 'relatives who have passed away' là cách nói trang trọng của 'người đã chết' — nhận ra paraphrase này để khớp đúng đoạn (honour those who have died).","point":"Mệnh đề quan hệ xác định với 'who' + thì hiện tại hoàn thành","review":"Mệnh đề quan hệ xác định chỉ người: N + who + V…, không dấu phẩy. Hiện tại hoàn thành: have/has + V3.","example":"families gather to remember relatives **who have passed** away","analysis":"'who have passed away' là mệnh đề quan hệ xác định bổ nghĩa cho 'relatives'; 'who' làm chủ ngữ, theo sau là hiện tại hoàn thành 'have passed' (have + V3) chỉ việc đã xảy ra và còn liên quan tới hiện tại. Không có dấu phẩy vì là mệnh đề xác định."},{"tip":"'so' báo hiệu một kết quả — câu hỏi matching information ('date changes according to the moon') khớp với mệnh đề nguyên nhân trước 'so'.","point":"Mệnh đề chỉ kết quả với 'so (that)'","review":"so = vì vậy/nên (nối kết quả). Phân biệt với 'so that' = để mà (nối mục đích). 'so + adj + that' = quá… đến nỗi.","example":"Its date follows the moon, **so** it falls on a different day each year.","analysis":"Liên từ 'so' nối hai mệnh đề, mệnh đề sau nêu kết quả của mệnh đề trước: vì ngày theo mặt trăng (nguyên nhân) NÊN rơi vào ngày khác nhau mỗi năm (kết quả). Thường có dấu phẩy trước 'so'."}],"translation_vi":"**A**  Mỗi mùa xuân, các thị trấn và làng mạc khắp Ấn Độ bùng nổ sắc màu vì lễ hội Holi. Thường được gọi là lễ hội màu sắc, Holi đón mừng sự kết thúc của mùa đông và sự chiến thắng của cái thiện trước cái ác. Trong suốt lễ hội, các đám đông phủ lên nhau những đám bột màu rực rỡ và té nước vào nhau, cho đến khi khuôn mặt và quần áo của mọi người chuyển thành đủ mọi sắc màu. Người lạ và bạn bè cùng nhảy múa trên đường phố, và trong một ngày những khác biệt thường ngày dường như tan biến.\n\n**B**  Nhiều tháng sau đó, vào mùa thu, một lễ hội lớn khác của Ấn Độ thắp sáng màn đêm. Diwali, lễ hội ánh sáng, kéo dài trong vài ngày. Các gia đình trên khắp Ấn Độ thắp những hàng đèn dầu nhỏ quanh nhà của họ để chào đón sự may mắn và một khởi đầu mới. Người ta cũng chia sẻ đồ ngọt, mặc quần áo mới và đốt pháo hoa, biến cả những con phố thành những dòng sông ánh sáng lung linh.\n\n**C**  Bên kia thế giới, ở Mexico, một lễ hội đầy màu sắc khác tôn vinh không phải sự sống mà là ký ức. Trong dịp Ngày của Người chết (Day of the Dead), các gia đình tụ họp để tưởng nhớ những người thân đã qua đời. Họ dựng những bàn thờ nhỏ với hoa, ảnh và những món ăn yêu thích của người đã khuất. Khác xa với một dịp buồn bã, lễ hội này đầy âm nhạc, màu sắc và những câu chuyện, một cách vui tươi để giữ cho ký ức luôn sống mãi.\n\n**D**  Có lẽ lễ hội được tổ chức rộng rãi nhất là Tết Nguyên Đán (Chinese New Year). Ngày của nó đi theo mặt trăng, nên nó rơi vào một ngày khác nhau mỗi năm, thường là vào cuối tháng Một hoặc tháng Hai. Các gia đình quây quần bên những bữa ăn lớn, trao nhau những phong bao đỏ may mắn, và xem những điệu múa rồng đầy năng lượng trên các đường phố. Dù khác nhau đến đâu, những lễ hội này đều cho thấy một điều giống nhau: nhu cầu sâu sắc của con người được tụ họp và cùng nhau ăn mừng.","practice_support":{"schema_version":1,"source_sha256":"5cd0f95e379d054b94f19afae09bbb9312b00a36378055088094b44c63f91519","translation_sha256":"d0aee848b892a9d61f885f0af2e37bd5bc2ea132d203851a1f9d8682223997a6","units":[],"illustrations":[],"question_evidence":{"5":{"question_sha256":"e6f89e0b90171d04eb6a54449c55abcd298dee0f38d5131caf18fc52a28c45b6","source":"crowds cover one another in clouds of bright coloured powder and splash water","precision":"quote","illustrations":[]},"6":{"question_sha256":"b41602b1da5a1155e77d364e60c891c97c417f7f79e32308f1599373af719706","source":"light rows of small oil lamps around their homes to welcome good luck","precision":"quote","illustrations":[]},"7":{"question_sha256":"af924bf611f8ab21310cd62f9efba5691c6be84fa2329ef602881974a0b82491","source":"families gather to remember relatives who have passed away","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"powder","definition":"bột","example":"During the festival, crowds cover one another in clouds of bright coloured powder and splash water, until faces and clothes turn every shade imaginable.","aliases":[]},{"term":"oil lamps","definition":"đèn dầu","example":"Families across India light rows of small oil lamps around their homes to welcome good luck and a fresh start.","aliases":[]},{"term":"passed away","definition":"đã qua đời","example":"During the Day of the Dead, families gather to remember relatives who have passed away.","aliases":[]},{"term":"altars","definition":"bàn thờ","example":"They build small altars with flowers, photographs and the favourite foods of the dead.","aliases":[]},{"term":"envelopes","definition":"phong bì","example":"Families gather for huge meals, hand each other lucky red envelopes, and watch energetic dragon dances.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["culture","social-sciences"],"skill_focus":"scanning","word_count":null,"estimated_minutes":9},{"id":"fe692d52-7c82-4e24-b983-2dfacf506795","slug":"matching-great-scientists","title":"Matching — Four Great Scientists","library":"l2_skill","status":"published","body_markdown":"**A** A short list of scientists turns up again and again in classrooms, on banknotes and in the names of units and craters. Picking four of them does not settle who mattered most, but it does show how differently great discoveries can be made — by sudden insight, by patient collecting, or by stubborn pattern-hunting.\n\n**B** The earliest of the four, the Englishman Isaac Newton, worked in the late seventeenth century. His law of universal gravitation linked things that had seemed unrelated: the fall of an apple and the orbits of the planets obeyed, he argued, a single rule. He also showed that white light splits into colours, founding much of modern optics, though he guarded his findings jealously and quarrelled with rivals.\n\n**C** Almost two centuries later, the naturalist Charles Darwin took the opposite path. Rather than a flash of insight, his great idea grew from roughly twenty years of careful observation of finches, barnacles and farm animals. Only when a younger naturalist reached a similar conclusion did Darwin finally publish his account of natural selection, a theory that reorganised the whole of biology.\n\n**D** The Polish-born physicist Marie Curie pushed into stranger territory still. Studying the faint rays given off by certain minerals, she and her collaborators identified new radioactive elements, coining the term radioactivity itself. She remains a rare figure honoured with Nobel Prizes in two distinct sciences, physics and chemistry, won years apart and at real cost to her health.\n\n**E** The Russian chemist Dmitri Mendeleev brought order to a different kind of chaos. Laying out the known elements by weight and behaviour, he noticed a repeating pattern and left deliberate gaps where no element was yet known. When substances later turned up that fitted those gaps almost exactly, his periodic table moved from a clever guess to a foundation of chemistry.\n\n**F** Set side by side, these four scientists share little in method or temperament. What they have in common is that each found a hidden order beneath the surface of things — and how much of that order was waiting to be seen, rather than invented, is a question philosophers still find hard to close.","metadata":{"grammar_focus":[{"tip":"Cụm '-ing, …' đầu câu phải có chủ ngữ trùng mệnh đề chính; trong matching, hành động trong cụm phân từ thường là 'thành tựu' cần khớp với nhân vật.","point":"Cụm phân từ hiện tại đầu câu (present participle clause) chỉ cách thức","review":"Present participle clause đầu câu (V-ing, …) = mệnh đề rút gọn cùng chủ ngữ, diễn tả hành động đồng thời, lý do hoặc cách thức.","example":"**Laying out** the known elements by weight and behaviour, he noticed a repeating pattern","analysis":"'Laying out the known elements…' là cụm phân từ hiện tại '-ing' đầu câu, chủ ngữ logic là 'he' của mệnh đề chính. Nó rút gọn từ 'While/By laying out…', diễn tả hành động đồng thời/cách thức dẫn đến việc 'he noticed'."},{"tip":"Danh từ + V3 ngay sau (không có 'be') = mệnh đề quan hệ rút gọn bị động → khôi phục 'which is/are' để dịch đúng.","point":"Mệnh đề quan hệ rút gọn quá khứ (reduced relative, past participle)","review":"Mệnh đề quan hệ rút gọn: N + V3 (= which is/are + V3, nghĩa bị động). 'given off' = bị/được phát ra.","example":"Studying the faint rays **given off by** certain minerals, she and her collaborators identified new radioactive elements","analysis":"'given off by certain minerals' là mệnh đề quan hệ rút gọn bị động (= rays that were given off by…), bổ nghĩa cho 'rays'. Đồng thời cả cụm 'Studying the faint rays…' lại là một participle clause chủ động đầu câu. Hai lớp rút gọn trong một câu."},{"tip":"Các từ tăng cường so sánh (even, far, still, much) là tín hiệu mức độ — chú ý khi câu hỏi diễn đạt lại bằng cấp độ mạnh/yếu khác.","point":"So sánh hơn nhấn mạnh với 'still' đặt sau","review":"So sánh hơn: tính từ ngắn + -er. 'even/still/far + comparative' = nhấn mạnh mức chênh lệch ('even stranger', 'far more').","example":"The Polish-born physicist Marie Curie pushed into **stranger territory still**.","analysis":"'stranger' là so sánh hơn của 'strange' (tính từ ngắn + -er); 'still' đặt sau danh từ để nhấn mạnh mức độ 'thậm chí còn… hơn nữa'. Trật tự 'adjective-comparative + noun + still' là cách nhấn trang trọng, tương đương 'even stranger territory'."}],"translation_vi":"**A** Một danh sách ngắn các nhà khoa học xuất hiện đi xuất hiện lại trong lớp học, trên tờ tiền giấy và trong tên của các đơn vị đo và các miệng hố. Chọn ra bốn người trong số họ không giải quyết được ai quan trọng nhất, nhưng nó cho thấy những khám phá vĩ đại có thể được thực hiện khác nhau biết bao — bằng sự thấu hiểu đột ngột, bằng sự thu thập kiên nhẫn, hoặc bằng sự săn tìm khuôn mẫu bền bỉ.\n\n**B** Người sớm nhất trong bốn người, người Anh Isaac Newton, làm việc vào cuối thế kỷ mười bảy. Định luật vạn vật hấp dẫn của ông liên kết những thứ tưởng chừng không liên quan: sự rơi của một quả táo và quỹ đạo của các hành tinh, ông lập luận, tuân theo một quy luật duy nhất. Ông cũng chứng minh rằng ánh sáng trắng tách thành các màu, đặt nền móng cho phần lớn quang học hiện đại, dù ông giữ kín những phát hiện của mình một cách ghen tị và tranh cãi với các đối thủ.\n\n**C** Gần hai thế kỷ sau, nhà tự nhiên học Charles Darwin đi con đường ngược lại. Thay vì một tia thấu hiểu, ý tưởng vĩ đại của ông lớn lên từ khoảng hai mươi năm quan sát cẩn thận về chim sẻ, hà và động vật nuôi. Chỉ khi một nhà tự nhiên học trẻ hơn đi đến một kết luận tương tự thì Darwin mới cuối cùng công bố bản trình bày của mình về chọn lọc tự nhiên, một lý thuyết đã tổ chức lại toàn bộ sinh học.\n\n**D** Nhà vật lý sinh ra ở Ba Lan Marie Curie tiến vào lãnh địa còn lạ lùng hơn nữa. Nghiên cứu những tia mờ nhạt phát ra từ một số khoáng chất, bà và các cộng sự đã xác định những nguyên tố phóng xạ mới, đặt ra chính thuật ngữ phóng xạ (radioactivity). Bà vẫn là một nhân vật hiếm hoi được vinh danh với giải Nobel ở hai ngành khoa học riêng biệt, vật lý và hóa học, giành được cách nhau nhiều năm và phải trả giá thực sự bằng sức khỏe của mình.\n\n**E** Nhà hóa học người Nga Dmitri Mendeleev mang trật tự đến cho một loại hỗn loạn khác. Sắp xếp các nguyên tố đã biết theo khối lượng và tính chất, ông nhận thấy một khuôn mẫu lặp lại và để lại những khoảng trống có chủ ý ở nơi chưa có nguyên tố nào được biết đến. Khi những chất về sau xuất hiện vừa khít với những khoảng trống đó gần như chính xác, bảng tuần hoàn của ông đã chuyển từ một phỏng đoán thông minh thành một nền tảng của hóa học.\n\n**F** Đặt cạnh nhau, bốn nhà khoa học này có ít điểm chung về phương pháp hay tính khí. Điều họ có chung là mỗi người đều tìm thấy một trật tự ẩn bên dưới bề mặt của sự vật — và bao nhiêu phần của trật tự ấy đang chờ được nhìn thấy, thay vì được sáng tạo ra, là một câu hỏi mà các nhà triết học vẫn thấy khó khép lại.","practice_support":{"schema_version":1,"source_sha256":"e7e7481f57d1553e1e2c036e35b3f3ac96d8b40ee4142a74a531dd070be02d8c","translation_sha256":"4f5487815d982bbbd383039ad1215ca2d1b6d81620e3e4b0e21b8e2f8855a64e","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"012b3b99aaa296f9ff2021d178864dfe70223ed061fa93a82f7700a87734e1d1","source":"left deliberate gaps where no element was yet known","precision":"quote","illustrations":[]},"2":{"question_sha256":"e0863e3e5a6b3fc8bf65532d7b1638cf44a628951385cafdab0e017b6e4c1fda","source":"the fall of an apple and the orbits of the planets obeyed, he argued, a single rule","precision":"quote","illustrations":[]},"3":{"question_sha256":"9dd3225331e74af2b112e25ed0544a1f07c4b38eae4324dea5734adf13565732","source":"his great idea grew from roughly twenty years of careful observation","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"orbits","definition":"các quỹ đạo","example":"His law of universal gravitation linked things that had seemed unrelated: the fall of an apple and the orbits of the planets obeyed, he argued, a single rule.","aliases":[]},{"term":"natural selection","definition":"chọn lọc tự nhiên","example":"Only when a younger naturalist reached a similar conclusion did Darwin finally publish his account of natural selection, a theory that reorganised the whole of biology.","aliases":[]},{"term":"radioactive","definition":"có tính phóng xạ","example":"Studying the faint rays given off by certain minerals, she and her collaborators identified new radioactive elements, coining the term radioactivity itself.","aliases":[]},{"term":"deliberate gaps","definition":"những chỗ trống được cố ý để lại","example":"Laying out the known elements by weight and behaviour, he noticed a repeating pattern and left deliberate gaps where no element was yet known.","aliases":[]},{"term":"periodic table","definition":"bảng tuần hoàn các nguyên tố","example":"When substances later turned up that fitted those gaps almost exactly, his periodic table moved from a clever guess to a foundation of chemistry.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["science","history"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","slug":"matching-inventors-and-inventions","title":"Matching — Inventors and Their Inventions","library":"l2_skill","status":"published","body_markdown":"**A**  In December 1903, on a windy beach in North Carolina, two American brothers named\nOrville and Wilbur Wright changed the world. After years of building gliders, they\nflew the first powered aircraft that could rise into the air and be steered by a pilot.\nThe flight lasted only twelve seconds, yet within decades their machine would let\nordinary people cross distances that had once taken days.\n\n**B**  Twenty years earlier, Thomas Edison had been busy with a very different problem:\nlight. It is often said that Edison invented the electric light, but this is not quite\ntrue. Other people had already produced electric lamps; what Edison did was improve the\nearlier idea until it became cheap, safe and long-lasting enough for an ordinary home.\n\n**C**  Even before Edison's lamp, in 1876, the Scottish-born inventor Alexander Graham\nBell had built a device that could carry the sound of a human voice along a wire — the\ntelephone. Strangely, many people at first saw little use for it, treating it as a clever\ntoy rather than a serious tool.\n\n**D**  Not every great invention was carefully planned. In 1928, the British scientist\nAlexander Fleming returned from a holiday to find mould growing on a dish he had\nforgotten to clean. Around the mould, the bacteria had died. By chance, he had\ndiscovered penicillin, a medicine that could fight off the bacteria that cause\ninfections.","metadata":{"grammar_focus":[{"tip":"Cụm 'a device/medicine that could + V' mô tả công dụng phát minh — chính là chỗ ra câu hỏi matching sentence endings ('carry a human voice over a wire').","point":"Mệnh đề quan hệ xác định 'that' + modal 'could' (khả năng trong quá khứ)","review":"Mệnh đề quan hệ xác định: N + that/which + V…, không dấu phẩy. 'could' = dạng quá khứ của 'can', chỉ khả năng trong quá khứ.","example":"Bell had built a device **that could carry** the sound of a human voice along a wire","analysis":"'that could carry…' là mệnh đề quan hệ xác định bổ nghĩa cho 'a device'; 'that' làm chủ ngữ, theo sau là modal 'could + V(bare)' chỉ khả năng trong quá khứ. Không có dấu phẩy vì là mệnh đề xác định."},{"tip":"'It is often said that … but …' báo hiệu một quan niệm sai sắp bị bác bỏ — bám vế sau 'but' để lấy quan điểm thật của bài (matching paragraph C/B).","point":"Bị động vô nhân xưng để tường thuật quan điểm chung ('It is often said that…')","review":"Cấu trúc bị động vô nhân xưng: It is said/believed/thought that + S + V. Dùng để dẫn ý kiến chung, lược tác nhân.","example":"**It is often said that** Edison invented the electric light, but this is not quite true.","analysis":"'It is often said that + mệnh đề' = bị động vô nhân xưng (it + be + V3 'said' + that-clause), nêu điều người ta thường nói mà không chỉ rõ ai nói. Theo sau là 'but' nêu sự phản bác của tác giả."},{"tip":"'yet/but' đánh dấu chỗ đảo ý — thông tin quan trọng (hệ quả lớn của phát minh) thường nằm sau từ tương phản.","point":"Liên từ tương phản 'yet' nối hai mệnh đề","review":"Liên từ tương phản: but/yet nối hai mệnh đề trái ý, thường có dấu phẩy phía trước. Cấu trúc 'let + O + V(bare)' = cho phép ai làm gì.","example":"The flight lasted only twelve seconds, **yet** within a few decades their machine would let ordinary people cross distances…","analysis":"'yet' (đồng nghĩa 'but') là liên từ tương phản, nối ý đối lập: chuyến bay chỉ 12 giây (nhỏ bé) NHƯNG hệ quả lại to lớn. 'would let' = 'would' (tương lai nhìn từ quá khứ) + 'let' + tân ngữ + V(bare)."}],"translation_vi":"**A**  Vào tháng 12 năm 1903, trên một bãi biển lộng gió ở North Carolina, hai anh em người Mỹ tên là Orville và Wilbur Wright đã thay đổi thế giới. Sau nhiều năm chế tạo tàu lượn, họ đã bay chiếc máy bay có động cơ đầu tiên có thể bay lên không trung và được điều khiển bởi một phi công. Chuyến bay chỉ kéo dài mười hai giây, thế nhưng trong vòng vài thập kỷ chiếc máy của họ sẽ cho phép những người bình thường vượt qua những khoảng cách từng phải mất nhiều ngày.\n\n**B**  Hai mươi năm trước đó, Thomas Edison đã bận rộn với một vấn đề rất khác: ánh sáng. Người ta thường nói rằng Edison phát minh ra đèn điện, nhưng điều này không hẳn đúng. Những người khác đã sản xuất đèn điện rồi; điều mà Edison làm là cải tiến ý tưởng trước đó cho đến khi nó trở nên rẻ, an toàn và bền đủ lâu cho một ngôi nhà bình thường.\n\n**C**  Thậm chí trước cả đèn của Edison, vào năm 1876, nhà phát minh gốc Scotland Alexander Graham Bell đã chế tạo một thiết bị có thể truyền âm thanh của giọng nói con người dọc theo một sợi dây — chiếc điện thoại. Kỳ lạ thay, nhiều người ban đầu thấy nó ít có công dụng, coi nó như một món đồ chơi khéo léo hơn là một công cụ nghiêm túc.\n\n**D**  Không phải mọi phát minh vĩ đại đều được lên kế hoạch cẩn thận. Năm 1928, nhà khoa học người Anh Alexander Fleming đi nghỉ về thì phát hiện nấm mốc đang mọc trên một chiếc đĩa mà ông quên rửa. Xung quanh đám nấm mốc, vi khuẩn đã chết. Một cách tình cờ, ông đã phát hiện ra penicillin, một loại thuốc có thể chống lại các vi khuẩn gây nhiễm trùng.","practice_support":{"schema_version":1,"source_sha256":"64316676f9d199a980981d8e144188cceee46fb3a4c981a9423860aa7138cd21","translation_sha256":"a7c475ebd5bdce07b1b866ca0e1684fc0f458bbceac26952e1466d7f5200d534","units":[],"illustrations":[],"question_evidence":{"5":{"question_sha256":"834c737101d8019e030cf29417eb852b151739d2f2e28d8c9c21349f75d53339","source":"flew the first powered aircraft that could rise into the air and be steered by a pilot","precision":"quote","illustrations":[]},"6":{"question_sha256":"698fa93b1f42e5186cf4d9d307bf8026c503a1fef757d8c155cd240e85e62a17","source":"carry the sound of a human voice along a wire","precision":"quote","illustrations":[]},"7":{"question_sha256":"802253c4a18b3c7b7854f442975ce0d63fd7e245b4dfb70aeda42f58cd1cbebc","source":"a medicine that could fight off the bacteria that cause infections","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"gliders","definition":"tàu lượn","example":"After years of building gliders, they flew the first powered aircraft that could rise into the air and be steered by a pilot.","aliases":[]},{"term":"steered","definition":"được điều khiển hướng đi","example":"After years of building gliders, they flew the first powered aircraft that could rise into the air and be steered by a pilot.","aliases":[]},{"term":"long-lasting","definition":"bền, dùng được lâu","example":"Other people had already produced electric lamps; what Edison did was improve the earlier idea until it became cheap, safe and long-lasting enough for an ordinary home.","aliases":[]},{"term":"mould","definition":"nấm mốc","example":"In 1928, the British scientist Alexander Fleming returned from a holiday to find mould growing on a dish he had forgotten to clean.","aliases":[]},{"term":"infections","definition":"các bệnh hoặc tình trạng nhiễm trùng","example":"By chance, he had discovered penicillin, a medicine that could fight off the bacteria that cause infections.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["history","science"],"skill_focus":"scanning","word_count":null,"estimated_minutes":9},{"id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","slug":"matching-inventors-of-transport","title":"Matching — Inventors of Transport","library":"l2_skill","status":"published","body_markdown":"**A**  In 1885, the German engineer Karl Benz built what many regard as the first true\nmotor car, a three-wheeled vehicle driven by a small petrol engine. Few people trusted\nthe noisy machine at first. To prove it was reliable, his wife Bertha Benz drove it more\nthan 100 kilometres to visit her mother — the first long car journey in history.\n\n**B**  Decades earlier, the British engineer George Stephenson had turned the steam engine\ninto a practical means of transport. His famous locomotive, the Rocket, pulled carriages\nalong iron rails faster than any horse. He built some of the world's first public\nrailways, and is often called the 'Father of Railways'.\n\n**C**  On the water, the American Robert Fulton changed travel with steam. In 1807 his\nsteamboat, later known as the Clermont, carried fare-paying passengers up the Hudson\nRiver in New York. It was the first steamboat to earn a steady profit, proving that\nboats no longer needed wind or muscle to move.\n\n**D**  The bicycle, too, was transformed by a careful inventor. Earlier bicycles had one\nhuge front wheel and were dangerous to ride. In 1885 the Englishman John Kemp Starley\nbuilt the 'safety bicycle', the Rover, with two equal wheels and a chain. Far safer and\neasier to balance, it is the direct ancestor of the bicycle we ride today.","metadata":{"grammar_focus":[{"tip":"Bài kể về nhà phát minh gắn chặt với năm tháng — bám động từ quá khứ + mốc năm để định vị ai làm gì, khi nào (matching information).","point":"Quá khứ đơn với động từ bất quy tắc (built, drove, pulled)","review":"Quá khứ đơn cho sự kiện đã qua: động từ thường + -ed; động từ bất quy tắc đổi dạng (build→built, drive→drove). Hay đi với mốc thời gian (in 1885).","example":"In 1885, the German engineer Karl Benz **built** what many regard as the first true motor car.","analysis":"'built' là quá khứ đơn bất quy tắc của 'build' (build–built–built), kể một sự kiện đã hoàn tất, gắn mốc thời gian 'In 1885'. Cả bài tiểu sử dùng quá khứ đơn (drove, pulled, carried)."},{"tip":"'had + V3' + 'earlier/before' giúp xếp đúng thứ tự thời gian giữa các nhà phát minh — chú ý khi bài không kể theo trình tự năm tăng dần.","point":"Quá khứ hoàn thành (had + V3) chỉ việc xảy ra sớm hơn trong quá khứ","review":"Quá khứ hoàn thành: had + V3, chỉ hành động hoàn tất trước một thời điểm/sự kiện quá khứ khác. Hay đi với earlier, before, by then.","example":"Decades earlier, the British engineer George Stephenson **had turned** the steam engine into a practical means of transport.","analysis":"'had turned' = had + turned (V3), quá khứ hoàn thành, cho biết việc Stephenson cải tiến động cơ hơi nước xảy ra TRƯỚC mốc thời gian của Benz ở đoạn A. Cụm 'Decades earlier' đánh dấu trình tự lùi về trước."},{"tip":"Cụm so sánh 'faster/safer than…' mô tả ưu điểm của phát minh — chính là chỗ ra statement cho matching features (safer than the machines before it).","point":"So sánh hơn của tính từ + 'than'","review":"So sánh hơn tính từ ngắn: adj + -er + than (fast→faster than); tính từ dài: more + adj + than. Có thể nhấn bằng far/much + comparative.","example":"His famous locomotive, the Rocket, pulled carriages along iron rails **faster than** any horse.","analysis":"'faster than' = fast + -er + than, so sánh hơn của tính từ/trạng từ ngắn, đối chiếu tốc độ đầu máy với ngựa. Ở đoạn D còn có 'far safer than…' (far nhấn mức chênh lệch)."}],"translation_vi":"**A**  Năm 1885, kỹ sư người Đức Karl Benz đã chế tạo thứ mà nhiều người coi là chiếc ô tô thực thụ đầu tiên, một chiếc xe ba bánh chạy bằng một động cơ xăng nhỏ. Ban đầu ít ai tin tưởng cỗ máy ồn ào ấy. Để chứng minh nó đáng tin cậy, vợ của ông là Bertha Benz đã lái nó đi hơn 100 kilômét để về thăm mẹ — chuyến đi bằng ô tô đường dài đầu tiên trong lịch sử.\n\n**B**  Nhiều thập kỷ trước đó, kỹ sư người Anh George Stephenson đã biến động cơ hơi nước thành một phương tiện vận chuyển thiết thực. Đầu máy nổi tiếng của ông, chiếc Rocket, kéo những toa xe chạy trên đường ray sắt nhanh hơn bất kỳ con ngựa nào. Ông đã xây dựng một số tuyến đường sắt công cộng đầu tiên trên thế giới, và thường được gọi là \"Cha đẻ của Đường sắt\".\n\n**C**  Trên mặt nước, người Mỹ Robert Fulton đã thay đổi việc đi lại bằng hơi nước. Năm 1807, chiếc tàu hơi nước của ông, về sau được biết đến với tên Clermont, đã chở những hành khách trả tiền vé ngược dòng sông Hudson ở New York. Đó là chiếc tàu hơi nước đầu tiên thu được lợi nhuận đều đặn, chứng minh rằng tàu thuyền không còn cần gió hay sức cơ bắp để di chuyển.\n\n**D**  Chiếc xe đạp cũng được một nhà phát minh tỉ mỉ biến đổi. Những chiếc xe đạp trước đó có một bánh trước khổng lồ và rất nguy hiểm khi đi. Năm 1885, người Anh John Kemp Starley đã chế tạo chiếc \"xe đạp an toàn\", chiếc Rover, với hai bánh bằng nhau và một sợi xích. An toàn hơn nhiều và dễ giữ thăng bằng hơn, nó là tổ tiên trực tiếp của chiếc xe đạp mà chúng ta đi ngày nay.","practice_support":{"schema_version":1,"source_sha256":"068a4399f48be29b1ef4966be142443ffa2bee1ad88ece84e5ac9a5dcccb78c8","translation_sha256":"5b2e83dcf5a99ddf8a15b95415ad2c200722fb1cf92a2dbc4d82f2979f19c1ca","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"a19a9d8cda8f15953b06d1e61e078f56e0e0d4a173219b67eb0ef22659630eee","source":"with two equal wheels and a chain","precision":"quote","illustrations":[]},"2":{"question_sha256":"18f7c09a94afc7edc2f6cd39959e1176e309f66d4fab3408bfd15f769ec23ae4","source":"a three-wheeled vehicle driven by a small petrol engine","precision":"quote","illustrations":[]},"3":{"question_sha256":"f515d8d6ea5ad2a05fe9c66013fba6eb818b3db95ad685885607b6399667ce9b","source":"the first steamboat to earn a steady profit","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"petrol engine","definition":"động cơ chạy bằng xăng","example":"A In 1885, the German engineer Karl Benz built what many regard as the first true motor car, a three-wheeled vehicle driven by a small petrol engine.","aliases":[]},{"term":"locomotive","definition":"đầu máy xe lửa","example":"His famous locomotive, the Rocket, pulled carriages along iron rails faster than any horse.","aliases":[]},{"term":"fare-paying passengers","definition":"hành khách trả tiền vé","example":"In 1807 his steamboat, later known as the Clermont, carried fare-paying passengers up the Hudson River in New York.","aliases":[]},{"term":"steady profit","definition":"lợi nhuận ổn định","example":"It was the first steamboat to earn a steady profit, proving that boats no longer needed wind or muscle to move.","aliases":[]},{"term":"ancestor","definition":"mẫu tiền thân; dạng trước đó dẫn tới mẫu ngày nay","example":"Far safer and easier to balance, it is the direct ancestor of the bicycle we ride today.","aliases":[]}],"image_url":null,"difficulty_level":"foundation","topic_tags":["history","technology"],"skill_focus":"detail","word_count":null,"estimated_minutes":9},{"id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","slug":"matching-movements-in-art","title":"Matching — Four Movements in Modern Art","library":"l2_skill","status":"published","body_markdown":"**A** Walk through a museum of modern art and the rooms can feel like separate worlds: soft gardens in one, shattered guitars in the next, melting clocks beyond that, and finally great fields of dripped colour. These are not random styles but four movements, each reacting against the art that came before it and each redefining what a painting was supposed to do.\n\n**B** Impressionism arrived first, in 1870s France. Painters such as Claude Monet left the studio to work outdoors, trying to record how sunlight struck a pond or a field at one fleeting moment. Their loose, visible brushstrokes looked unfinished to many viewers, and early critics mocked them; the very word \"Impressionism\" began as an insult before the artists adopted it with pride.\n\n**C** Cubism, developed around 1908 by Pablo Picasso and Georges Braque, went further from realism. Instead of painting an object as the eye sees it from one spot, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time, so that a face or a guitar might appear front and side together. The result asked viewers to assemble the subject in their own minds.\n\n**D** Surrealism, which took shape in the 1920s around the writer André Breton, turned away from the visible world altogether. Drawing on new ideas about dreams and the unconscious mind, artists such as Salvador Dalí painted scenes that obeyed no ordinary logic — soft watches draped over branches, familiar objects placed in impossible settings — in the hope of releasing thoughts that waking reason normally keeps hidden.\n\n**E** Abstract Expressionism emerged in New York after 1945 and abandoned recognisable subjects entirely. Jackson Pollock laid huge canvases on the floor and dripped or poured paint across them, moving around the edges so that the work recorded his physical gestures rather than any object. Critics argued fiercely over whether such paintings were a serious achievement or no achievement at all.\n\n**F** Seen together, the four movements trace a steady loosening of the link between a painting and the world outside it, from Monet's pond to Pollock's bare gesture. Whether that long retreat from likeness counts as the liberation of art or the loss of something it once did well is a question that visitors, standing in those very different rooms, may still answer in different ways.","metadata":{"grammar_focus":[{"tip":"Mở bài kiểu mệnh lệnh kéo người đọc vào cảnh — thông tin định vị (matching) nằm ở chuỗi liệt kê sau dấu hai chấm.","point":"Câu mệnh lệnh + 'and' chỉ kết quả (fronting bối cảnh)","review":"Imperative + and + S will/can… = câu điều kiện ẩn (If you do X, Y happens). Liệt kê song song có thể lược động từ chung.","example":"**Walk through a museum of modern art and the rooms can feel like separate worlds**: soft gardens in one, shattered guitars in the next…","analysis":"Mệnh lệnh 'Walk…' + 'and' + mệnh đề kết quả ('the rooms can feel…') = cấu trúc 'Imperative + and + clause' thay cho 'If you walk…, the rooms will…'. Sau dấu hai chấm là chuỗi cụm danh từ song song có lược động từ (ellipsis): 'soft gardens in one, shattered guitars in the next…' (lược 'there are')."},{"tip":"Cụm '-ing' cuối câu bổ nghĩa cho cả mệnh đề trước; quy chiếu về chủ ngữ chính để không gán nhầm hành động.","point":"Mệnh đề phân từ cuối câu (-ing) chỉ mục đích/đồng thời","review":"…, V-ing… (cuối câu) = mệnh đề rút gọn cùng chủ ngữ, diễn tả hành động đồng thời/hệ quả/động cơ.","example":"Painters such as Claude Monet left the studio to work outdoors, **trying to record** how sunlight struck a pond or a field","analysis":"Cụm phân từ 'trying to record…' đứng cuối, rút gọn từ 'as they tried to record…', bổ sung động cơ cho hành động chính 'left the studio'. Bên trong lồng mệnh đề danh ngữ gián tiếp 'how sunlight struck…' làm tân ngữ của 'record'. Chủ ngữ logic = 'Painters'."},{"tip":"Cụm tương phản đầu câu (Instead of/Rather than) nêu cái KHÔNG đúng với chủ thể — bẫy matching hay lấy đúng phần này gán nhầm.","point":"Fronting cụm 'Instead of + N' đầu câu (không đảo S-V)","review":"Instead of + V-ing/N = thay vì… Fronting cụm tương phản lên đầu để nhấn mạnh sự đối lập.","example":"**Instead of painting an object as the eye sees it from one spot**, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time","analysis":"Cụm giới từ 'Instead of + V-ing' fronting (đảo lên đầu) nêu cái bị bác bỏ, tạo tương phản với mệnh đề chính. Mệnh đề chính có hai động từ song song 'broke … and showed …'. 'so that…' theo sau dẫn mệnh đề kết quả. Trật tự được đánh dấu (marked) để làm nổi sự tương phản."},{"tip":"Kết bài 'Whether… is a question' = tác giả không kết luận; trong matching information đây là đoạn 'tổng kết/để ngỏ' (đoạn F).","point":"Mệnh đề danh ngữ 'Whether A or B' làm chủ ngữ + bổ ngữ danh từ","review":"Whether A or B + is/remains a question = liệu A hay B vẫn là câu hỏi (bỏ ngỏ). Mệnh đề quan hệ tân ngữ lược 'that'.","example":"**Whether that long retreat from likeness counts as the liberation of art or the loss of something it once did well is a question** that visitors … may still answer in different ways.","analysis":"Mệnh đề danh ngữ 'Whether A or B' làm chủ ngữ của 'is'; bổ ngữ 'a question' được mệnh đề quan hệ 'that visitors… may answer' bổ nghĩa. Bên trong B còn lồng mệnh đề quan hệ rút gọn 'something [that] it once did well'. Câu nhiều tầng, bỏ ngỏ kết luận."}],"translation_vi":"Đi qua một bảo tàng nghệ thuật hiện đại, bạn có thể thấy các phòng như những thế giới riêng: vườn cây mềm mại ở phòng này, đàn ghi-ta vỡ vụn ở phòng kế, rồi đồng hồ tan chảy, và cuối cùng là những mảng màu rộng được nhỏ lên tranh. Đây là bốn trào lưu, mỗi trào lưu phản ứng với nghệ thuật đi trước và định nghĩa lại điều một bức tranh nên làm, chứ không phải những phong cách ngẫu nhiên.\n\nẤn tượng xuất hiện trước, ở Pháp vào những năm 1870. Các họa sĩ như Claude Monet rời xưởng để vẽ ngoài trời, cố ghi lại cách ánh nắng chiếu lên ao hoặc cánh đồng trong một khoảnh khắc thoáng qua. Những nét cọ tự do, lộ rõ của họ trông như chưa hoàn thiện với nhiều người xem và bị giới phê bình ban đầu chế giễu. Chính từ 'Ấn tượng' lúc đầu là lời chê bai, trước khi được các nghệ sĩ tự hào nhận làm tên gọi.\n\nLập thể, do Pablo Picasso và Georges Braque phát triển khoảng năm 1908, đi xa hơn nữa khỏi chủ nghĩa hiện thực. Thay vì vẽ một vật như mắt nhìn thấy từ một vị trí, tranh Lập thể chia nó thành những hình phẳng, góc cạnh và thể hiện đồng thời nhiều góc nhìn. Vì thế, một khuôn mặt hoặc đàn ghi-ta có thể hiện cả phía trước lẫn bên cạnh cùng lúc. Kết quả buộc người xem phải tự ráp chủ thể lại trong tâm trí.\n\nSiêu thực, hình thành vào những năm 1920 quanh nhà văn André Breton, hoàn toàn quay lưng với thế giới nhìn thấy được. Dựa vào những ý tưởng mới về giấc mơ và tâm trí vô thức, các nghệ sĩ như Salvador Dalí vẽ những cảnh không tuân theo lô-gic thông thường: đồng hồ mềm rủ trên cành cây, vật quen thuộc đặt trong bối cảnh không thể có. Họ hy vọng giải phóng những suy nghĩ mà lý trí lúc tỉnh thường che giấu.\n\nBiểu hiện Trừu tượng xuất hiện ở New York sau năm 1945 và hoàn toàn từ bỏ các chủ thể có thể nhận diện. Jackson Pollock đặt những tấm toan lớn trên sàn rồi nhỏ hoặc đổ sơn lên đó, di chuyển quanh các mép để tác phẩm ghi lại động tác cơ thể của ông thay vì một vật thể. Giới phê bình tranh cãi gay gắt rằng những bức tranh ấy là thành tựu đáng kể hay chẳng phải thành tựu gì.\n\nNhìn chung, bốn trào lưu cho thấy mối liên hệ giữa tranh và thế giới bên ngoài dần lỏng đi, từ ao của Monet đến động tác thuần túy của Pollock. Sự rời xa hình ảnh giống thực kéo dài ấy là giải phóng nghệ thuật hay đánh mất điều nghệ thuật từng làm tốt? Những khách tham quan đứng trong các phòng rất khác nhau ấy vẫn có thể trả lời khác nhau.","practice_support":{"schema_version":1,"source_sha256":"bab4b0f5457a620be683f246c4c388927ad59e09201e3dcb0755e7e9c8609904","translation_sha256":"2332790ee10a0e2f54e645b03d7c423d4e7a4b40c5b36ed0127380601395b3ff","units":[{"id":"p1-s1","source":"Walk through a museum of modern art and the rooms can feel like separate worlds: soft gardens in one, shattered guitars in the next, melting clocks beyond that, and finally great fields of dripped colour.","translation_vi":"Đi qua một bảo tàng nghệ thuật hiện đại, bạn có thể thấy các phòng như những thế giới riêng: vườn cây mềm mại ở phòng này, đàn ghi-ta vỡ vụn ở phòng kế, rồi đồng hồ tan chảy, và cuối cùng là những mảng màu rộng được nhỏ lên tranh.","precision":"sentence","phrases":[{"source":"separate worlds","target":"những thế giới riêng"},{"source":"melting clocks","target":"đồng hồ tan chảy"}]},{"id":"p1-s2","source":"These are not random styles but four movements, each reacting against the art that came before it and each redefining what a painting was supposed to do.","translation_vi":"Đây là bốn trào lưu, mỗi trào lưu phản ứng với nghệ thuật đi trước và định nghĩa lại điều một bức tranh nên làm, chứ không phải những phong cách ngẫu nhiên.","precision":"sentence","phrases":[{"source":"four movements","target":"bốn trào lưu"},{"source":"reacting against","target":"phản ứng với"}]},{"id":"p2-s1","source":"Impressionism arrived first, in 1870s France.","translation_vi":"Ấn tượng xuất hiện trước, ở Pháp vào những năm 1870.","precision":"sentence","phrases":[{"source":"Impressionism","target":"Ấn tượng"},{"source":"1870s France","target":"Pháp vào những năm 1870"}]},{"id":"p2-s2","source":"Painters such as Claude Monet left the studio to work outdoors, trying to record how sunlight struck a pond or a field at one fleeting moment.","translation_vi":"Các họa sĩ như Claude Monet rời xưởng để vẽ ngoài trời, cố ghi lại cách ánh nắng chiếu lên ao hoặc cánh đồng trong một khoảnh khắc thoáng qua.","precision":"sentence","phrases":[{"source":"work outdoors","target":"vẽ ngoài trời"},{"source":"one fleeting moment","target":"một khoảnh khắc thoáng qua"}]},{"id":"p2-s3","source":"Their loose, visible brushstrokes looked unfinished to many viewers, and early critics mocked them; the very word \"Impressionism\" began as an insult before the artists adopted it with pride.","translation_vi":"Những nét cọ tự do, lộ rõ của họ trông như chưa hoàn thiện với nhiều người xem và bị giới phê bình ban đầu chế giễu. Chính từ 'Ấn tượng' lúc đầu là lời chê bai, trước khi được các nghệ sĩ tự hào nhận làm tên gọi.","precision":"sentence","phrases":[{"source":"loose, visible brushstrokes","target":"Những nét cọ tự do, lộ rõ"},{"source":"began as an insult","target":"lúc đầu là lời chê bai"}]},{"id":"p3-s1","source":"Cubism, developed around 1908 by Pablo Picasso and Georges Braque, went further from realism.","translation_vi":"Lập thể, do Pablo Picasso và Georges Braque phát triển khoảng năm 1908, đi xa hơn nữa khỏi chủ nghĩa hiện thực.","precision":"sentence","phrases":[{"source":"Cubism","target":"Lập thể"},{"source":"realism","target":"chủ nghĩa hiện thực"}]},{"id":"p3-s2","source":"Instead of painting an object as the eye sees it from one spot, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time, so that a face or a guitar might appear front and side together.","translation_vi":"Thay vì vẽ một vật như mắt nhìn thấy từ một vị trí, tranh Lập thể chia nó thành những hình phẳng, góc cạnh và thể hiện đồng thời nhiều góc nhìn. Vì thế, một khuôn mặt hoặc đàn ghi-ta có thể hiện cả phía trước lẫn bên cạnh cùng lúc.","precision":"sentence","phrases":[{"source":"flat, angular shapes","target":"những hình phẳng, góc cạnh"},{"source":"several viewpoints","target":"nhiều góc nhìn"},{"source":"front and side together","target":"phía trước lẫn bên cạnh cùng lúc"}]},{"id":"p3-s3","source":"The result asked viewers to assemble the subject in their own minds.","translation_vi":"Kết quả buộc người xem phải tự ráp chủ thể lại trong tâm trí.","precision":"sentence","phrases":[{"source":"assemble the subject","target":"ráp chủ thể lại"},{"source":"in their own minds","target":"trong tâm trí"}]},{"id":"p4-s1","source":"Surrealism, which took shape in the 1920s around the writer André Breton, turned away from the visible world altogether.","translation_vi":"Siêu thực, hình thành vào những năm 1920 quanh nhà văn André Breton, hoàn toàn quay lưng với thế giới nhìn thấy được.","precision":"sentence","phrases":[{"source":"Surrealism","target":"Siêu thực"},{"source":"the visible world","target":"thế giới nhìn thấy được"}]},{"id":"p4-s2","source":"Drawing on new ideas about dreams and the unconscious mind, artists such as Salvador Dalí painted scenes that obeyed no ordinary logic — soft watches draped over branches, familiar objects placed in impossible settings — in the hope of releasing thoughts that waking reason normally keeps hidden.","translation_vi":"Dựa vào những ý tưởng mới về giấc mơ và tâm trí vô thức, các nghệ sĩ như Salvador Dalí vẽ những cảnh không tuân theo lô-gic thông thường: đồng hồ mềm rủ trên cành cây, vật quen thuộc đặt trong bối cảnh không thể có. Họ hy vọng giải phóng những suy nghĩ mà lý trí lúc tỉnh thường che giấu.","precision":"sentence","phrases":[{"source":"dreams and the unconscious mind","target":"giấc mơ và tâm trí vô thức"},{"source":"impossible settings","target":"bối cảnh không thể có"},{"source":"waking reason","target":"lý trí lúc tỉnh"}]},{"id":"p5-s1","source":"Abstract Expressionism emerged in New York after 1945 and abandoned recognisable subjects entirely.","translation_vi":"Biểu hiện Trừu tượng xuất hiện ở New York sau năm 1945 và hoàn toàn từ bỏ các chủ thể có thể nhận diện.","precision":"sentence","phrases":[{"source":"Abstract Expressionism","target":"Biểu hiện Trừu tượng"},{"source":"recognisable subjects","target":"các chủ thể có thể nhận diện"}]},{"id":"p5-s2","source":"Jackson Pollock laid huge canvases on the floor and dripped or poured paint across them, moving around the edges so that the work recorded his physical gestures rather than any object.","translation_vi":"Jackson Pollock đặt những tấm toan lớn trên sàn rồi nhỏ hoặc đổ sơn lên đó, di chuyển quanh các mép để tác phẩm ghi lại động tác cơ thể của ông thay vì một vật thể.","precision":"sentence","phrases":[{"source":"canvases","target":"tấm toan"},{"source":"dripped or poured paint","target":"nhỏ hoặc đổ sơn"},{"source":"physical gestures","target":"động tác cơ thể"}]},{"id":"p5-s3","source":"Critics argued fiercely over whether such paintings were a serious achievement or no achievement at all.","translation_vi":"Giới phê bình tranh cãi gay gắt rằng những bức tranh ấy là thành tựu đáng kể hay chẳng phải thành tựu gì.","precision":"sentence","phrases":[{"source":"argued fiercely","target":"tranh cãi gay gắt"},{"source":"a serious achievement","target":"thành tựu đáng kể"}]},{"id":"p6-s1","source":"Seen together, the four movements trace a steady loosening of the link between a painting and the world outside it, from Monet's pond to Pollock's bare gesture.","translation_vi":"Nhìn chung, bốn trào lưu cho thấy mối liên hệ giữa tranh và thế giới bên ngoài dần lỏng đi, từ ao của Monet đến động tác thuần túy của Pollock.","precision":"sentence","phrases":[{"source":"a steady loosening","target":"dần lỏng đi"},{"source":"the world outside it","target":"thế giới bên ngoài"}]},{"id":"p6-s2","source":"Whether that long retreat from likeness counts as the liberation of art or the loss of something it once did well is a question that visitors, standing in those very different rooms, may still answer in different ways.","translation_vi":"Sự rời xa hình ảnh giống thực kéo dài ấy là giải phóng nghệ thuật hay đánh mất điều nghệ thuật từng làm tốt? Những khách tham quan đứng trong các phòng rất khác nhau ấy vẫn có thể trả lời khác nhau.","precision":"sentence","phrases":[{"source":"retreat from likeness","target":"rời xa hình ảnh giống thực"},{"source":"the liberation of art","target":"giải phóng nghệ thuật"},{"source":"the loss","target":"đánh mất"}]}],"illustrations":[],"question_evidence":{"1":{"question_sha256":"171d037a46ad32f7f9c23ed51d04449d73445264dff50cec331d5760be37fabf","source":"Painters such as Claude Monet left the studio to work outdoors, trying to record how sunlight struck a pond or a field at one fleeting moment.","precision":"quote","illustrations":[{"src":"/reading-illustrations/art-impressionism.svg","alt":"Minh hoạ khái niệm impressionism: hình tự vẽ theo đoạn nguồn của câu 1.","caption":"Hình tự vẽ để giải thích các trào lưu trong bài; không phải tác phẩm của Monet, Picasso, Dalí hay Pollock."}]},"2":{"question_sha256":"44aa28bf7989402807c279f6ddd945c644fbfe1429e656d094ac7cd9d286007b","source":"Instead of painting an object as the eye sees it from one spot, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time, so that a face or a guitar might appear front and side together.","precision":"quote","illustrations":[{"src":"/reading-illustrations/art-cubism.svg","alt":"Minh hoạ khái niệm cubism: hình tự vẽ theo đoạn nguồn của câu 2.","caption":"Hình tự vẽ để giải thích các trào lưu trong bài; không phải tác phẩm của Monet, Picasso, Dalí hay Pollock."}]},"3":{"question_sha256":"76424d814390a74aae6659090365546be4fa4513286bb3f8fbe86c759ec693f1","source":"Drawing on new ideas about dreams and the unconscious mind, artists such as Salvador Dalí painted scenes that obeyed no ordinary logic — soft watches draped over branches, familiar objects placed in impossible settings — in the hope of releasing thoughts that waking reason normally keeps hidden.","precision":"quote","illustrations":[{"src":"/reading-illustrations/art-surrealism.svg","alt":"Minh hoạ khái niệm surrealism: hình tự vẽ theo đoạn nguồn của câu 3.","caption":"Hình tự vẽ để giải thích các trào lưu trong bài; không phải tác phẩm của Monet, Picasso, Dalí hay Pollock."}]},"4":{"question_sha256":"327824eaad00c209d9314e2da3daa6e050bf927cf8ae71ad0266155d9aa2944b","source":"Their loose, visible brushstrokes looked unfinished to many viewers, and early critics mocked them; the very word \"Impressionism\" began as an insult before the artists adopted it with pride.","precision":"quote","illustrations":[{"src":"/reading-illustrations/art-impressionism.svg","alt":"Minh hoạ khái niệm impressionism: hình tự vẽ theo đoạn nguồn của câu 4.","caption":"Hình tự vẽ để giải thích các trào lưu trong bài; không phải tác phẩm của Monet, Picasso, Dalí hay Pollock."}]},"5":{"question_sha256":"938f500f4f4b472bb035fd2914f7d6274e73c4c0949874258d8dd6b522f4cfa0","source":"Jackson Pollock laid huge canvases on the floor and dripped or poured paint across them, moving around the edges so that the work recorded his physical gestures rather than any object.","precision":"quote","illustrations":[{"src":"/reading-illustrations/art-gestures.svg","alt":"Minh hoạ khái niệm gestures: hình tự vẽ theo đoạn nguồn của câu 5.","caption":"Hình tự vẽ để giải thích các trào lưu trong bài; không phải tác phẩm của Monet, Picasso, Dalí hay Pollock."}]}}}},"glossary":[{"term":"movement","definition":"trào lưu nghệ thuật","aliases":["movements"],"example":"These are not random styles but four movements, each reacting against the art that came before it and each redefining what a painting was supposed to do."},{"term":"brushstroke","definition":"nét cọ","aliases":["brushstrokes"],"example":"Their loose, visible brushstrokes looked unfinished to many viewers, and early critics mocked them; the very word \"Impressionism\" began as an insult before the artists adopted it with pride."},{"term":"fleeting","definition":"thoáng qua, ngắn ngủi","aliases":[],"example":"Painters such as Claude Monet left the studio to work outdoors, trying to record how sunlight struck a pond or a field at one fleeting moment."},{"term":"viewpoint","definition":"góc nhìn","aliases":["viewpoints"],"example":"Instead of painting an object as the eye sees it from one spot, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time, so that a face or a guitar might appear front and side together."},{"term":"angular","definition":"có góc cạnh","aliases":[],"example":"Instead of painting an object as the eye sees it from one spot, Cubist works broke it into flat, angular shapes and showed several viewpoints at the same time, so that a face or a guitar might appear front and side together."},{"term":"unconscious mind","definition":"tâm trí vô thức","aliases":[],"example":"Drawing on new ideas about dreams and the unconscious mind, artists such as Salvador Dalí painted scenes that obeyed no ordinary logic — soft watches draped over branches, familiar objects placed in impossible settings — in the hope of releasing thoughts that waking reason normally keeps hidden."},{"term":"canvas","definition":"toan vẽ","aliases":["canvases"],"example":"Jackson Pollock laid huge canvases on the floor and dripped or poured paint across them, moving around the edges so that the work recorded his physical gestures rather than any object."},{"term":"gesture","definition":"động tác cơ thể","aliases":["gestures"],"example":"Jackson Pollock laid huge canvases on the floor and dripped or poured paint across them, moving around the edges so that the work recorded his physical gestures rather than any object."},{"term":"likeness","definition":"sự giống với hình ảnh thực","aliases":[],"example":"Whether that long retreat from likeness counts as the liberation of art or the loss of something it once did well is a question that visitors, standing in those very different rooms, may still answer in different ways."},{"term":"liberation","definition":"sự giải phóng","aliases":[],"example":"Whether that long retreat from likeness counts as the liberation of art or the loss of something it once did well is a question that visitors, standing in those very different rooms, may still answer in different ways."}],"image_url":null,"difficulty_level":"advanced","topic_tags":["arts","history"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","slug":"matching-philosophers-of-mind","title":"Matching — Philosophers of Mind","library":"l2_skill","status":"published","body_markdown":"**A** Ask a neuroscientist what a thought is and one may receive a description of cells and electrical currents; ask a person undergoing a thought, and the answer is something quite different. The gap between those two kinds of account has haunted the philosophy of mind for centuries, and rival schools have formed largely around how that gap should be treated.\n\n**B** The most influential statement of the problem belongs to René Descartes, who argued that mind and body are two distinct kinds of substance — one thinking and immaterial, one extended and physical. This dualist view dominated for a long time, but it was eventually weakened by a puzzle it raised: if the mind is in no way physical, how can it act upon a body that is wholly physical?\n\n**C** Partly to sidestep that question, the functionalists proposed that what makes a state mental is not the stuff it is made of but the role it plays. On their view, a belief or a pain is defined by the job it does within a network of inputs, outputs and other states — much as a piece of software can run on different kinds of machine. The appeal of this framework was that it placed the mind firmly within the reach of science without appealing to a separate soul.\n\n**D** Not everyone, however, was persuaded that explaining function settled everything. David Chalmers argued famously that even a complete account of how the brain processes information would leave a separate question open: why is there something it feels like to be in such a state at all? He called this the \"hard problem\" of consciousness, and distinguished it from the easier \"easy problems\" of mapping mechanisms.\n\n**E** Daniel Dennett responded with pronounced scepticism. For him, the sense that some mysterious residue remains once all the functions are explained is itself the thing to be explained away, not revered — a confusion arising from how we talk about experience, and one that careful analysis will dissolve. What Chalmers takes to be a deep chasm, Dennett regards as an illusion.\n\n**F** None of these positions has driven the others from the field, and most contemporary work moves between them, borrowing the rigour of functionalism while still feeling the pull of Chalmers's question. Whether the gap between mechanism and experience will finally close or merely be redescribed in fresher terms remains a matter on which reasonable minds continue to disagree.","metadata":{"grammar_focus":[{"tip":"'what makes X … is …' báo hiệu tác giả đang định nghĩa lại bản chất một khái niệm — chỗ then chốt cho câu hỏi matching/ý chính.","point":"Câu chẻ giả thác (pseudo-cleft) 'what makes … is not A but B'","review":"What + S + V + is + X = chính cái mà… là X (pseudo-cleft). 'not A but B' = không phải A mà là B. Khác it-cleft ('It is X that…').","example":"the functionalists proposed that **what makes a state mental is not the stuff it is made of but the role it plays**","analysis":"Pseudo-cleft mở đầu bằng mệnh đề danh ngữ 'what makes a state mental' làm chủ ngữ, nối bằng 'is' với cấu trúc tương phản 'not A but B' (not the stuff… but the role…). Hai vế 'the stuff it is made of' // 'the role it plays' đều chứa mệnh đề quan hệ lược 'that'. Trọng tâm thông tin dồn về vế sau 'is'."},{"tip":"Cụm 'to + V' đầu câu chỉ mục đích — xác định chủ ngữ của mệnh đề chính để biết ai thực hiện hành động ấy.","point":"Cụm to-infinitive chỉ mục đích fronting đầu câu (không đảo S–V)","review":"Fronting = đưa một thành phần (cụm mục đích/trạng ngữ) lên đầu để nhấn mạnh, S–V giữ nguyên. Khác inversion (đảo trợ động từ ra trước chủ ngữ).","example":"**Partly to sidestep that question**, the functionalists proposed that…","analysis":"Cụm bổ ngữ 'Partly to sidestep that question' (trạng từ 'partly' + to-infinitive chỉ mục đích) đứng đầu, được đưa lên trước mệnh đề chính mà KHÔNG đảo chủ–vị — đây là fronting (đảo thành phần lên đầu), không phải inversion. Mệnh đề chính giữ trật tự S–V bình thường 'the functionalists proposed…'."},{"tip":"Đoạn kết 'Whether… remains a matter…disagree' báo hiệu tác giả không nghiêng hẳn về bên nào — câu hỏi quan điểm hay nhắm vào sự lưỡng lự này.","point":"Mệnh đề danh ngữ 'Whether A or B' làm chủ ngữ + bổ ngữ có mệnh đề quan hệ","review":"Whether A or B + remains a matter on which… = liệu A hay B vẫn là vấn đề mà… (bỏ ngỏ). 'on which' = mệnh đề quan hệ trang trọng.","example":"**Whether the gap between mechanism and experience will finally close or merely be redescribed in fresher terms remains a matter** on which reasonable minds continue to disagree.","analysis":"Mệnh đề 'Whether A or B' (A = will…close, B = merely be redescribed) làm chủ ngữ của 'remains'; B ở dạng bị động lược tác nhân. Bổ ngữ 'a matter' được mệnh đề quan hệ trang trọng 'on which reasonable minds…disagree' (giới từ + which) bổ nghĩa. Câu bỏ ngỏ kết luận. Đây là mệnh đề danh ngữ, KHÔNG phải cleft."},{"tip":"Hai vế đối xứng 'What X sees as A, Y sees as B' tóm gọn sự bất đồng giữa hai bên — lý tưởng cho câu hỏi matching quan điểm.","point":"Fronting tân ngữ-mệnh đề để tạo phản đề (không đảo S–V)","review":"take/regard A as B = coi A là B. Fronting tân ngữ ('What…') lên đầu để tạo đối lập, không đảo S–V.","example":"**What Chalmers takes to be a deep chasm, Dennett regards as an illusion.**","analysis":"Tân ngữ-mệnh đề 'What Chalmers takes to be a deep chasm' được đưa lên đầu làm fronting để đối lập với 'Dennett regards [it] as an illusion'; cả hai vế dùng cấu trúc song song 'take/regard … as …'. Việc đưa thành phần lên đầu nhằm tạo phản đề mạnh, S–V của mệnh đề chính ('Dennett regards') vẫn theo trật tự thường."}],"translation_vi":"**A** Hãy hỏi một nhà thần kinh học suy nghĩ là gì và người ta có thể nhận về một mô tả về các tế bào và những dòng điện; hãy hỏi một người đang trải nghiệm một suy nghĩ, và đáp lại là một điều gì đó rất khác. Khoảng cách giữa hai loại tường thuật ấy đã ám ảnh triết học tâm trí trong nhiều thế kỷ, và những trường phái cạnh tranh đã hình thành chủ yếu quanh việc nên xử lý khoảng cách ấy như thế nào.\n\n**B** Cách trình bày có ảnh hưởng nhất về vấn đề này thuộc về René Descartes, người đã lập luận rằng tâm trí và thân thể thuộc về hai loại thực thể khác biệt — một cái biết tư duy và phi vật chất, một cái có quảng tính và vật chất. Quan điểm nhị nguyên này thống trị trong một thời gian dài, nhưng rốt cuộc nó bị suy yếu bởi một câu đố mà chính nó dấy lên: nếu tâm trí không hề có tính vật chất, thì làm thế nào nó có thể tác động lên một thân thể vốn dĩ hoàn toàn là vật chất?\n\n**C** Một phần để né tránh câu hỏi ấy, các nhà chức năng luận đã đề xuất rằng cái khiến một trạng thái trở thành tâm trí không phải là chất liệu nó được làm bằng mà là vai trò nó đảm nhận. Theo cách nhìn của họ, một niềm tin hay một cơn đau được xác định bởi công việc nó làm trong một mạng lưới gồm những đầu vào, đầu ra và những trạng thái khác — tựa như một phần mềm có thể chạy trên những loại máy móc khác nhau. Sức hấp dẫn của khung này nằm ở chỗ nó đặt tâm trí vững chắc trong tầm với của khoa học mà không cần viện đến một linh hồn riêng biệt.\n\n**D** Tuy nhiên, không phải ai cũng tin rằng việc giải thích được chức năng là đã giải quyết được mọi điều. David Chalmers đã lập luận một cách nổi tiếng rằng ngay cả một tường thuật đầy đủ về việc bộ não xử lý thông tin như thế nào vẫn sẽ bỏ ngỏ một câu hỏi tách biệt: vì sao lại có một điều-cảm-thấy-ra-sao khi ở trong một trạng thái như vậy? Ông gọi đây là \"bài toán khó\" của ý thức, và phân biệt nó với những \"bài toán dễ\" hơn về việc lập sơ đồ cơ chế.\n\n**E** Daniel Dennett đã trả lời bằng sự ngờ vực rõ rệt. Đối với ông, cái cảm giác rằng có một dư lượng bí ẩn còn lại sau khi mọi chức năng đã được giải thích chính bản thân nó là điều cần được giải thích đi, không phải để tôn kính — một sự lẫn lộn nảy sinh từ cách chúng ta nói về trải nghiệm, và một sự lẫn lộn mà sự phân tích cẩn thận sẽ làm tan biến. Điều mà Chalmers coi là một vực thẳm sâu thẳm thì Dennett lại xem như một ảo ảnh.\n\n**F** Không có quan điểm nào trong số này đã đẩy được những quan điểm khác ra khỏi cuộc chơi, và phần lớn các công trình đương đại đều di chuyển giữa chúng, vay mượn sự nghiêm ngặt của chức năng luận trong khi vẫn cảm thấy lực kéo của câu hỏi của Chalmers. Liệu khoảng cách giữa cơ chế và trải nghiệm cuối cùng có khép lại hay chỉ đơn thuần được mô tả lại bằng những thuật ngữ mới mẻ hơn vẫn còn là một vấn đề mà những bộ óc có lý trí tiếp tục bất đồng.","practice_support":{"schema_version":1,"source_sha256":"27a6c6e284525039c820c7fc8566968d327969ffebf5c7bdd461760b7062be72","translation_sha256":"5c1ff08ab940915f13f66bf90e73ed3b8c66ebace6114e22fe58513ec7b0c4e0","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"3e8e0092625c93fb1f996bc881d2b8cdc4c0c4c469973a6c83fcd3c02e226535","source":"mind and body are two distinct kinds of substance","precision":"quote","illustrations":[]},"2":{"question_sha256":"c4717943da02e7474d0331bad91002ff78c4848d75e5c28c3de7671658e1c302","source":"even a complete account of how the brain processes information would leave a separate question open","precision":"quote","illustrations":[]},"3":{"question_sha256":"e5f63125c07031d65b47870676f99d95182ada01aef8581532c6a4701f46b341","source":"the job it does within a network of inputs, outputs and other states","precision":"quote","illustrations":[]},"4":{"question_sha256":"bac2ff7490f13c57eedaf53e23466621664dd065a5067c9ad7e90756f7c6acb7","source":"a confusion arising from how we talk about experience, and one that careful analysis will dissolve","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"immaterial","definition":"phi vật chất","example":"B The most influential statement of the problem belongs to René Descartes, who argued that mind and body are two distinct kinds of substance — one thinking and immaterial, one extended and physical.","aliases":[]},{"term":"inputs","definition":"các đầu vào","example":"On their view, a belief or a pain is defined by the job it does within a network of inputs, outputs and other states — much as a piece of software can run on different kinds of machine.","aliases":[]},{"term":"consciousness","definition":"ý thức","example":"David Chalmers argued famously that even a complete account of how the brain processes information would leave a separate question open: why is there something it feels like to be in such a state at all? He called this the \"hard problem\" of consciousness, and distinguished it from the easier \"easy problems\" of mapping mechanisms.","aliases":[]},{"term":"residue","definition":"phần còn lại chưa được giải thích","example":"For him, the sense that some mysterious residue remains once all the functions are explained is itself the thing to be explained away, not revered — a confusion arising from how we talk about experience, and one that careful analysis will dissolve.","aliases":[]},{"term":"rigour","definition":"tính chặt chẽ trong lập luận hoặc phương pháp","example":"F None of these positions has driven the others from the field, and most contemporary work moves between them, borrowing the rigour of functionalism while still feeling the pull of Chalmers's question.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["social-sciences","science"],"skill_focus":"detail","word_count":null,"estimated_minutes":14},{"id":"145f4430-a780-4988-b3bd-f977f2c73704","slug":"matching-pioneers-of-flight","title":"Matching — Four Pioneers of Early Flight","library":"l2_skill","status":"published","body_markdown":"**A** The story of flight is often shrunk to a single December morning in 1903, when a fragile machine lifted off a windy beach in North Carolina. Yet that morning rested on more than a century of patient work by people who never saw an aeroplane carry a passenger.\n\n**B** The first of them was the English engineer Sir George Cayley. Working in the early nineteenth century, long before any engine was light enough to fly, he set out the forces a flying machine must overcome — lift, weight, thrust and drag. He argued that lift, propulsion and control could be handled by separate parts of a craft, an idea that still underlies aircraft design today.\n\n**C** Decades later, the German engineer Otto Lilienthal turned theory into practice. Between 1891 and his death in a crash in 1896, he made around two thousand glider flights from hills near Berlin, recording careful data on how curved wings behaved. His measurements, and the photographs of him gliding, reached inventors across the Atlantic.\n\n**D** Among those inventors were the American brothers Wilbur and Orville Wright. Their decisive contribution was not the engine but control: they devised a system for steering an aircraft about three axes, so a pilot could keep it steady and turn it deliberately. Their first powered flights were short, low and watched by only a handful of people.\n\n**E** Public proof that powered flight had arrived came in Europe through the Brazilian Alberto Santos-Dumont. In 1906, before crowds in Paris, he flew his box-like 14-bis a few hundred metres — the first powered aeroplane flight there to be openly witnessed and officially recorded.\n\n**F** No single figure can claim to have invented flight. Each built on the failures and notebooks of others, and where exactly the credit should fall is still argued over, perhaps because the achievement was never really one person's to begin with.","metadata":{"grammar_focus":[{"tip":"Cụm 'the first … to be + V3' nhấn mạnh tính 'đầu tiên/duy nhất' — chi tiết hay được hỏi trong matching và True/False (kiểm tra có đúng là 'đầu tiên' không).","point":"Bị động dạng nguyên mẫu hoàn thành (perfect passive infinitive)","review":"To-infinitive bị động: to be + V3. Sau danh từ có 'the first/only…' thường dùng to-infinitive bổ nghĩa (the first to do / to be done).","example":"the first powered aeroplane flight there **to be openly witnessed and officially recorded**","analysis":"'to be witnessed and recorded' là to-infinitive bị động (to be + V3), bổ nghĩa cho 'flight' theo nghĩa 'chuyến bay đầu tiên ĐƯỢC chứng kiến và ghi nhận'. Hai phân từ 'witnessed' và 'recorded' nối song song bằng 'and', cùng chia sẻ 'to be'."},{"tip":"Định vị danh từ đứng ngay trước 'that/which' để biết mệnh đề quan hệ đang mô tả cái gì — bước bắt buộc khi giải matching information.","point":"Mệnh đề quan hệ xác định bổ nghĩa cho danh từ trừu tượng","review":"Mệnh đề quan hệ xác định với 'that/which' cho vật, không dấu phẩy. Bị động với modal: modal + be + V3 (could be handled).","example":"He argued that lift, propulsion and control could be handled by separate parts of a craft, **an idea that still underlies** aircraft design today","analysis":"'an idea' là cụm đồng vị (appositive) tóm lại cả ý trước; 'that still underlies aircraft design today' là mệnh đề quan hệ xác định, 'that' thay 'an idea' và làm chủ ngữ của 'underlies'. Bên trong còn có 'could be handled by…' là bị động với modal."},{"tip":"Khi câu mở đầu bằng cụm chỉ nơi chốn rồi đến động từ 'to be/come', chủ ngữ nằm CUỐI câu — đọc ngược để xác định ai/cái gì là chủ ngữ.","point":"Đảo ngữ với cụm giới từ chỉ nơi chốn đầu câu","review":"Đảo ngữ với trạng ngữ chỉ nơi chốn/hướng đầu câu: Adverbial + V + S (Here comes…, Among them was…). Động từ chia theo chủ ngữ thật đứng sau.","example":"**Among those inventors were** the American brothers Wilbur and Orville Wright.","analysis":"Cụm giới từ 'Among those inventors' được đảo lên đầu, kéo theo đảo ngữ chủ–động: động từ 'were' đứng trước chủ ngữ thật 'the American brothers…'. Đây là đảo ngữ vị trí (locative inversion), giúp nối thông tin cũ–mới mượt mà."}],"translation_vi":"**A** Câu chuyện về chuyến bay thường bị thu nhỏ lại thành một buổi sáng tháng Mười Hai duy nhất năm 1903, khi một cỗ máy mỏng manh cất cánh khỏi một bãi biển lộng gió ở North Carolina. Thế nhưng buổi sáng ấy dựa trên hơn một thế kỷ làm việc kiên nhẫn của những người chưa bao giờ thấy một chiếc máy bay chở một hành khách.\n\n**B** Người đầu tiên trong số họ là kỹ sư người Anh Sir George Cayley. Làm việc vào đầu thế kỷ mười chín, từ rất lâu trước khi bất kỳ động cơ nào đủ nhẹ để bay, ông đã trình bày những lực mà một cỗ máy bay phải vượt qua — lực nâng, trọng lực, lực đẩy và lực cản. Ông lập luận rằng lực nâng, sự đẩy và sự điều khiển có thể được xử lý bởi những bộ phận riêng biệt của một phương tiện, một ý tưởng vẫn còn làm nền tảng cho thiết kế máy bay ngày nay.\n\n**C** Nhiều thập kỷ sau, kỹ sư người Đức Otto Lilienthal đã biến lý thuyết thành thực hành. Giữa năm 1891 và cái chết của ông trong một vụ tai nạn năm 1896, ông đã thực hiện khoảng hai nghìn chuyến bay tàu lượn từ những ngọn đồi gần Berlin, ghi lại dữ liệu cẩn thận về cách những cánh cong hoạt động. Những phép đo của ông, và những bức ảnh ông lượn, đã đến với các nhà phát minh bên kia Đại Tây Dương.\n\n**D** Trong số những nhà phát minh đó có anh em người Mỹ Wilbur và Orville Wright. Đóng góp mang tính quyết định của họ không phải là động cơ mà là sự điều khiển: họ đã nghĩ ra một hệ thống để lái một chiếc máy bay quanh ba trục, để một phi công có thể giữ nó ổn định và rẽ nó một cách có chủ đích. Những chuyến bay có động cơ đầu tiên của họ ngắn, thấp và chỉ được một số ít người chứng kiến.\n\n**E** Bằng chứng công khai rằng chuyến bay có động cơ đã đến được mang tới ở châu Âu qua người Brazil Alberto Santos-Dumont. Năm 1906, trước đám đông ở Paris, ông đã bay chiếc 14-bis hình hộp của mình vài trăm mét — chuyến bay máy bay có động cơ đầu tiên ở đó được chứng kiến công khai và ghi nhận chính thức.\n\n**F** Không một nhân vật đơn lẻ nào có thể tuyên bố đã phát minh ra chuyến bay. Mỗi người đều xây dựng trên những thất bại và sổ tay của người khác, và chính xác công lao nên thuộc về đâu vẫn còn được tranh cãi, có lẽ vì thành tựu này ngay từ đầu chưa bao giờ thực sự là của riêng một người.","practice_support":{"schema_version":1,"source_sha256":"59b4b733e88a343a9a351cd7b7c2720463acaa08a87de5853deff191bbc2d953","translation_sha256":"ad03ce8eec73f5f1f1f7562047d587823cab155c6c985e8a4d3b4e5bcb2bde28","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"b418c70bd449e080069f880bc4c2fd4fbff098935673b3d29a617a512284750d","source":"lift, propulsion and control could be handled by separate parts of a craft","precision":"quote","illustrations":[]},"2":{"question_sha256":"17772c00269ef0cec754132186546c4fdb8b6c184b5d45dc6efc93a72522c230","source":"he made around two thousand glider flights","precision":"quote","illustrations":[]},"3":{"question_sha256":"debbb8f90e6f47e611e6923ba2a58a1f7d96569c0ae5b90ec473923ff37a6d54","source":"a system for steering an aircraft about three axes","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"lift","definition":"lực nâng","example":"Working in the early nineteenth century, long before any engine was light enough to fly, he set out the forces a flying machine must overcome — lift, weight, thrust and drag.","aliases":[]},{"term":"thrust","definition":"lực đẩy","example":"Working in the early nineteenth century, long before any engine was light enough to fly, he set out the forces a flying machine must overcome — lift, weight, thrust and drag.","aliases":[]},{"term":"drag","definition":"lực cản","example":"Working in the early nineteenth century, long before any engine was light enough to fly, he set out the forces a flying machine must overcome — lift, weight, thrust and drag.","aliases":[]},{"term":"propulsion","definition":"sự tạo lực đẩy để máy bay tiến lên","example":"He argued that lift, propulsion and control could be handled by separate parts of a craft, an idea that still underlies aircraft design today.","aliases":[]},{"term":"glider flights","definition":"các chuyến bay bằng tàu lượn","example":"Between 1891 and his death in a crash in 1896, he made around two thousand glider flights from hills near Berlin, recording careful data on how curved wings behaved.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["history","science"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","slug":"matching-pioneers-of-medicine","title":"Matching — Pioneers of Modern Medicine","library":"l2_skill","status":"published","body_markdown":"**A** Medicine before the mid-nineteenth century was often a matter of guesswork, and\nsurgery was so dangerous that many patients died of infection rather than of the\noriginal injury. A few early breakthroughs hinted at what was possible — the English\ndoctor Edward Jenner had introduced a smallpox vaccine as early as 1796 — but a modern\nunderstanding of disease was still decades away.\n\n**B** The decisive shift came with the French chemist Louis Pasteur. Through careful\nexperiments he demonstrated that many illnesses were caused not by 'bad air' but by tiny\nliving organisms, a principle now known as germ theory. He also developed a method of\ngentle heating, later called pasteurisation, to kill microbes in liquids, and in 1885 he\ntreated a boy bitten by a rabid dog with an early vaccine.\n\n**C** Pasteur's ideas reached the operating theatre through the British surgeon Joseph\nLister. Reasoning that germs might be infecting open wounds, in 1867 he began spraying\ncarbolic acid on instruments, hands and dressings. Death rates after surgery in his\nwards fell sharply, and antiseptic technique gradually became standard practice.\n\n**D** Cleanliness mattered outside the operating room too. Florence Nightingale, working\nin military hospitals during the Crimean War from 1854, argued that overcrowding and\nfilth were killing soldiers faster than their wounds. She recorded deaths carefully and\npresented her evidence in clear diagrams, using statistics to persuade officials that\nsanitation could save lives.\n\n**E** Perhaps the most famous turning point came almost by accident. In 1928 the Scottish\nresearcher Alexander Fleming returned from holiday to find that a mould had drifted into\na dish of bacteria and killed the colonies around it. The mould was producing a\nsubstance he named penicillin, the first of the antibiotics that would later treat\nonce-fatal infections.\n\n**F** Taken together, these figures turned medicine from a craft into a science. None\nworked entirely alone, and each built on the discoveries of others, yet the line\nconnecting their efforts is clear: disease could be understood, prevented and,\nincreasingly, cured.","metadata":{"grammar_focus":[{"tip":"Cấu trúc 'not by X but by Y' rất hay ra Matching/TFNG — đáp án đúng là Y, X là bẫy; đọc trọn cả vế 'but' mới chọn.","point":"Câu bị động (passive voice) ở quá khứ với cấu trúc 'not … but …'","review":"Bị động: be + V3; tác nhân nêu bằng 'by'. 'not … but …' = không phải … mà là …, dùng để đối chiếu/sửa lại.","example":"many illnesses **were caused** not by 'bad air' but by tiny living organisms","analysis":"'were caused' là bị động quá khứ (were + V3). Cấu trúc tương phản 'not by X but by Y' đặt sau động từ bị động để loại bỏ nguyên nhân sai (bad air) và khẳng định nguyên nhân đúng (organisms). Hai tác nhân đều nêu bằng 'by'."},{"tip":"Khi gặp cụm ', V-ing …,' chèn giữa câu, hãy bỏ tạm để tìm chủ ngữ–động từ chính, tránh nhầm phân từ là động từ chính của câu.","point":"Mệnh đề phân từ hiện tại (present participle clause) chèn giữa câu","review":"Participle clause: , V-ing …, rút gọn cho 'who/which + be + V-ing'. Chủ ngữ phân từ phải khớp chủ ngữ chính.","example":"Florence Nightingale, **working in military hospitals** during the Crimean War from 1854, argued that ...","analysis":"'working in military hospitals …' là mệnh đề phân từ rút gọn từ 'who was working …', chèn giữa hai dấu phẩy để bổ sung hoàn cảnh. Chủ ngữ ngầm của 'working' chính là 'Florence Nightingale'; động từ chính của câu là 'argued'."},{"tip":"'would' ở đây KHÔNG phải điều kiện — định vị mốc thời gian quá khứ để hiểu đúng 'về sau sẽ…', chi tiết hay bị hỏi trong matching information.","point":"Mệnh đề quan hệ xác định với 'that' và động từ khuyết thiếu 'would'","review":"Mệnh đề quan hệ xác định: N + that/which + V. 'would + V' = tương lai trong quá khứ (sẽ, nhìn từ một mốc quá khứ).","example":"the first of the antibiotics **that would later treat** once-fatal infections","analysis":"'that' thay 'the antibiotics' làm chủ ngữ của 'would later treat', mở mệnh đề quan hệ xác định (không dấu phẩy). 'would' diễn tả tương lai nhìn từ quá khứ (future in the past): vào năm 1928, những kháng sinh này 'về sau sẽ' chữa bệnh."}],"translation_vi":"**A** Y học trước giữa thế kỷ mười chín thường là chuyện phỏng đoán, và phẫu thuật nguy hiểm đến mức nhiều bệnh nhân chết vì nhiễm trùng chứ không phải vì vết thương ban đầu. Một vài đột phá sớm đã hé lộ điều có thể làm được — bác sĩ người Anh Edward Jenner đã giới thiệu một loại vắc-xin đậu mùa từ sớm, vào năm 1796 — nhưng hiểu biết hiện đại về bệnh tật vẫn còn cách xa nhiều thập kỷ.\n\n**B** Bước ngoặt quyết định đến cùng nhà hóa học người Pháp Louis Pasteur. Qua những thí nghiệm cẩn thận, ông đã chứng minh rằng nhiều bệnh tật không phải do \"không khí xấu\" mà do những sinh vật sống tí hon, một nguyên lý nay gọi là thuyết mầm bệnh. Ông cũng phát triển một phương pháp gia nhiệt nhẹ, về sau gọi là khử trùng kiểu Pasteur, để diệt vi khuẩn trong chất lỏng, và vào năm 1885 ông đã chữa cho một cậu bé bị chó dại cắn bằng một loại vắc-xin sơ khai.\n\n**C** Những ý tưởng của Pasteur đã đến với phòng mổ thông qua nhà phẫu thuật người Anh Joseph Lister. Lập luận rằng mầm bệnh có thể đang làm nhiễm trùng các vết thương hở, năm 1867 ông bắt đầu xịt axit carbolic lên dụng cụ, bàn tay và băng gạc. Tỷ lệ tử vong sau phẫu thuật trong các khu của ông giảm mạnh, và kỹ thuật vô trùng dần trở thành thông lệ chuẩn.\n\n**D** Sự sạch sẽ cũng quan trọng ngoài phòng mổ. Florence Nightingale, làm việc trong các bệnh viện quân đội trong Chiến tranh Krym từ năm 1854, lập luận rằng tình trạng chật chội và bẩn thỉu đang giết binh lính nhanh hơn cả vết thương của họ. Bà ghi chép các ca tử vong tỉ mỉ và trình bày bằng chứng bằng những biểu đồ rõ ràng, dùng số liệu thống kê để thuyết phục giới chức rằng vệ sinh có thể cứu mạng người.\n\n**E** Có lẽ bước ngoặt nổi tiếng nhất đến gần như một cách tình cờ. Năm 1928, nhà nghiên cứu người Scotland Alexander Fleming trở về sau kỳ nghỉ và phát hiện một loại nấm mốc đã lọt vào một đĩa vi khuẩn và giết chết các khuẩn lạc xung quanh nó. Loại nấm mốc đó đang tạo ra một chất mà ông đặt tên là penicillin, kháng sinh đầu tiên về sau sẽ chữa được những nhiễm trùng từng bị coi là chí mạng.\n\n**F** Gộp lại, những nhân vật này đã biến y học từ một nghề thủ công thành một khoa học. Không ai làm việc hoàn toàn đơn độc, và mỗi người đều xây trên khám phá của người khác, nhưng đường nối liền công trình của họ đủ rõ ràng: bệnh tật có thể được hiểu, phòng ngừa và, ngày càng nhiều, chữa khỏi.","practice_support":{"schema_version":1,"source_sha256":"6a59af9a490bcbc1efaee9d61fed11b5bd5f02b06bafbc76ec0381e8c0620076","translation_sha256":"f2346b960dcc59eaf3487f6a0f6e6207027dffe6f4cee00bbaf3461e09558b1f","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"e7ba103fd0e99a0607e15a1a2e6a33bac49b6b920d568c6d40c60b077138095e","source":"many illnesses were caused not by 'bad air' but by tiny living organisms","precision":"quote","illustrations":[]},"2":{"question_sha256":"da539d32e01521100370575f1e951832d27f7b98cc8f030d0ebe3cae616a2faa","source":"using statistics to persuade officials that sanitation could save lives","precision":"quote","illustrations":[]},"3":{"question_sha256":"ad01a953ac5f3e64162dfa770b7c12549fd08e76e2de95f96355c0e93f0b03b8","source":"a mould had drifted into a dish of bacteria and killed the colonies around it","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"germ theory","definition":"thuyết mầm bệnh: vi sinh vật có thể gây bệnh","example":"Through careful experiments he demonstrated that many illnesses were caused not by 'bad air' but by tiny living organisms, a principle now known as germ theory.","aliases":[]},{"term":"pasteurisation","definition":"phương pháp thanh trùng bằng nhiệt","example":"He also developed a method of gentle heating, later called pasteurisation, to kill microbes in liquids, and in 1885 he treated a boy bitten by a rabid dog with an early vaccine.","aliases":[]},{"term":"open wounds","definition":"các vết thương hở","example":"Reasoning that germs might be infecting open wounds, in 1867 he began spraying carbolic acid on instruments, hands and dressings.","aliases":[]},{"term":"sanitation","definition":"điều kiện và biện pháp vệ sinh","example":"She recorded deaths carefully and presented her evidence in clear diagrams, using statistics to persuade officials that sanitation could save lives.","aliases":[]},{"term":"antibiotics","definition":"thuốc kháng sinh","example":"The mould was producing a substance he named penicillin, the first of the antibiotics that would later treat once-fatal infections.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["health","history"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","slug":"matching-schools-of-architecture","title":"Matching — Schools of Architecture","library":"l2_skill","status":"published","body_markdown":"**A** A building is rarely only shelter; it is also an argument, made in stone or concrete, about how life should be ordered and what is worth looking up at. The history of Western architecture can therefore be read as a sequence of competing arguments, each reacting against the one before it as much as to the practical needs of its age.\n\n**B** The most ambitious of the medieval arguments was the Gothic style, which emerged in France in the twelfth century. By replacing heavy round arches with pointed ones and ribbed vaults, its builders could raise taller, thinner walls, hollowed out by wide windows. The effect was deliberate: the eye is drawn upward towards heaven, and once-dark interiors are flooded with coloured light, turning the structure itself into an expression of devotion.\n\n**C** Centuries later, the German Bauhaus, founded in 1919, made an almost opposite argument. Rejecting ornament as dishonest, its designers held that the appearance of an object should arise directly from its function and from the straightforward use of modern industrial materials such as steel and glass. Form, in the famous slogan, should follow function, and beauty was to be found in clarity rather than in what was added on.\n\n**D** After the Second World War, a generation of architects pushed that ideal of honesty in a rougher direction. Brutalism, named partly for the French béton brut, \"raw concrete\", left concrete bare and exposed a building's structure plainly rather than hiding it. Conceived as honest and democratic, the style was later condemned by many as bleak, and some of its finest works were demolished before their reputations could recover.\n\n**E** By the 1970s a reaction had formed against the severity that modernism left behind. Postmodernism, as it came to be known, rejected the idea that there was a single true language of form. Instead it borrowed playfully from many past styles at once, mixing classical motifs with bright colour and ironic touches, as if to remind onlookers that architecture too could make jokes.\n\n**F** None of these styles has wholly erased those that preceded it, and most contemporary work borrows from several at once, reaching for whichever vocabulary suits the site and purpose. Whether that mixture represents a maturing of taste or merely the absence of a shared conviction remains a question on which critics continue to disagree.","metadata":{"grammar_focus":[{"tip":"Cụm 'By + V-ing' đầu câu phải cùng chủ ngữ với mệnh đề chính ('its builders') — xác định để biết ai thực hiện hành động.","point":"Cụm giới từ 'By + V-ing' fronting chỉ phương thức","review":"by + V-ing = bằng cách (làm gì); gerund sau giới từ 'by'. replace A with B = thay A bằng B. Fronting cụm phương thức lên đầu, không đảo S–V.","example":"**By replacing heavy round arches with pointed ones and ribbed vaults**, its builders could raise taller, thinner walls","analysis":"Cụm giới từ 'By + V-ing' (By replacing…) chỉ phương thức, đưa lên đầu (fronting) trước mệnh đề chính 'its builders could raise…'; S–V mệnh đề chính giữ nguyên trật tự, không đảo. Tân ngữ của 'replacing' có cấu trúc 'replace A with B' (A = heavy round arches, B = pointed ones and ribbed vaults). 'ones' thay cho 'arches' tránh lặp."},{"tip":"Cụm '-ing' mở đầu câu phải cùng chủ ngữ với mệnh đề chính — kiểm tra để tránh hiểu sai chủ thể của hành động.","point":"Cụm phân từ hiện tại đầu câu (participle clause) chỉ hoàn cảnh","review":"V-ing + …, S + V… = mệnh đề phân từ chủ động rút gọn, cùng chủ ngữ với mệnh đề chính. reject A as B = bác bỏ A vì coi là B.","example":"**Rejecting ornament as dishonest**, its designers held that the appearance of an object should arise directly from its function","analysis":"Cụm phân từ hiện tại 'Rejecting ornament as dishonest' đứng đầu, rút gọn từ mệnh đề chủ động ('Because they rejected…'), bổ nghĩa cho chủ ngữ 'its designers' của mệnh đề chính. 'reject A as B' = bác bỏ A vì cho là B. Mệnh đề danh ngữ 'that the appearance…should arise…' làm tân ngữ cho 'held'."},{"tip":"Cụm '-ed' mở đầu câu là mệnh đề bị động rút gọn — đối lập giữa nó và mệnh đề chính thường hàm ý nhượng bộ ('tuy… nhưng…').","point":"Cụm phân từ quá khứ đầu câu (participle clause) bị động chỉ nhượng bộ","review":"V3 (Conceived…) + …, S + V… = mệnh đề phân từ bị động rút gọn (= Although it was conceived…). condemn A as B = lên án A là B.","example":"**Conceived as honest and democratic**, the style was later condemned by many as bleak","analysis":"Cụm phân từ quá khứ 'Conceived as honest and democratic' đứng đầu, rút gọn từ mệnh đề bị động ('Although it was conceived…'), bổ nghĩa cho chủ ngữ 'the style'. Tương phản với mệnh đề chính bị động 'was later condemned… as bleak' tạo sắc thái nhượng bộ. 'conceive/condemn A as B' = hình dung/lên án A là B; cả hai vế lược tác nhân, riêng vế sau nêu 'by many'."},{"tip":"Đoạn kết 'Whether… remains a question…disagree' báo hiệu tác giả không nghiêng hẳn về bên nào — câu hỏi quan điểm hay nhắm vào sự lưỡng lự này.","point":"Mệnh đề danh ngữ 'Whether A or B' làm chủ ngữ + bổ ngữ có mệnh đề quan hệ","review":"Whether A or B + remains a question on which… = liệu A hay B vẫn là vấn đề mà… (bỏ ngỏ). 'on which' = mệnh đề quan hệ trang trọng.","example":"**Whether that mixture represents a maturing of taste or merely the absence of a shared conviction remains a question** on which critics continue to disagree.","analysis":"Mệnh đề 'Whether A or B' (A = a maturing of taste, B = merely the absence of a shared conviction) làm chủ ngữ của 'remains'; bổ ngữ 'a question' được mệnh đề quan hệ trang trọng 'on which critics…disagree' (giới từ + which) bổ nghĩa. Câu bỏ ngỏ kết luận. Đây là mệnh đề danh ngữ, KHÔNG phải cleft."}],"translation_vi":"**A** Một tòa nhà hiếm khi chỉ là chỗ trú ẩn; nó cũng là một lập luận được dựng bằng đá hoặc bê tông về việc cuộc sống nên được tổ chức như thế nào và cái gì đáng để ngước nhìn. Lịch sử kiến trúc phương Tây do đó có thể được đọc như một chuỗi những lập luận cạnh tranh, mỗi lập luận phản ứng lại với lập luận đến trước nó cũng nhiều như với những nhu cầu thực tiễn của thời đại nó.\n\n**B** Tham vọng nhất trong số những lập luận thời trung cổ là phong cách Gothic, vốn nổi lên ở Pháp vào thế kỷ mười hai. Bằng việc thay thế những vòm tròn nặng nề bằng vòm nhọn và những vòm có gân, các thợ xây của nó đã có thể dựng những bức tường cao hơn, mỏng hơn, được khoét rỗng bằng những ô cửa sổ rộng. Hiệu ứng được dụng ý: ánh nhìn bị kéo lên trên về phía thiên đường, và những nội thất từng tối tăm giờ ngập tràn ánh sáng nhuốm màu, biến chính cấu trúc thành một biểu hiện của lòng sùng kính.\n\n**C** Nhiều thế kỷ về sau, trường phái Bauhaus của Đức, thành lập năm 1919, đã đưa ra một lập luận gần như đối nghịch. Bác bỏ trang trí như một thứ không trung thực, các nhà thiết kế của nó cho rằng diện mạo của một vật thể phải nảy sinh trực tiếp từ chức năng của nó và từ việc sử dụng thẳng thắn những vật liệu công nghiệp hiện đại như thép và kính. Hình thức, theo phương châm nổi tiếng, phải đi theo công năng, và vẻ đẹp cần được tìm thấy ở sự rõ ràng thay vì ở những gì được thêm thắt.\n\n**D** Sau Thế chiến thứ hai, một thế hệ kiến trúc sư đã đẩy lý tưởng về sự trung thực ấy theo một hướng gồ ghề hơn. Trường phái Brutalism, được đặt tên một phần theo từ béton brut trong tiếng Pháp nghĩa là \"bê tông thô\", để lộ bê tông trần và phơi bày cấu trúc của một tòa nhà một cách lộ liễu thay vì che giấu nó. Được hình dung như một thứ trung thực và mang tính dân chủ, phong cách ấy về sau lại bị nhiều người lên án là u ám, và một số công trình tốt nhất của nó đã bị phá dỡ trước khi danh tiếng của chúng kịp hồi phục.\n\n**E** Đến những năm 1970, một phản ứng đã hình thành chống lại sự nghiêm khắc mà chủ nghĩa hiện đại để lại phía sau. Chủ nghĩa hậu hiện đại, như nó được gọi, đã từ chối ý niệm rằng chỉ có một ngôn ngữ chân chính duy nhất của hình thức. Thay vào đó, nó vay mượn một cách vui đùa từ nhiều phong cách quá khứ cùng một lúc, pha trộn các họa tiết cổ điển với màu sắc tươi sáng và những điểm nhấn mỉa mai, như thể để nhắc nhở những người xem rằng kiến trúc cũng có thể đùa cợt.\n\n**F** Không phong cách nào trong số này đã xóa sạch hoàn toàn những phong cách đến trước nó, và phần lớn công trình đương đại đều vay mượn từ nhiều phong cách cùng lúc, với tới bất cứ ngữ vựng nào phù hợp với địa điểm và mục đích. Liệu sự pha trộn ấy đại diện cho một sự chín muồi của thị hiếu hay chỉ đơn thuần là sự thiếu vắng một niềm tin chung vẫn còn là một vấn đề mà các nhà phê bình tiếp tục bất đồng.","practice_support":{"schema_version":1,"source_sha256":"02b28a1ad50f84b8ae5c08e0bcf052c7c18704fb8d782ec7dc05ed984c64f649","translation_sha256":"88b77a4aa419c3862702e34418d3b29e8c481c60b40b7478509a354e6c4ab0cb","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"9b7d0fe84651048d525c99dfe8aeacc688a392a475012ab30f6a12db976941eb","source":"the eye is drawn upward towards heaven","precision":"quote","illustrations":[]},"2":{"question_sha256":"b54529811cb61be7ef71007eb846baef2c5222fc35ba033b5fb404130e2aea2d","source":"left concrete bare and exposed a building's structure plainly","precision":"quote","illustrations":[]},"3":{"question_sha256":"65e716ea223eadb511edc55152ca893b4ba97b4390090496564343629a9f3b25","source":"the appearance of an object should arise directly from its function","precision":"quote","illustrations":[]},"4":{"question_sha256":"2d353256f03359428527be1fdd3ff292ed32d667f52c5c6404c658bfcc0480a1","source":"borrowed playfully from many past styles at once","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"pointed","definition":"nhọn, có đầu nhọn (nói về vòm)","example":"By replacing heavy round arches with pointed ones and ribbed vaults, its builders could raise taller, thinner walls, hollowed out by wide windows.","aliases":[]},{"term":"devotion","definition":"lòng thành kính","example":"The effect was deliberate: the eye is drawn upward towards heaven, and once-dark interiors are flooded with coloured light, turning the structure itself into an expression of devotion.","aliases":[]},{"term":"ornament","definition":"chi tiết trang trí","example":"Rejecting ornament as dishonest, its designers held that the appearance of an object should arise directly from its function and from the straightforward use of modern industrial materials such as steel and glass.","aliases":[]},{"term":"raw concrete","definition":"bê tông để mộc","example":"Brutalism, named partly for the French béton brut, \"raw concrete\", left concrete bare and exposed a building's structure plainly rather than hiding it.","aliases":[]},{"term":"demolished","definition":"bị phá dỡ","example":"Conceived as honest and democratic, the style was later condemned by many as bleak, and some of its finest works were demolished before their reputations could recover.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["arts","history"],"skill_focus":"detail","word_count":null,"estimated_minutes":14},{"id":"927626aa-24cb-4cd8-967e-60613afb4cb0","slug":"matching-schools-of-economic-thought","title":"Matching — Schools of Economic Thought","library":"l2_skill","status":"published","body_markdown":"**A** Ask three economists to explain a recession and one may collect three incompatible diagnoses. This is not a sign that the discipline has failed; rather, it reflects the fact that economics has long been organised into competing schools, each resting on different assumptions about how people behave and how markets work.\n\n**B** The oldest of these is the classical tradition, associated with Adam Smith and the writers who followed him. It pictures an economy populated by rational, self-interested individuals whose countless private decisions, coordinated through prices, tend to pull the system back towards balance. On this view, if markets are left largely alone, temporary disruptions will correct themselves without outside help.\n\n**C** That confidence was badly shaken by the Depression of the 1930s, when unemployment remained high for years with no sign of self-correction. John Maynard Keynes argued that economies could become stuck far below their capacity, and that, in such conditions, government spending might be needed to revive demand. Keynesian economics thus made an active role for the state central rather than exceptional.\n\n**D** A later challenge came from the monetarists, led by Milton Friedman, who accepted markets' tendency to settle but disputed how to manage them. For monetarists, the quantity of money circulating in an economy is the principal lever over the price level; control the money supply with a steady hand, they argued, and inflation can be tamed without the heavy intervention Keynesians favoured.\n\n**E** More recently, behavioural economists have questioned a premise all three older schools shared: that people decide rationally. Drawing on psychology, they have documented systematic, repeatable mistakes — overconfidence, an exaggerated fear of loss, a tendency to be swayed by how a choice is framed — that conventional models had quietly assumed away.\n\n**F** None of these schools has driven the others from the field, and most working economists now borrow from several at once, reaching for whichever framework seems to fit the problem in front of them. A central bank fighting inflation may lean on monetarist instincts, while a government facing a slump turns instinctively to Keynesian remedies. Whether that pragmatic mixture represents a maturing synthesis or merely an unresolved argument dressed in technical language is itself a matter on which reasonable people continue to disagree.","metadata":{"grammar_focus":[{"tip":"Cụm '-ed' kẹp giữa hai dấu phẩy thường là bổ nghĩa bị động rút gọn — tách ra để tìm động từ chính của chủ ngữ.","point":"Mệnh đề quan hệ rút gọn (-ing) hậu bổ nghĩa","review":"whose + N = mệnh đề quan hệ chỉ sở hữu. Cụm V3 (coordinated…) = mệnh đề quan hệ bị động rút gọn (which is/are + V3).","example":"It pictures an economy populated by rational, self-interested individuals **whose countless private decisions, coordinated through prices, tend to pull the system back towards balance**.","analysis":"Mệnh đề quan hệ sở hữu 'whose … decisions … tend to pull' bổ nghĩa cho 'individuals'; lồng bên trong là cụm phân từ quá khứ rút gọn 'coordinated through prices' (= which are coordinated…), chèn giữa chủ ngữ 'decisions' và động từ 'tend' như một cụm bị động xen ngang. Cấu trúc nhiều tầng điển hình C1."},{"tip":"Mệnh lệnh + and + result là cách diễn đạt điều kiện rất súc tích trong văn nghị luận; nhận ra để hiểu đúng quan hệ nhân–quả.","point":"Mệnh lệnh + 'and' diễn đạt điều kiện (Imperative conditional)","review":"Imperative + and + clause = If + S + V…, … Mệnh đề chêm 'they argued/said' tách bằng dấu phẩy, không đổi cấu trúc câu.","example":"**control the money supply with a steady hand, they argued, and inflation can be tamed**","analysis":"Mệnh lệnh 'control…' + 'and' + mệnh đề kết quả bị động 'inflation can be tamed' = câu điều kiện ẩn (If you control…, inflation can be tamed). 'they argued' là mệnh đề chêm (parenthetical) chỉ nguồn ý kiến. Bị động 'can be tamed' lược tác nhân."},{"tip":"Danh từ trừu tượng (premise/idea/claim) + 'that…' = nội dung mệnh đề ấy; trong matching, đây chính là 'tiền đề/quan điểm' cần ghép.","point":"Mệnh đề danh ngữ đồng vị giải thích 'a premise … : that …'","review":"N + dấu hai chấm + 'that + clause' = mệnh đề đồng vị nêu nội dung của danh từ trừu tượng (idea/premise/fact that…).","example":"have questioned a premise all three older schools shared: **that people decide rationally**","analysis":"Sau dấu hai chấm, mệnh đề danh ngữ 'that people decide rationally' là cụm đồng vị, giải thích nội dung của 'a premise'. Trước đó 'a premise [that] all three older schools shared' là mệnh đề quan hệ tân ngữ đã lược 'that'. Như vậy một danh từ được vừa hậu bổ nghĩa vừa đồng vị hoá."},{"tip":"Đoạn kết 'Whether… is itself a matter…disagree' báo hiệu tác giả không nghiêng hẳn về bên nào — câu hỏi quan điểm thường yêu cầu nhận ra sự lưỡng lự này.","point":"Mệnh đề danh ngữ 'Whether A or B' làm chủ ngữ + bổ ngữ danh từ có mệnh đề quan hệ","review":"Whether A or B + is a matter on which… = liệu A hay B vẫn là vấn đề mà… (bỏ ngỏ). 'on which' = mệnh đề quan hệ trang trọng.","example":"**Whether that pragmatic mixture represents a maturing synthesis or merely an unresolved argument dressed in technical language is itself a matter** on which reasonable people continue to disagree.","analysis":"Mệnh đề 'Whether A or B' làm chủ ngữ của 'is'; 'itself' nhấn mạnh; bổ ngữ 'a matter' được mệnh đề quan hệ 'on which reasonable people…disagree' (giới từ + which) bổ nghĩa. B chứa cụm phân từ rút gọn bị động 'dressed in technical language'. Câu bỏ ngỏ kết luận."}],"translation_vi":"**A** Hãy hỏi ba nhà kinh tế học giải thích một cuộc suy thoái và người ta có thể thu về ba chẩn đoán không tương thích với nhau. Đây không phải là dấu hiệu cho thấy ngành học này đã thất bại; đúng hơn, nó phản ánh sự thật rằng kinh tế học từ lâu đã được tổ chức thành những trường phái cạnh tranh, mỗi trường phái dựa trên những giả định khác nhau về cách con người hành xử và cách thị trường vận hành.\n\n**B** Lâu đời nhất trong số này là truyền thống cổ điển, gắn với Adam Smith và những tác giả theo sau ông. Nó hình dung một nền kinh tế gồm những cá nhân duy lý, vị kỷ mà vô số những quyết định riêng tư của họ, được phối hợp thông qua giá cả, có xu hướng kéo hệ thống trở lại về phía cân bằng. Theo quan điểm này, nếu thị trường phần lớn được để yên, những xáo trộn tạm thời sẽ tự điều chỉnh mà không cần sự trợ giúp từ bên ngoài.\n\n**C** Sự tự tin đó đã bị lung lay nghiêm trọng bởi cuộc Đại Suy thoái những năm 1930, khi tỷ lệ thất nghiệp duy trì ở mức cao trong nhiều năm mà không có dấu hiệu tự điều chỉnh. John Maynard Keynes lập luận rằng các nền kinh tế có thể bị mắc kẹt ở mức thấp hơn nhiều so với năng lực của chúng, và rằng, trong những điều kiện như vậy, chi tiêu của chính phủ có thể là cần thiết để hồi sinh nhu cầu. Kinh tế học Keynes do đó đã biến vai trò chủ động của nhà nước thành trung tâm thay vì ngoại lệ.\n\n**D** Một thách thức về sau đến từ những nhà tiền tệ học, dẫn đầu bởi Milton Friedman, những người chấp nhận xu hướng tự ổn định của thị trường nhưng tranh luận về cách quản lý chúng. Đối với những nhà tiền tệ học, lượng tiền lưu thông trong một nền kinh tế là đòn bẩy chủ yếu đối với mức giá; hãy kiểm soát cung tiền với một bàn tay vững vàng, họ lập luận, thì lạm phát có thể được chế ngự mà không cần sự can thiệp nặng nề mà những người theo Keynes ưa chuộng.\n\n**E** Gần đây hơn, những nhà kinh tế học hành vi đã chất vấn một tiền đề mà cả ba trường phái cũ hơn đều chia sẻ: rằng con người quyết định một cách duy lý. Dựa trên tâm lý học, họ đã ghi nhận những sai lầm có hệ thống, lặp lại được — sự tự tin thái quá, một nỗi sợ mất mát bị phóng đại, một xu hướng bị tác động bởi cách một lựa chọn được trình bày — những điều mà các mô hình thông thường đã lặng lẽ giả định cho qua.\n\n**F** Không trường phái nào trong số này đã đẩy được những trường phái khác ra khỏi cuộc chơi, và hầu hết các nhà kinh tế học đang làm việc giờ đây vay mượn từ nhiều trường phái cùng một lúc, với tới bất cứ khuôn khổ nào có vẻ phù hợp với vấn đề đang ở trước mặt họ. Một ngân hàng trung ương chống lạm phát có thể nghiêng về những bản năng tiền tệ học, trong khi một chính phủ đối mặt với một cuộc suy sụp thì theo bản năng quay sang những phương thuốc của Keynes. Liệu sự pha trộn thực dụng đó đại diện cho một sự tổng hợp đang trưởng thành hay chỉ đơn thuần là một cuộc tranh luận chưa được giải quyết khoác lên ngôn ngữ kỹ thuật tự nó là một vấn đề mà những người có lý trí vẫn tiếp tục bất đồng.","practice_support":{"schema_version":1,"source_sha256":"4ad5d2d3c1f8d8eb0fea219b519dea40ac0e0132cecb196666b2ab445655c01e","translation_sha256":"f201bd77cf33f2ca79afb98ff0ea76c342f0c37f3a12f9cf23391ef4ca10e71b","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"5654d04aeb75cf2a1ce430dd25015a352fa45348fa8e951f5d2c92ad3a616a62","source":"temporary disruptions will correct themselves without outside help","precision":"quote","illustrations":[]},"2":{"question_sha256":"804780e16828c8dfc2b463db78cc334cb3ae30c98cf0474bbc5285e0b8d91ce8","source":"the quantity of money circulating in an economy is the principal lever over the price level","precision":"quote","illustrations":[]},"3":{"question_sha256":"393800c18af6009d1b0926d5703b879416407423bb69d50e5775800d764ca8cd","source":"rational, self-interested individuals","precision":"quote","illustrations":[]},"4":{"question_sha256":"9841591466e6484b63feae2c9d5597fa6ca26faa5a866e633072f1b7289af8ce","source":"systematic, repeatable mistakes","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"recession","definition":"suy thoái kinh tế","example":"A Ask three economists to explain a recession and one may collect three incompatible diagnoses.","aliases":[]},{"term":"self-interested","definition":"hành động vì lợi ích của bản thân","example":"It pictures an economy populated by rational, self-interested individuals whose countless private decisions, coordinated through prices, tend to pull the system back towards balance.","aliases":[]},{"term":"revive demand","definition":"khôi phục nhu cầu","example":"John Maynard Keynes argued that economies could become stuck far below their capacity, and that, in such conditions, government spending might be needed to revive demand.","aliases":[]},{"term":"money supply","definition":"lượng cung tiền","example":"For monetarists, the quantity of money circulating in an economy is the principal lever over the price level; control the money supply with a steady hand, they argued, and inflation can be tamed without the heavy intervention Keynesians favoured.","aliases":[]},{"term":"overconfidence","definition":"sự tự tin quá mức","example":"Drawing on psychology, they have documented systematic, repeatable mistakes — overconfidence, an exaggerated fear of loss, a tendency to be swayed by how a choice is framed — that conventional models had quietly assumed away.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["business","social-sciences"],"skill_focus":"detail","word_count":null,"estimated_minutes":13},{"id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","slug":"matching-stages-of-language-learning","title":"Matching — Theories of Language Learning","library":"l2_skill","status":"published","body_markdown":"**A** Few questions in the human sciences have proved as stubbornly contested as the one a child answers effortlessly: how does a young mind, in the space of a few short years, master a system of rules that even trained linguists struggle to describe? The twentieth century produced a sequence of rival answers, each illuminating and each, in time, found wanting in some respect.\n\n**B** The earliest of these to dominate was behaviourism, associated above all with B. F. Skinner. On this account, language is learned much as any other behaviour: through imitation and reinforcement. A toddler who says \"milk\" and is rewarded with both the drink and an approving smile is, in effect, being trained to repeat the utterance, while sounds that resemble adult speech are gradually shaped by the responses they provoke.\n\n**C** This tidy picture was famously dismantled by Noam Chomsky, who pointed out that children routinely produce sentences they cannot possibly have heard and been rewarded for. To explain such creativity, Chomsky proposed that the brain arrives already equipped with a \"universal grammar\" — an innate template, present from birth, that underlies the grammar of every human language and needs only exposure to a particular tongue to be set in motion.\n\n**D** Where the nativist account looks inward to biology, the social-interactionist tradition, traced to Lev Vygotsky, looks outward to relationships. For Vygotsky, thought and language alike take shape through dialogue with more capable partners — parents, teachers, older children — who guide the learner through tasks just beyond their independent reach. Language, on this view, is less a private endowment than a tool first borrowed from others and only later made one's own.\n\n**E** More recently, Michael Tomasello has advanced a usage-based approach that, in a sense, seeks middle ground. Rejecting the idea of a fixed inborn grammar, he argues that language emerges from more general cognitive gifts, above all the distinctively human capacity to read the shared intentions behind another person's actions. The child who grasps what an adult is trying to do is already halfway to grasping what the adult is trying to say.\n\n**F** No single theory has swept the field, and perhaps none should be expected to. It may be that each captures a genuine fragment of an extraordinarily complex process — that reinforcement, innate structure, social guidance and intention-reading all play their part, in proportions that remain difficult to fix. The debate, like the child's mind itself, resists any neat conclusion.","metadata":{"grammar_focus":[{"tip":"'Few questions have proved as … as X' = X gây tranh cãi bậc nhất — cách nói nhấn mạnh thay cho 'X is the most contested'.","point":"Cấu trúc so sánh 'as … as' + mệnh đề quan hệ rút gọn","review":"as + adj + as = ngang bằng. 'Few + N' = nghĩa phủ định (ít đến mức gần như không). Mệnh đề quan hệ tân ngữ có thể lược 'that'.","example":"Few questions in the human sciences **have proved as stubbornly contested as** the one a child answers effortlessly","analysis":"So sánh ngang bằng 'as + adv + adj + as' ('as stubbornly contested as'). Sau 'as' thứ hai là 'the one [that] a child answers effortlessly' — mệnh đề quan hệ tân ngữ đã lược 'that'. Chủ ngữ 'Few questions' mang nghĩa phủ định (rất ít → hầu như không), nhấn mạnh mức độ gây tranh cãi cao nhất."},{"tip":"Cụm '-ed' sau dấu phẩy = thông tin bổ sung bị động; trong matching-features, đây thường gắn nhân vật với trường phái (Skinner ↔ behaviourism).","point":"Mệnh đề quan hệ rút gọn bị động (past participle) hậu bổ nghĩa","review":"N, V3… = mệnh đề quan hệ bị động rút gọn (which is/was + V3). the + so sánh nhất + to V = … nhất để/mà làm gì.","example":"The earliest of these to dominate was behaviourism, **associated above all with B. F. Skinner**.","analysis":"Cụm phân từ quá khứ 'associated above all with…' = mệnh đề quan hệ bị động rút gọn ('which is associated…'), bổ nghĩa cho 'behaviourism' sau dấu phẩy (non-defining). Trước đó 'The earliest of these to dominate' dùng to-infinitive 'to dominate' hậu bổ nghĩa cho cụm so sánh nhất 'the earliest'."},{"tip":"'Where A …, B …' đầu câu là tín hiệu tương phản hai đối tượng — matching hay khai thác đúng thế đối lập này.","point":"Mệnh đề tương phản fronting với 'Where' (= whereas)","review":"Where + clause (đầu câu) = trong khi/ở phương diện mà (tương phản, ≈ whereas). Giữ song song để tăng tương phản.","example":"**Where the nativist account looks inward to biology, the social-interactionist tradition … looks outward to relationships.**","analysis":"'Where + S + V, S + V' dùng nghĩa tương phản ('trong khi/ở chỗ mà…'), không phải nơi chốn cụ thể. Hai mệnh đề đối xứng: 'looks inward to biology' // 'looks outward to relationships' — song song hoá triệt để (parallelism) để làm nổi sự đối lập giữa hai trường phái."},{"tip":"'less X than Y' định nghĩa lại khái niệm theo hướng Y — trong sentence-ending/features, Y là đặc trưng cần ghép, X là bẫy.","point":"Cấu trúc nhấn mạnh 'less … than' định nghĩa lại","review":"less A than B = không phải A mà đúng hơn là B. Hai V3 song song hậu bổ nghĩa cùng một danh từ → giữ cân đối.","example":"Language, on this view, is **less a private endowment than a tool** first borrowed from others and only later made one's own.","analysis":"Khung 'less A than B' phủ định nhẹ A, đề cao B (= không phải A cho bằng B). Cụm 'a tool first borrowed from others and only later made one's own' chứa hai phân từ quá khứ song song ('borrowed' // 'made') rút gọn bổ nghĩa 'a tool', với trạng từ tương phản 'first … only later'."}],"translation_vi":"**A** Ít câu hỏi nào trong khoa học về con người lại gây tranh cãi dai dẳng như câu hỏi mà một đứa trẻ trả lời một cách dễ dàng: làm thế nào mà một tâm trí non trẻ, chỉ trong vài năm ngắn ngủi, lại làm chủ được một hệ thống quy tắc mà ngay cả các nhà ngôn ngữ học được đào tạo bài bản cũng vất vả để mô tả? Thế kỷ hai mươi đã sản sinh ra một chuỗi các câu trả lời đối lập nhau, mỗi câu đều soi sáng vấn đề và mỗi câu, theo thời gian, đều bị phát hiện là thiếu sót ở khía cạnh nào đó.\n\n**B** Câu trả lời sớm nhất chiếm ưu thế trong số này là chủ nghĩa hành vi (behaviourism), gắn liền trên hết với B. F. Skinner. Theo quan điểm này, ngôn ngữ được học giống như bất kỳ hành vi nào khác: thông qua bắt chước và củng cố (reinforcement). Một đứa trẻ tập đi nói \"sữa\" và được thưởng cả thức uống lẫn một nụ cười tán thưởng, thực chất, đang được huấn luyện để lặp lại lời nói đó, trong khi những âm thanh giống tiếng nói của người lớn dần dần được định hình bởi những phản ứng mà chúng gợi ra.\n\n**C** Bức tranh gọn gàng này đã bị Noam Chomsky tháo dỡ một cách nổi tiếng, khi ông chỉ ra rằng trẻ em thường xuyên tạo ra những câu mà chúng không thể nào đã từng nghe và đã từng được thưởng cho chúng. Để giải thích sự sáng tạo như vậy, Chomsky đề xuất rằng bộ não đã được trang bị sẵn một \"ngữ pháp phổ quát\" (universal grammar) — một khuôn mẫu bẩm sinh, hiện diện từ khi sinh ra, làm nền tảng cho ngữ pháp của mọi ngôn ngữ con người và chỉ cần được tiếp xúc với một thứ tiếng cụ thể là được kích hoạt.\n\n**D** Trong khi quan điểm bẩm sinh (nativist) nhìn vào bên trong, hướng tới sinh học, thì truyền thống tương tác xã hội (social-interactionist), bắt nguồn từ Lev Vygotsky, lại nhìn ra bên ngoài, hướng tới các mối quan hệ. Đối với Vygotsky, tư duy và ngôn ngữ đều định hình thông qua đối thoại với những người bạn đồng hành có năng lực hơn — cha mẹ, thầy cô, những đứa trẻ lớn hơn — những người dẫn dắt người học vượt qua các nhiệm vụ vừa vượt quá tầm với độc lập của họ. Ngôn ngữ, theo quan điểm này, không phải là một thiên phú riêng tư cho bằng là một công cụ thoạt đầu được mượn từ người khác và chỉ về sau mới được biến thành của riêng mình.\n\n**E** Gần đây hơn, Michael Tomasello đã đưa ra một cách tiếp cận dựa trên sử dụng (usage-based) mà, theo một nghĩa nào đó, tìm kiếm điểm trung dung. Bác bỏ ý tưởng về một ngữ pháp bẩm sinh cố định, ông lập luận rằng ngôn ngữ nảy sinh từ những năng khiếu nhận thức tổng quát hơn, trên hết là khả năng đặc trưng của con người trong việc đọc ra những ý định chung đằng sau hành động của người khác. Đứa trẻ nắm bắt được điều một người lớn đang cố gắng làm thì đã đi được nửa chặng đường tới việc nắm bắt điều người lớn đó đang cố gắng nói.\n\n**F** Không một lý thuyết nào đã quét sạch toàn bộ lĩnh vực, và có lẽ không nên kỳ vọng lý thuyết nào làm được điều đó. Có thể là mỗi lý thuyết nắm bắt được một mảnh ghép đích thực của một quá trình cực kỳ phức tạp — rằng sự củng cố, cấu trúc bẩm sinh, sự dẫn dắt xã hội và việc đọc ý định, tất cả đều đóng vai trò của mình, với những tỷ lệ vẫn khó xác định. Cuộc tranh luận, cũng như chính tâm trí của đứa trẻ, kháng cự lại mọi kết luận gọn gàng.","practice_support":{"schema_version":1,"source_sha256":"d07c9ed9f5d7ee4f1fcbc3ed5d393ebea68ff8e68ae516c6b05416099d0ab6c7","translation_sha256":"cd6e5d965b8caf98bc505fd023e37dadbde86322d8f33109cb1030a89ca2d1e8","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"0cadaf533201c80515bf33aecdd43045bddcb5002650ce7ad4842ec2c95fac55","source":"through imitation and reinforcement","precision":"quote","illustrations":[]},"2":{"question_sha256":"fdc70fc25be5d38220bfeb5c2ebadc96b96848393efdc4d8b79f47e032b79048","source":"the brain arrives already equipped with a \"universal grammar\"","precision":"quote","illustrations":[]},"3":{"question_sha256":"715dc05431a5fd1b1d3c135af8b242979c2a9301a03ad0198c0b90852c92443e","source":"the distinctively human capacity to read the shared intentions behind another person's actions","precision":"quote","illustrations":[]},"4":{"question_sha256":"6c5dc019f24e70fa778b7aa4487bc529444543167f97147449fcd1d1ed6ae356","source":"children routinely produce sentences they cannot possibly have heard","precision":"quote","illustrations":[]},"5":{"question_sha256":"b6e11385699ea8453974dccf83312629efb64ca4fbc7296c2e398a4ac095b7de","source":"thought and language alike take shape through dialogue with more capable partners","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"imitation","definition":"sự bắt chước","example":"On this account, language is learned much as any other behaviour: through imitation and reinforcement.","aliases":[]},{"term":"reinforcement","definition":"sự củng cố hành vi qua phản hồi hoặc phần thưởng","example":"On this account, language is learned much as any other behaviour: through imitation and reinforcement.","aliases":[]},{"term":"utterance","definition":"một lời hoặc phát ngôn","example":"A toddler who says \"milk\" and is rewarded with both the drink and an approving smile is, in effect, being trained to repeat the utterance, while sounds that resemble adult speech are gradually shaped by the responses they provoke.","aliases":[]},{"term":"innate","definition":"bẩm sinh","example":"To explain such creativity, Chomsky proposed that the brain arrives already equipped with a \"universal grammar\" — an innate template, present from birth, that underlies the grammar of every human language and needs only exposure to a particular tongue to be set in motion.","aliases":[]},{"term":"shared intentions","definition":"những ý định được cùng hiểu và chia sẻ","example":"Rejecting the idea of a fixed inborn grammar, he argues that language emerges from more general cognitive gifts, above all the distinctively human capacity to read the shared intentions behind another person's actions.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["education","psychology"],"skill_focus":"detail","word_count":null,"estimated_minutes":15},{"id":"2ade381b-2d88-4870-92f0-f278734ff2a4","slug":"matching-styles-of-painting","title":"Matching — Styles of Painting","library":"l2_skill","status":"published","body_markdown":"**A** Western painting did not evolve in a straight line but split, again and again, into\nrival movements, each convinced it had found a truer way of seeing. Four of these,\nemerging within fifty years, did much to shape what is meant by modern art.\n\n**B** By the 1850s a group of French painters led by Gustave Courbet had grown tired of\nthe grand mythological and historical scenes that the academies admired. Realism, as the\nmovement was called, turned instead to the everyday lives of ordinary people — labourers,\npeasants and the urban poor — and aimed to show them honestly, without flattery or\nromance.\n\n**C** A generation later, the Impressionists pushed in a different direction. Artists such\nas Claude Monet abandoned the studio to paint outdoors, trying to capture the shifting\neffects of natural light on water, snow and city streets with quick, visible\nbrushstrokes. The movement owed its name to mockery: a critic borrowed the title of one\nof Monet's paintings, 'Impression, Sunrise', to ridicule the unfinished look of the work\nshown in 1874.\n\n**D** Around 1907, Pablo Picasso and Georges Braque went further still, dismantling the\nidea that a painting should show a scene from a single fixed point. In the style that\nbecame known as Cubism, objects were broken into geometric facets and reassembled so that\nseveral viewpoints appeared at once, as if the subject were being seen from all sides\nsimultaneously.\n\n**E** The final break came after the First World War. Inspired by new theories of the\nmind, the Surrealists — among them Salvador Dalí and René Magritte — abandoned the visible\nworld almost entirely. Following a manifesto published in 1924, they filled their canvases\nwith dreamlike, impossible images drawn from the hidden workings of the unconscious mind.\n\n**F** These movements often overlapped, and few artists fit neatly into a\nsingle label. Yet together they trace a steady loosening of old rules — a shift from\npainting the world as it looks towards painting it as it is felt or imagined.","metadata":{"grammar_focus":[{"tip":"Bị động lược tác nhân (ai vẽ) để tập trung vào kỹ thuật (objects … broken) — bám danh từ chịu tác động khi ghép feature với trường phái.","point":"Câu bị động (passive voice) ở quá khứ với động từ song song","review":"Bị động: be + V3; hai V3 nối bằng 'and' dùng chung 'be'. so that + S + V = sao cho/để mà (mục đích–kết quả).","example":"objects **were broken** into geometric facets and **reassembled** so that several viewpoints appeared at once","analysis":"'were broken … and reassembled' là bị động quá khứ; hai phân từ 'broken' và 'reassembled' nối song song bằng 'and' cùng dùng một trợ động từ 'were'. 'so that + mệnh đề' nêu kết quả của việc lắp ghép."},{"tip":"Cụm V-ing đầu câu nêu hoàn cảnh/trình tự — đọc tiếp tới chủ ngữ chính ngay sau dấu phẩy để gắn đúng 'ai làm gì', tránh hiểu lệch mốc thời gian.","point":"Mệnh đề phân từ hiện tại (participle clause) mở đầu câu","review":"Participle clause đầu câu: V-ing …, S + V. Rút gọn bị động: N + V3 (a manifesto published). Chủ ngữ phân từ phải khớp chủ ngữ chính.","example":"**Following a manifesto published in 1924**, they filled their canvases with dreamlike, impossible images","analysis":"'Following a manifesto …' là mệnh đề phân từ mở đầu câu, rút gọn ý 'After they followed a manifesto'. Bên trong, 'published in 1924' là mệnh đề quan hệ rút gọn bị động bổ nghĩa cho 'a manifesto'. Chủ ngữ ngầm của 'following' là 'they'."},{"tip":"'as if' báo hiệu một hình ảnh giả định/ẩn dụ, KHÔNG phải sự kiện có thật — đừng chọn đáp án coi nội dung sau 'as if' là một sự việc đã xảy ra.","point":"Mệnh đề so sánh không thực với 'as if' + 'were'","review":"as if/as though + quá khứ giả định (were/V2) = như thể (điều không thật). Bị động đang diễn ra: be + being + V3.","example":"several viewpoints appeared at once, **as if the subject were being seen** from all sides simultaneously","analysis":"'as if + S + were' diễn tả một so sánh giả định, không có thật ('như thể'). Dùng 'were' (thể giả định) thay 'was', kết hợp bị động đang diễn ra 'being seen' để tả cảm giác chủ thể được nhìn từ mọi phía cùng lúc."}],"translation_vi":"**A** Hội họa phương Tây không tiến hóa theo một đường thẳng mà cứ tách ra, lần này đến lần khác, thành những trường phái đối nghịch, mỗi trường phái đều tin chắc mình đã tìm ra một cách nhìn chân thực hơn. Bốn trong số những trường phái này, xuất hiện trong vòng hơn nửa thế kỷ một chút, đã góp phần lớn định hình điều mà người ta gọi là nghệ thuật hiện đại.\n\n**B** Đến thập niên 1850, một nhóm họa sĩ Pháp dẫn đầu bởi Gustave Courbet đã chán những cảnh thần thoại và lịch sử hoành tráng mà các viện hàn lâm ngưỡng mộ. Chủ nghĩa hiện thực, tên gọi của trường phái này, thay vào đó hướng tới cuộc sống thường nhật của những con người bình thường — người lao động, nông dân và dân nghèo thành thị — và nhắm tới việc khắc họa họ một cách trung thực, không tô vẽ hay lãng mạn hóa.\n\n**C** Một thế hệ sau, các họa sĩ Ấn tượng đẩy theo một hướng khác. Những nghệ sĩ như Claude Monet rời bỏ xưởng vẽ để vẽ ngoài trời, cố nắm bắt những hiệu ứng biến đổi của ánh sáng tự nhiên trên mặt nước, tuyết và đường phố bằng những nét cọ nhanh, lộ rõ. Trường phái này có được chính cái tên của mình từ sự chế giễu: một nhà phê bình đã mượn nhan đề của một bức tranh của Monet, \"Ấn tượng, Mặt trời mọc\", để nhạo báng vẻ dở dang của tác phẩm trưng bày năm 1874.\n\n**D** Khoảng năm 1907, Pablo Picasso và Georges Braque còn đi xa hơn nữa, phá bỏ quan niệm rằng một bức tranh phải thể hiện một cảnh từ một điểm nhìn cố định duy nhất. Trong phong cách về sau được gọi là Lập thể, các vật thể bị bẻ thành những mặt cắt hình học và lắp ghép lại sao cho nhiều điểm nhìn xuất hiện cùng một lúc, như thể chủ thể đang được nhìn từ mọi phía đồng thời.\n\n**E** Sự đứt gãy cuối cùng đến sau Thế chiến thứ nhất. Lấy cảm hứng từ những lý thuyết mới về tâm trí, các họa sĩ Siêu thực — trong số đó có Salvador Dalí và René Magritte — gần như từ bỏ hoàn toàn thế giới hữu hình. Theo một tuyên ngôn công bố năm 1924, họ phủ kín các bức toan bằng những hình ảnh như mộng, bất khả, rút ra từ những vận hành ẩn giấu của tâm trí vô thức.\n\n**F** Những trường phái này thường chồng lấn và tranh cãi nhau, và ít nghệ sĩ nào vừa khít một nhãn duy nhất. Tuy vậy, gộp lại chúng phác nên một sự nới lỏng đều đặn các quy tắc cũ — một hành trình từ vẽ thế giới như nó hiện ra tới vẽ thế giới như nó được cảm nhận hay tưởng tượng.","practice_support":{"schema_version":1,"source_sha256":"e339e70de2bedc3fb16ec27bea7a978c9bfdc8833222e27693eb269318756d7e","translation_sha256":"f672165d952266730ba359b71521828b2ba4793a09f2b778edb4f4a79cd08f26","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"d2adcc70e893a8505094259d2997a172d282efa1bc56608d5b25013380b732e8","source":"trying to capture the shifting effects of natural light","precision":"quote","illustrations":[]},"2":{"question_sha256":"166541ed4528302a6b5deb62cd683072277648d9effd81f8b3eefceb6f5213f4","source":"several viewpoints appeared at once","precision":"quote","illustrations":[]},"3":{"question_sha256":"2bc7a1fa7b937e98021a50a92d804d5140231cdacda4fb6456d8fb42744e1392","source":"dreamlike, impossible images drawn from the hidden workings of the unconscious mind","precision":"quote","illustrations":[]},"4":{"question_sha256":"d81b6b6fa94e37bc60576dc3ce5a10e6e1663adeb40ea4b39e5cd485cfcacd71","source":"the everyday lives of ordinary people","precision":"quote","illustrations":[]},"5":{"question_sha256":"974baca7c163e7446fdcb358216300bf4f7d525eb21102fc1f8f5b6619fbccbe","source":"a critic borrowed the title of one of Monet's paintings","precision":"quote","illustrations":[]},"6":{"question_sha256":"e210717c9a85726f1485441046db6e37349b8add81c6733fc05119c8971a681a","source":"drawn from the hidden workings of the unconscious mind","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"labourers","definition":"những người lao động chân tay","example":"Realism, as the movement was called, turned instead to the everyday lives of ordinary people — labourers, peasants and the urban poor — and aimed to show them honestly, without flattery or romance.","aliases":[]},{"term":"mockery","definition":"sự chế giễu","example":"The movement owed its name to mockery: a critic borrowed the title of one of Monet's paintings, 'Impression, Sunrise', to ridicule the unfinished look of the work shown in 1874.","aliases":[]},{"term":"geometric facets","definition":"các mảng hình học","example":"In the style that became known as Cubism, objects were broken into geometric facets and reassembled so that several viewpoints appeared at once, as if the subject were being seen from all sides simultaneously.","aliases":[]},{"term":"reassembled","definition":"được ráp lại theo cách mới","example":"In the style that became known as Cubism, objects were broken into geometric facets and reassembled so that several viewpoints appeared at once, as if the subject were being seen from all sides simultaneously.","aliases":[]},{"term":"unconscious mind","definition":"tâm trí vô thức","example":"Following a manifesto published in 1924, they filled their canvases with dreamlike, impossible images drawn from the hidden workings of the unconscious mind.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["arts"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","slug":"matching-theories-of-emotion","title":"Matching — Theories of Emotion","library":"l2_skill","status":"published","body_markdown":"**A** A person who steps off a kerb, hears a horn and freezes will probably say, afterwards, that fear made the heart pound. Yet the ordering implied by that account — first the feeling, then the racing pulse — is precisely what a century of research on emotion has called into question. Where, in the sequence linking a stimulus, the body and the conscious mind, the emotion actually begins is a problem psychologists have answered in strikingly different ways.\n\n**B** The earliest systematic answer, advanced independently by William James and the Danish physician Carl Lange in the 1880s, inverted common sense. On their account, a frightening sight first triggers a bodily reaction — quickened breathing, a jolt of adrenaline, tensed muscles — and the conscious emotion is simply the mind's reading of those changes. We do not tremble because we are afraid, the slogan ran; we are afraid because we tremble. Each distinct emotion, in this picture, corresponds to its own distinct pattern of physiological response.\n\n**C** Walter Cannon, joined later by Philip Bard, found this implausible. He noted that fear, rage and even excitement are attended by much the same internal upheaval, so the body's response could hardly, by itself, distinguish one emotion from another. He proposed instead that a stimulus reaching the brain sends signals simultaneously down two routes — one producing the bodily arousal, the other producing the conscious feeling — so that the two arrive together rather than one causing the other.\n\n**D** A third position emerged in 1962, when Stanley Schachter and Jerome Singer argued that arousal and interpretation must combine. In their experiment, volunteers received an injection of a stimulant and were then placed with an actor who behaved either cheerfully or angrily; those exposed to cheerfulness reported feeling happy, while those exposed to anger reported irritation, despite sharing an identical physiological state. Emotion, they concluded, requires two factors: a state of arousal and a cognitive label that the surrounding situation supplies.\n\n**E** More recent work has pushed the cognitive element earlier still. Richard Lazarus maintained that even the initial bodily reaction is shaped by appraisal — a rapid, often unconscious assessment of whether an event is threatening, welcome or irrelevant to one's goals. On this reading, the judgement does not merely name an arousal already underway but helps to set it off, so that two people facing the same event may respond quite differently from the very first instant.\n\n**F** No single account has wholly displaced the others, and contemporary theorists tend to treat them as describing different stages of one rapid process rather than rival explanations of the whole. Whether the felt emotion is best understood as the cause of the body's reaction, its consequence, or its inseparable partner remains a question on which the evidence, intriguingly, still points in more than one direction.","metadata":{"grammar_focus":[{"tip":"Chủ ngữ có mệnh đề quan hệ dài → tìm động từ chính ('will say') để không lạc; chuỗi động từ trong who-clause chỉ là mô tả chủ thể.","point":"Mệnh đề quan hệ rút gọn (-ing) hậu bổ nghĩa cho chủ ngữ dài","review":"who + chuỗi V song song = mệnh đề quan hệ; make + O + V (nguyên thể) = khiến ai/cái gì làm gì.","example":"A person **who steps off a kerb, hears a horn and freezes** will probably say, afterwards, that fear made the heart pound.","analysis":"Mệnh đề quan hệ xác định 'who steps… hears… and freezes' với ba động từ song song bổ nghĩa cho chủ ngữ 'A person', đẩy động từ chính 'will say' ra xa. 'afterwards' chêm giữa câu; theo sau là mệnh đề danh ngữ 'that fear made the heart pound' (tân ngữ) chứa cấu trúc sai khiến 'make + O + V-bare'."},{"tip":"'…is precisely what …' nhấn mạnh đúng vào ý phản bác của tác giả — chỗ này hay ra câu hỏi inference/quan điểm.","point":"Câu chẻ chủ ngữ giả 'what … is' (pseudo-cleft / fronting Wh-)","review":"S + be + what + S + V = câu chẻ giả nhấn mạnh phần 'what…'. Cụm V3 (implied…) = mệnh đề quan hệ bị động rút gọn.","example":"the ordering implied by that account … **is precisely what a century of research on emotion has called into question**.","analysis":"Đây là pseudo-cleft đảo: bổ ngữ là mệnh đề danh ngữ 'what a century of research … has called into question'. Chủ ngữ 'the ordering implied by that account' chứa cụm phân từ quá khứ rút gọn 'implied by that account' (= which is implied…). 'call into question' = đặt thành nghi vấn (cụm động từ)."},{"tip":"Mệnh đề Wh- làm chủ ngữ thường rất dài — khoanh từ 'Where' tới động từ 'is' để xác định bộ khung S–V chính.","point":"Mệnh đề nghi vấn gián tiếp (Wh-) làm chủ ngữ","review":"Câu hỏi gián tiếp (Wh- + S + V) có thể làm chủ ngữ: 'Where… begins is a problem'. Trật tự khẳng định (không đảo trợ động từ).","example":"**Where, in the sequence linking a stimulus, the body and the conscious mind, the emotion actually begins** is a problem psychologists have answered in strikingly different ways.","analysis":"Cả một mệnh đề nghi vấn gián tiếp 'Where … the emotion actually begins' được đẩy lên làm chủ ngữ của 'is a problem'. Cụm chêm 'in the sequence linking a stimulus, the body and the conscious mind' (có phân từ 'linking' rút gọn) tách 'Where' khỏi phần còn lại. 'a problem [that] psychologists have answered' lược 'that'."},{"tip":"Đoạn kết 'Whether… remains a question… points in more than one direction' = tác giả không kết luận → matching information cho đoạn 'tổng kết/để ngỏ' (đoạn F).","point":"Mệnh đề danh ngữ 'Whether A, B, or C' làm chủ ngữ + bổ ngữ danh từ","review":"Whether A, B, or C + remains a question = liệu A, B hay C vẫn là câu hỏi. be understood as = được hiểu là. Giữ song song các lựa chọn.","example":"**Whether the felt emotion is best understood as the cause of the body's reaction, its consequence, or its inseparable partner** remains a question on which the evidence … still points in more than one direction.","analysis":"Mệnh đề 'Whether … or …' (ba lựa chọn song song: 'the cause…', 'its consequence', 'its inseparable partner') làm chủ ngữ của 'remains'; bị động 'is best understood as' lược tác nhân. Bổ ngữ 'a question' được mệnh đề quan hệ 'on which… still points' bổ nghĩa. Câu kết bỏ ngỏ."}],"translation_vi":"**A** Một người bước xuống lề đường, nghe thấy tiếng còi xe và đứng sững lại có lẽ sẽ nói, sau đó, rằng nỗi sợ đã khiến tim đập thình thịch. Tuy nhiên, trình tự được ngụ ý trong cách giải thích đó — trước hết là cảm giác, rồi mới đến nhịp tim dồn dập — chính là điều mà một thế kỷ nghiên cứu về cảm xúc đã đặt thành nghi vấn. Cảm xúc thực sự bắt đầu ở đâu, trong chuỗi liên kết một kích thích, cơ thể và tâm trí có ý thức, là một vấn đề mà các nhà tâm lý học đã trả lời theo những cách khác nhau đến mức đáng ngạc nhiên.\n\n**B** Câu trả lời có hệ thống sớm nhất, được William James và bác sĩ người Đan Mạch Carl Lange đưa ra một cách độc lập vào những năm 1880, đã đảo ngược lẽ thường. Theo quan điểm của họ, một cảnh tượng đáng sợ trước hết khởi phát một phản ứng cơ thể — hơi thở gấp gáp, một luồng adrenaline, các cơ bắp căng cứng — và cảm xúc có ý thức chỉ đơn giản là sự đọc hiểu của tâm trí về những thay đổi đó. Chúng ta không run rẩy vì chúng ta sợ hãi, câu khẩu hiệu nói; chúng ta sợ hãi vì chúng ta run rẩy. Mỗi cảm xúc riêng biệt, trong bức tranh này, tương ứng với một khuôn mẫu phản ứng sinh lý riêng biệt của nó.\n\n**C** Walter Cannon, về sau có sự tham gia của Philip Bard, thấy điều này khó tin. Ông lưu ý rằng nỗi sợ, cơn thịnh nộ và thậm chí cả sự phấn khích đều đi kèm với cùng một biến động nội tại như nhau, nên phản ứng của cơ thể khó có thể, tự thân nó, phân biệt được cảm xúc này với cảm xúc khác. Thay vào đó, ông đề xuất rằng một kích thích đến não sẽ gửi các tín hiệu đồng thời theo hai tuyến — một tuyến tạo ra sự kích hoạt cơ thể (arousal), tuyến kia tạo ra cảm giác có ý thức — sao cho cả hai cùng đến một lúc chứ không phải cái này gây ra cái kia.\n\n**D** Một quan điểm thứ ba xuất hiện vào năm 1962, khi Stanley Schachter và Jerome Singer lập luận rằng sự kích hoạt và sự diễn giải phải kết hợp với nhau. Trong thí nghiệm của họ, các tình nguyện viên nhận một mũi tiêm chất kích thích rồi được đặt cùng một diễn viên có hành vi hoặc vui vẻ hoặc giận dữ; những người tiếp xúc với sự vui vẻ báo cáo cảm thấy hạnh phúc, trong khi những người tiếp xúc với sự giận dữ báo cáo cảm thấy bực bội, mặc dù cùng chia sẻ một trạng thái sinh lý y hệt. Họ kết luận, cảm xúc đòi hỏi hai yếu tố: một trạng thái kích hoạt và một nhãn nhận thức mà tình huống xung quanh cung cấp.\n\n**E** Công trình gần đây hơn đã đẩy yếu tố nhận thức lên còn sớm hơn nữa. Richard Lazarus cho rằng ngay cả phản ứng cơ thể ban đầu cũng được định hình bởi sự đánh giá (appraisal) — một sự thẩm định nhanh chóng, thường là vô thức, về việc một sự kiện có đe dọa, đáng mừng hay không liên quan đến các mục tiêu của một người. Theo cách hiểu này, sự phán đoán không chỉ đặt tên cho một sự kích hoạt đã đang diễn ra mà còn giúp khởi phát nó, sao cho hai người đối mặt với cùng một sự kiện có thể phản ứng khá khác nhau ngay từ khoảnh khắc đầu tiên.\n\n**F** Không một cách giải thích nào đã hoàn toàn thay thế được những cách khác, và các nhà lý thuyết đương đại có xu hướng xem chúng như đang mô tả những giai đoạn khác nhau của một quá trình nhanh chóng duy nhất hơn là những lời giải thích đối lập về toàn bộ vấn đề. Liệu cảm xúc được cảm nhận có được hiểu đúng nhất là nguyên nhân của phản ứng cơ thể, là hệ quả của nó, hay là người bạn đồng hành không thể tách rời của nó, vẫn là một câu hỏi mà bằng chứng, một cách thú vị, vẫn còn chỉ về nhiều hơn một hướng.","practice_support":{"schema_version":1,"source_sha256":"e54dcdf9c59c04fb92c5f3a6e43abec75962e7d309f7b7d7e60430534cfb84e7","translation_sha256":"e191099800659ec3c8cb33ee2915a0429445fb50d6d7aed901e11e22ce3938db","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"9fa108147d04753763261e32c56731317f475bbc37d75f82fbc636516bf9a829","source":"the conscious emotion is simply the mind's reading of those changes","precision":"quote","illustrations":[]},"2":{"question_sha256":"460d02c312536c60739e03177f6bf0f6b16a1dbaaf9541835adb5d6746f55071","source":"a state of arousal and a cognitive label that the surrounding situation supplies","precision":"quote","illustrations":[]},"3":{"question_sha256":"ea05e040a2f63880f3188de644580017574027b0f644c24cef705ff4c5fd7c15","source":"fear, rage and even excitement are attended by much the same internal upheaval","precision":"quote","illustrations":[]},"4":{"question_sha256":"2f5cc3b5512b42d52a18e4e694b2ecb36228e12e097f83cf9b6e3b13fcd36457","source":"even the initial bodily reaction is shaped by appraisal","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"stimulus","definition":"tác nhân kích thích","example":"Where, in the sequence linking a stimulus, the body and the conscious mind, the emotion actually begins is a problem psychologists have answered in strikingly different ways.","aliases":[]},{"term":"bodily reaction","definition":"phản ứng của cơ thể","example":"On their account, a frightening sight first triggers a bodily reaction — quickened breathing, a jolt of adrenaline, tensed muscles — and the conscious emotion is simply the mind's reading of those changes.","aliases":[]},{"term":"arousal","definition":"trạng thái kích hoạt về sinh lý","example":"He proposed instead that a stimulus reaching the brain sends signals simultaneously down two routes — one producing the bodily arousal, the other producing the conscious feeling — so that the two arrive together rather than one causing the other.","aliases":[]},{"term":"cognitive label","definition":"cách diễn giải hoặc tên gọi mà nhận thức gán cho cảm xúc","example":"Emotion, they concluded, requires two factors: a state of arousal and a cognitive label that the surrounding situation supplies.","aliases":[]},{"term":"appraisal","definition":"sự đánh giá ý nghĩa của một sự kiện","example":"Richard Lazarus maintained that even the initial bodily reaction is shaped by appraisal — a rapid, often unconscious assessment of whether an event is threatening, welcome or irrelevant to one's goals.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["psychology","science"],"skill_focus":"detail","word_count":null,"estimated_minutes":13},{"id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","slug":"matching-theories-of-justice","title":"Matching — Theories of Justice","library":"l2_skill","status":"published","body_markdown":"**A** Every society must decide how the benefits and burdens of living together — income, opportunity, security, status — are to be shared out, and few questions in political philosophy have proved more contested. To ask what a just distribution looks like is at once to ask what we owe one another, and the major answers diverge not in detail but at the root.\n\n**B** The most influential modern attempt is John Rawls's \"justice as fairness\", set out in 1971. Rawls invites us to imagine choosing the basic rules of society from behind a \"veil of ignorance\", knowing nothing of the talents, wealth or social position we will end up with. Stripped of that knowledge, he argues, rational people would permit inequalities only where these work to the advantage of the least well-off — a conclusion he calls the difference principle.\n\n**C** Robert Nozick, writing a few years later, accepted the rigour of Rawls's method but rejected its conclusions. On his entitlement theory, a distribution is just if, and only if, it arose through legitimate steps — fair acquisition and voluntary transfer — regardless of the overall shape it produces. To insist that holdings conform to any preferred pattern, Nozick warned, is to license constant interference, since liberty will always upset such patterns; the state's proper role is correspondingly minimal.\n\n**D** Amartya Sen, while sympathetic to Rawls, has pressed a different objection. Theories preoccupied with the fairness of institutions, he contends, can lose sight of how people's lives actually go. What should concern us, on his capability approach, is not the bundle of resources a person formally holds but the real freedoms they enjoy — what they are genuinely able to do and to be, given their circumstances.\n\n**E** Older than any of these is the utilitarian tradition associated with Bentham and Mill, for which the justice of an arrangement turns simply on the sum of welfare it generates. A policy is to be preferred, on this view, if it yields a greater total of well-being than the alternatives, even should the gains and losses fall very unevenly across different people.\n\n**F** These frameworks cannot all be right, and yet each fastens on something we are reluctant to surrender — fairness to the disadvantaged, respect for liberty, attention to real freedom, concern for the aggregate good. Whether any single theory can hold these commitments together, or whether justice names a family of competing goods that must be balanced case by case, is a question the tradition has not, and perhaps cannot, finally resolve.","metadata":{"grammar_focus":[{"tip":"Cụm '-ing' tách bằng dấu phẩy thường bổ sung tình huống cho chủ ngữ chính — xác định đúng ai đang 'knowing' để khỏi hiểu lệch.","point":"Mệnh đề phân từ hiện tại làm trạng ngữ + mệnh đề quan hệ rút gọn lược 'that'","review":"V-ing đầu/giữa câu = mệnh đề phân từ trạng ngữ (cùng chủ ngữ mệnh đề chính). Lược 'that' khi nó là tân ngữ của mệnh đề quan hệ.","example":"imagine choosing the basic rules of society from behind a \"veil of ignorance\", **knowing nothing of the talents, wealth or social position we will end up with**","analysis":"Cụm phân từ hiện tại 'knowing nothing of…' là mệnh đề trạng ngữ rút gọn (= while knowing nothing…), cùng chủ ngữ ngầm với 'we' trong hành động chọn. Bên trong, 'the … position [that] we will end up with' là mệnh đề quan hệ tân ngữ lược 'that', với giới từ 'with' bị bỏ lại ở cuối (preposition stranding)."},{"tip":"Khi đoạn mở đầu bằng V3/V-ing rồi đến dấu phẩy, hãy nối nó với chủ ngữ ngay sau — và đừng nhầm nó với đảo ngữ vì động từ chính không đảo.","point":"Mệnh đề phân từ quá khứ ĐẦU CÂU (fronting, KHÔNG đảo ngữ)","review":"Mệnh đề phân từ V3 đầu câu = bổ nghĩa cho chủ ngữ mệnh đề chính. Fronting (đưa thành phần lên đầu) ≠ inversion (đảo trợ động từ lên trước chủ ngữ).","example":"**Stripped of that knowledge**, he argues, rational people would permit inequalities only where these work to the advantage of the least well-off","analysis":"'Stripped of that knowledge' là mệnh đề phân từ quá khứ bị động rút gọn (= Having been stripped of…) đưa lên đầu câu để nhấn mạnh — đây là FRONTING, không phải đảo ngữ: trật tự S–V của mệnh đề chính 'rational people would permit' vẫn bình thường, không có trợ động từ nào bị đảo lên trước chủ ngữ. 'he argues' là mệnh đề chêm chỉ nguồn ý kiến."},{"tip":"Sau insist/demand/suggest, động từ không chia (he conform, not conforms) là dấu hiệu giả định — đừng tưởng là lỗi ngữ pháp.","point":"Giả định mệnh lệnh (mandative subjunctive) sau 'insist that' + nguyên mẫu làm chủ ngữ 'To … is to …'","review":"insist/demand/require + that + S + V(nguyên mẫu trần) = giả định mệnh lệnh. to V (chủ ngữ) + is + to V (bổ ngữ) = làm X tức là làm Y.","example":"**To insist that holdings conform to any preferred pattern**, Nozick warned, **is to license constant interference**","analysis":"Sau 'insist that', động từ ở dạng nguyên mẫu trần 'conform' (không 'conforms') — đây là giả định mệnh lệnh (mandative subjunctive). Toàn cụm 'To insist that…' là nguyên mẫu làm chủ ngữ của 'is', với bổ ngữ cũng là nguyên mẫu 'to license…' theo khung 'to V … is to V'. 'Nozick warned' là mệnh đề chêm."},{"tip":"Thấy 'Should/Were/Had' đứng đầu mệnh đề mà không có dấu chấm hỏi → đó là câu điều kiện đảo ngữ, hãy dịch là 'nếu…'.","point":"Câu điều kiện đảo ngữ với trợ động từ 'should' (Should + S + V = If + S + should)","review":"Should + S + (bare) V = If + S + should + V (điều kiện trang trọng). 'even should…' = ngay cả khi…","example":"if it yields a greater total of well-being than the alternatives, **even should the gains and losses fall very unevenly** across different people","analysis":"'even should the gains and losses fall…' là câu điều kiện đảo ngữ: trợ động từ 'should' được đảo lên trước chủ ngữ 'the gains and losses' thay cho 'if' (= even if the gains and losses should fall…). Đây là ĐẢO NGỮ thật sự — có trợ động từ 'should' đứng trước chủ ngữ — khác hẳn fronting đơn thuần ở điểm ngữ pháp khác trong bài."}],"translation_vi":"**A** Mọi xã hội đều phải quyết định cách thức mà những lợi ích và gánh nặng của việc chung sống — thu nhập, cơ hội, an ninh, địa vị — được phân chia ra sao, và ít câu hỏi nào trong triết học chính trị lại tỏ ra gây tranh cãi nhiều hơn. Hỏi rằng một sự phân phối công bằng trông như thế nào cũng đồng thời là hỏi rằng chúng ta nợ nhau điều gì, và những câu trả lời lớn phân kỳ không phải ở chi tiết mà ngay tận gốc rễ.\n\n**B** Nỗ lực hiện đại có ảnh hưởng nhất là quan niệm \"công lý như là sự công bằng\" của John Rawls, được trình bày vào năm 1971. Rawls mời gọi chúng ta hình dung việc lựa chọn những quy tắc cơ bản của xã hội từ phía sau một \"tấm màn vô minh\", khi không biết gì về tài năng, của cải hay vị thế xã hội mà rốt cuộc ta sẽ có. Bị tước đi sự hiểu biết ấy, ông lập luận, những con người duy lý sẽ chỉ cho phép những bất bình đẳng ở nơi nào chúng vận hành theo hướng có lợi cho những người kém may mắn nhất — một kết luận mà ông gọi là nguyên tắc khác biệt.\n\n**C** Robert Nozick, viết vài năm sau đó, chấp nhận tính chặt chẽ trong phương pháp của Rawls nhưng bác bỏ những kết luận của nó. Theo thuyết quyền sở hữu của ông, một sự phân phối là công bằng khi và chỉ khi nó nảy sinh qua những bước chính đáng — sự thủ đắc công bằng và sự chuyển nhượng tự nguyện — bất kể hình dạng tổng thể mà nó tạo ra. Nhất quyết bắt các sở hữu phải tuân theo bất kỳ khuôn mẫu được ưa chuộng nào, Nozick cảnh báo, tức là cho phép sự can thiệp liên tục, bởi tự do sẽ luôn làm xáo trộn những khuôn mẫu như vậy; vai trò đúng đắn của nhà nước, tương ứng, là tối thiểu.\n\n**D** Amartya Sen, dù đồng cảm với Rawls, đã thúc đẩy một phản bác khác. Những lý thuyết bận tâm với sự công bằng của các thiết chế, ông lập luận, có thể đánh mất tầm nhìn về việc cuộc sống của con người thực sự diễn ra ra sao. Điều đáng quan tâm với chúng ta, theo cách tiếp cận năng lực của ông, không phải là gói nguồn lực mà một người chính thức nắm giữ mà là những sự tự do thực sự họ được hưởng — những gì họ thực sự có khả năng làm và trở thành, trong hoàn cảnh của họ.\n\n**E** Lâu đời hơn bất kỳ thuyết nào trong số này là truyền thống vị lợi gắn với Bentham và Mill, theo đó sự công bằng của một dàn xếp chỉ đơn giản phụ thuộc vào tổng phúc lợi mà nó tạo ra. Một chính sách nên được ưu tiên, theo quan điểm này, nếu nó mang lại một tổng phúc lợi lớn hơn so với các phương án thay thế, ngay cả khi những cái được và mất rơi xuống rất không đồng đều giữa những con người khác nhau.\n\n**F** Những khuôn khổ này không thể cùng đúng cả, vậy mà mỗi cái lại bám chặt vào một điều gì đó mà chúng ta miễn cưỡng từ bỏ — sự công bằng với người yếu thế, sự tôn trọng tự do, sự chú ý đến tự do thực sự, mối quan tâm tới điều tốt chung. Liệu một lý thuyết đơn lẻ nào có thể giữ những cam kết này lại với nhau, hay liệu công lý gọi tên một họ những điều tốt cạnh tranh nhau mà phải được cân nhắc theo từng trường hợp, là một câu hỏi mà truyền thống ấy đã không, và có lẽ không thể, giải quyết dứt điểm.","practice_support":{"schema_version":1,"source_sha256":"bfa9462fa34a7032e9d625edfca970f4e5173cc98ad14e6692cb1ac38e630c40","translation_sha256":"c89a7597863bbf7ca1b9faba34bf1a282d03432c1489260041fc9588d9c22998","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"c5cda8dff5bd26d0717f03d5311f6b1541a7e474c42052a9f6dd0b98beb2055e","source":"permit inequalities only where these work to the advantage of the least well-off","precision":"quote","illustrations":[]},"2":{"question_sha256":"832cee4c49efff1eba509847e71e0bf2c4c8fa2a36054b17409dc25c2addd193","source":"fair acquisition and voluntary transfer","precision":"quote","illustrations":[]},"3":{"question_sha256":"b3fa484aa601faaecbd57d81c22339d93d32d4b0a103bcd2f5d1cde51a8211a8","source":"behind a \"veil of ignorance\", knowing nothing of the talents, wealth or social position we will end up with","precision":"quote","illustrations":[]},"4":{"question_sha256":"c9d7be3859195fa8d92a86560bcce65774599f4966271bbb74eea27101ff541d","source":"what they are genuinely able to do and to be","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"veil of ignorance","definition":"tấm màn vô tri: không biết vị trí xã hội tương lai của mình","example":"Rawls invites us to imagine choosing the basic rules of society from behind a \"veil of ignorance\", knowing nothing of the talents, wealth or social position we will end up with.","aliases":[]},{"term":"least well-off","definition":"những người có hoàn cảnh kém thuận lợi nhất","example":"Stripped of that knowledge, he argues, rational people would permit inequalities only where these work to the advantage of the least well-off — a conclusion he calls the difference principle.","aliases":[]},{"term":"voluntary transfer","definition":"sự chuyển giao tự nguyện","example":"On his entitlement theory, a distribution is just if, and only if, it arose through legitimate steps — fair acquisition and voluntary transfer — regardless of the overall shape it produces.","aliases":[]},{"term":"capability approach","definition":"cách tiếp cận dựa vào khả năng thực tế làm và trở thành điều mình muốn","example":"What should concern us, on his capability approach, is not the bundle of resources a person formally holds but the real freedoms they enjoy — what they are genuinely able to do and to be, given their circumstances.","aliases":[]},{"term":"welfare","definition":"phúc lợi, mức độ sống tốt của con người","example":"E Older than any of these is the utilitarian tradition associated with Bentham and Mill, for which the justice of an arrangement turns simply on the sum of welfare it generates.","aliases":[]}],"image_url":null,"difficulty_level":"advanced","topic_tags":["social-sciences","philosophy"],"skill_focus":"detail","word_count":null,"estimated_minutes":14},{"id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","slug":"matching-types-of-renewable-energy","title":"Matching — Types of Renewable Energy","library":"l2_skill","status":"published","body_markdown":"**A** The phrase 'renewable energy' is used as if it described a single thing, but it\nactually covers a group of very different technologies. What they share is not how they\nwork but a single feature: they all draw on sources that are naturally replenished,\nrather than burning fossil fuels that will run out.\n\n**B** The most familiar is solar power, turning sunlight directly into electricity.\nBecause solar panels have no moving parts and can be fitted onto rooftops that already\nexist, they can be installed where large power stations cannot reach. Their weakness is\nas plain as their appeal: they produce nothing at night and less under cloud, so their\noutput rises and falls with the weather.\n\n**C** Hydropower has a far longer history. It has generated electricity on a large\nscale for longer than any other renewable source, by letting falling water pass through\nturbines. The Hoover Dam in the United States, for instance, has a generating capacity\nof around 2,080 megawatts. It is reliable and powerful, but it comes at a cost: building a large dam can\ndrown valleys and force the communities living there to move.\n\n**D** Wind power, now growing fast around the world, uses large blades to catch moving\nair and turn a generator. Like solar, it is clean and plentiful but uneven, strong on\nwindy days and silent on still ones.\n\n**E** Geothermal power taps a source beyond the reach of most other technologies: the\nheat held deep inside the Earth. By pumping water down to hot rock, engineers raise\nsteam that can spin turbines. Iceland, sitting on especially active ground, now draws\naround a quarter of its electricity this way. The drawback is that it works best where the hot rock\nlies near the surface, often in volcanically active regions.\n\n**F** Finally, biomass energy burns plant matter — wood, straw or special crops — to\nmake heat and power. It is a special case, because the burning does release carbon\ndioxide. It counts as renewable only if new plants regrow to absorb a similar amount,\nclosing the cycle over time.","metadata":{"grammar_focus":[{"tip":"Cụm V-ing sau danh từ thường = mệnh đề quan hệ rút gọn — quy nó về danh từ đứng trước để biết nó mô tả nguồn năng lượng NÀO khi giải matching.","point":"Mệnh đề quan hệ rút gọn dạng V-ing hậu bổ nghĩa","review":"Mệnh đề quan hệ chủ động có thể rút gọn thành V-ing (a source turning X = a source that turns X).","example":"The most familiar is solar power, **turning sunlight directly into electricity**.","analysis":"'turning sunlight directly into electricity' là cụm phân từ hiện tại rút gọn (= which turns…), bổ nghĩa cho 'solar power'. Dạng rút gọn lược 'which' và 'be/động từ chia', chỉ giữ V-ing 'turning'. Cụm đứng sau dấu phẩy mang tính bổ sung."},{"tip":"'Because…' nêu LÝ DO cho một đặc điểm — trong matching sentence endings, phần ưu/nhược điểm sau 'because' thường là nội dung cần ghép với phần kết câu.","point":"Mệnh đề trạng ngữ chỉ nguyên nhân với 'Because' đầu câu","review":"Because + S + V, S + V: mệnh đề nguyên nhân đầu câu có dấu phẩy. Bị động với modal: modal + be + V3.","example":"**Because solar panels have no moving parts** and can be fitted onto rooftops that already exist, they can be installed where large power stations cannot reach.","analysis":"'Because + S + V' là mệnh đề trạng ngữ chỉ nguyên nhân, đặt đầu câu và ngăn bằng dấu phẩy. Hai vị ngữ 'have no moving parts' và 'can be fitted' nối song song. 'can be fitted' là bị động với modal (can + be + V3). Cuối có mệnh đề quan hệ 'that already exist'."},{"tip":"Dấu hai chấm thường mở ra lời GIẢI THÍCH/ĐỊNH DANH cho danh từ trước nó — chỗ này hay chứa đặc điểm cốt lõi cần ghép trong matching features.","point":"Dấu hai chấm giới thiệu danh từ + cụm đồng vị giải thích","review":"N + dấu hai chấm + cụm danh từ = đồng vị, nêu rõ danh từ trừu tượng vừa nhắc (a source: the heat…). V3 sau danh từ = mệnh đề quan hệ bị động rút gọn.","example":"Geothermal power taps a source beyond the reach of most other technologies: **the heat held deep inside the Earth**.","analysis":"Sau dấu hai chấm, cụm danh từ 'the heat held deep inside the Earth' là phần đồng vị, giải thích cụ thể 'a source' đứng trước. 'held deep inside the Earth' là phân từ quá khứ rút gọn (= which is held…) bổ nghĩa cho 'heat'. Cấu trúc dùng dấu hai chấm để định danh."}],"translation_vi":"**A** Cụm từ \"năng lượng tái tạo\" được dùng như thể nó mô tả một thứ duy nhất, nhưng nó thực ra bao trùm một nhóm các công nghệ rất khác nhau. Điều chúng có chung không phải là cách chúng hoạt động mà là một đặc điểm duy nhất: tất cả chúng đều khai thác các nguồn được bổ sung một cách tự nhiên, thay vì đốt cháy nhiên liệu hóa thạch sẽ cạn kiệt.\n\n**B** Quen thuộc nhất là năng lượng mặt trời, biến ánh sáng mặt trời trực tiếp thành điện năng. Bởi vì các tấm pin mặt trời không có bộ phận chuyển động và có thể được lắp lên những mái nhà đã có sẵn, chúng có thể được lắp đặt ở những nơi mà các nhà máy điện lớn không thể tới. Nhược điểm của chúng cũng rõ ràng như ưu điểm: chúng không sản xuất gì vào ban đêm và ít hơn khi trời nhiều mây, nên sản lượng của chúng biến động theo thời tiết.\n\n**C** Thủy điện có một lịch sử lâu đời hơn nhiều. Nó đã sản xuất điện ở quy mô lớn lâu hơn bất kỳ nguồn tái tạo nào khác, bằng cách cho nước rơi qua các tuabin. Ví dụ, đập Hoover ở Hoa Kỳ có công suất phát điện khoảng 2.080 megawatt. Nó đáng tin cậy và mạnh mẽ, nhưng nó cũng có cái giá của nó: việc xây một con đập lớn có thể nhấn chìm các thung lũng và buộc các cộng đồng sống ở đó phải di dời.\n\n**D** Năng lượng gió, nay tăng trưởng nhanh trên khắp thế giới, sử dụng những cánh quạt lớn để bắt lấy không khí đang chuyển động và quay một máy phát điện. Giống như năng lượng mặt trời, nó sạch và dồi dào nhưng không đều đặn, mạnh mẽ vào những ngày lộng gió và lặng yên vào những ngày không.\n\n**E** Năng lượng địa nhiệt khai thác một nguồn nằm ngoài tầm với của hầu hết các công nghệ khác: nhiệt được lưu giữ sâu bên trong Trái Đất. Bằng cách bơm nước xuống đá nóng, các kỹ sư tạo ra hơi nước có thể quay các tuabin. Iceland, nằm trên nền đất có hoạt động địa chất đặc biệt mạnh, hiện lấy khoảng một phần tư lượng điện của mình theo cách này. Nhược điểm là nó hoạt động tốt nhất ở những nơi lớp đá nóng nằm gần bề mặt, thường là ở những vùng có hoạt động núi lửa.\n\n**F** Cuối cùng, năng lượng sinh khối đốt vật chất thực vật — gỗ, rơm rạ hoặc cây trồng đặc biệt — để tạo ra nhiệt và điện. Nó là một trường hợp đặc biệt, bởi vì việc đốt thực sự giải phóng carbon dioxide. Nó chỉ được tính là tái tạo nếu cây mới mọc lại để hấp thụ một lượng tương tự, khép kín vòng tuần hoàn theo thời gian.","practice_support":{"schema_version":1,"source_sha256":"63a3855a4232f7432613fe217cf92c4bc7631cf60fac20e7693e0c419c7c4e12","translation_sha256":"7f2525261f5341986d250c5cf1ae208eb965d73d212b0d0cc714e817c14009fe","units":[],"illustrations":[],"question_evidence":{"1":{"question_sha256":"063e0908b9ed7be936d2739f35f25f547b13d34d58f261364c6b4630b0729796","source":"the heat held deep inside the Earth","precision":"quote","illustrations":[]},"2":{"question_sha256":"bcba8aae67e44200d9b5224c729ee8bc9873b4967b78284df8f0e0fbe749d811","source":"only if new plants regrow to absorb a similar amount","precision":"quote","illustrations":[]},"3":{"question_sha256":"b5fda8f285e85f2074db75733f706d6bcbeaa2f1d99b6a2ccfc4e89386fddf42","source":"by letting falling water pass through turbines","precision":"quote","illustrations":[]},"4":{"question_sha256":"2c597a3cf4a362df51478f3eb51509ae3d011675af14f4459f1b0482e8a92b81","source":"solar panels have no moving parts","precision":"quote","illustrations":[]},"5":{"question_sha256":"aa5d6821f35de216a6f500833f55cbd469f9fd68bfb64a8ebdbaa05a2c4f6db9","source":"building a large dam can drown valleys and force the communities living there to move","precision":"quote","illustrations":[]}}}},"glossary":[{"term":"replenished","definition":"được bổ sung hoặc tái tạo trở lại","example":"What they share is not how they work but a single feature: they all draw on sources that are naturally replenished, rather than burning fossil fuels that will run out.","aliases":[]},{"term":"turbines","definition":"các tua-bin","example":"It has generated electricity on a large scale for longer than any other renewable source, by letting falling water pass through turbines.","aliases":[]},{"term":"generating capacity","definition":"công suất phát điện","example":"The Hoover Dam in the United States, for instance, has a generating capacity of around 2,080 megawatts.","aliases":[]},{"term":"geothermal power","definition":"điện địa nhiệt","example":"E Geothermal power taps a source beyond the reach of most other technologies: the heat held deep inside the Earth.","aliases":[]},{"term":"biomass energy","definition":"năng lượng từ sinh khối","example":"F Finally, biomass energy burns plant matter — wood, straw or special crops — to make heat and power.","aliases":[]}],"image_url":null,"difficulty_level":"intermediate","topic_tags":["environment","technology"],"skill_focus":"detail","word_count":null,"estimated_minutes":11},{"id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","slug":"the-tragedy-of-the-commons","title":"The Tragedy of the Commons","library":"l1_vocab","status":"published","body_markdown":"In a short essay published in the journal Science in 1968, the ecologist Garrett\nHardin offered a parable that would shape environmental thinking for decades. He\nimagined a pasture, held as a **commons**, on which several herders are free to\n**graze** their cattle. Each herder reasons that adding one more animal brings a\nclear private gain, while the resulting damage to the land is shared by everyone, and\nso the same self-interested calculation pushes every herder toward expansion until\nthe pasture is **depleted** and ruined.\n\nThe force of the argument lies in its bleak logic. Because each individual behaves in\na perfectly **rational** way, the slow **degradation** of the shared resource appears\nnot as a mistake but as an **inevitable** outcome that no single person can prevent\nalone. Hardin concluded that ruin was the destination toward which all such commons\nwere driven, and he insisted that only firm remedies could avert it. Either the state\nshould **privatise** the land into private holdings, or else society should accept a\ndegree of mutual **coercion**, agreed upon by the majority, in order to restrain\nindividual appetite.\n\nFor two decades this gloomy verdict was widely accepted, yet **empirical** research\ngradually undermined it. The political economist Elinor Ostrom, who would later become\nthe first woman to win the Nobel Prize in economics, argued that Hardin had quietly\n**conflated** two very different things. A genuinely **open-access** resource, owned\nby nobody and governed by no rules, may indeed collapse, but most historical commons\nwere nothing of the sort. Studying irrigation systems, forests and fisheries across\nthe world, Ostrom showed that communities had managed shared resources sustainably\nfor centuries, relying neither on privatisation nor on distant government, but instead\non local **norms**, on **sanctions** against those who took too much, and on the trust\nand **reciprocity** that bind neighbours together.\n\nThe picture that emerges today is therefore considerably more **nuanced** than the\noriginal parable suggested. Hardin's logic still illuminates the fate of unregulated\nresources, from open seas to a warming atmosphere, yet the assumption that ruin is\neverywhere unavoidable now looks too sweeping, and how best to govern any particular\ncommons appears to depend on circumstances that no single rule can settle.","metadata":{"grammar_focus":[{"tip":"Gặp 'V-ing…, S + V' hãy nối V-ing với chủ ngữ ngay sau dấu phẩy; phần sau thường là luận điểm chính của đoạn.","point":"Mệnh đề phân từ đầu câu (participle clause) chỉ bối cảnh đồng thời","review":"Participle clause đầu câu = mệnh đề rút gọn cùng chủ ngữ (While/When + S + V → V-ing…). Chủ ngữ cụm phân từ phải trùng chủ ngữ mệnh đề chính (tránh dangling modifier).","example":"**Studying** irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably…","analysis":"Cụm phân từ hiện tại 'Studying…' đứng đầu câu có chủ thể logic là 'Ostrom', cùng chủ ngữ với mệnh đề chính; trong ngữ cảnh này, nó nêu hoạt động nghiên cứu làm bối cảnh/cách thức cho kết luận. Mệnh đề chính là 'Ostrom showed…', với 'showed' ở thì quá khứ đơn. Mệnh đề nội dung 'that communities had managed shared resources sustainably…' làm bổ ngữ cho 'showed': 'communities' là chủ ngữ và 'had managed' ở thì quá khứ hoàn thành, diễn tả việc quản lý tài nguyên đã diễn ra trong nhiều thế kỷ trước mốc 'showed'. Vì vậy, 'had managed' thuộc mệnh đề phụ that, không phải động từ của mệnh đề chính."},{"tip":"Thông tin giữa hai dấu phẩy là phụ, không phải ý chính — câu hỏi detail thường nhắm vào mệnh đề chính, đừng lẫn với phần chèn thêm.","point":"Mệnh đề quan hệ không xác định với 'who would later…'","review":"Mệnh đề quan hệ không xác định: ,who/which + …, — có dấu phẩy, thêm thông tin phụ. 'would + V' = tương lai trong quá khứ (sẽ … về sau).","example":"Elinor Ostrom, **who would later become the first woman to win the Nobel Prize in economics**, argued that Hardin had quietly conflated two very different things.","analysis":"Mệnh đề quan hệ không xác định 'who would later become…' nằm giữa hai dấu phẩy, bổ sung thông tin phụ về Ostrom (bỏ đi câu vẫn đủ nghĩa). 'would' ở đây là tương lai trong quá khứ (future-in-the-past): nhìn từ mốc quá khứ, sự kiện về sau mới xảy ra."},{"tip":"Liệt kê song song dài là 'mỏ vàng' cho câu hỏi multiple-answer/note-completion — mỗi mục song song thường là một đáp án.","point":"Cấu trúc song song & lược từ (parallelism / ellipsis) sau 'neither … nor'","review":"Parallelism: các thành phần cùng vai trò phải cùng dạng (on N, on N, on N). 'neither … nor …' nối hai phủ định; 'but instead' đưa ra phương án thay thế.","example":"relying **neither on** privatisation **nor on** distant government, but instead **on** local norms, **on** sanctions…, and **on** the trust and reciprocity…","analysis":"Cấu trúc song song với một loạt cụm giới từ bắt đầu bằng 'on…', nối qua 'neither … nor … but instead …'. Các thành phần đồng chức năng được giữ cùng dạng (on + N) tạo nhịp song song; cụm phân từ 'relying…' rút gọn '…and they relied…'."},{"tip":"Từ tương phản (yet/however/nevertheless) là tín hiệu quan điểm tác giả nghiêng về vế sau — chỗ vàng cho câu hỏi Yes/No/Not Given.","point":"Cụm nhượng bộ & tương phản phức (concessive với 'yet')","review":"'yet' = liên từ tương phản như 'but', trang trọng hơn. 'the assumption/idea/fact + that + mệnh đề' = mệnh đề đồng cách nêu nội dung danh từ trừu tượng.","example":"Hardin's logic still illuminates the fate of unregulated resources…, **yet** the assumption that ruin is everywhere unavoidable now looks too sweeping…","analysis":"Liên từ tương phản 'yet' (= nhưng) nối hai mệnh đề độc lập, nhượng bộ một phần đúng của Hardin rồi phản bác. Chủ ngữ 'the assumption that ruin is…' chứa mệnh đề đồng cách (appositive 'that…') giải thích nội dung của 'assumption'."}],"translation_vi":"Trong một bài luận ngắn đăng trên tạp chí Science năm 1968, nhà sinh thái học Garrett Hardin đưa ra một câu chuyện ngụ ngôn có ảnh hưởng tới tư duy về môi trường suốt nhiều thập kỷ. Ông hình dung một đồng cỏ được giữ làm tài nguyên chung, nơi một số người chăn nuôi được tự do cho gia súc của mình ăn cỏ. Mỗi người chăn nuôi tính rằng thêm một con vật sẽ đem lại lợi ích riêng rõ rệt, còn thiệt hại đối với đất thì mọi người cùng gánh chịu. Vì vậy, cùng một phép tính vì lợi ích cá nhân khiến ai cũng mở rộng đàn, cho đến khi đồng cỏ bị khai thác cạn kiệt và hủy hoại.\n\nSức thuyết phục của lập luận nằm ở lô-gic bi quan của nó. Vì mỗi cá nhân hành động hoàn toàn hợp lý, sự suy thoái dần dần của tài nguyên chung dường như là một kết cục tất yếu mà không ai có thể một mình ngăn chặn, thay vì một sai lầm. Hardin kết luận rằng mọi tài nguyên chung như vậy đều đi tới chỗ bị hủy hoại, và khẳng định chỉ những biện pháp quyết liệt mới có thể ngăn điều đó. Hoặc nhà nước phải tư nhân hóa đất thành những phần sở hữu riêng, hoặc xã hội phải chấp nhận một mức độ cưỡng chế lẫn nhau do đa số đồng thuận, nhằm hạn chế ham muốn của từng cá nhân.\n\nTrong hai thập kỷ, kết luận bi quan này được chấp nhận rộng rãi, nhưng nghiên cứu thực nghiệm dần làm suy yếu nó. Nhà kinh tế chính trị Elinor Ostrom, người sau này trở thành phụ nữ đầu tiên giành giải Nobel Kinh tế, cho rằng Hardin đã ngầm đánh đồng hai điều rất khác nhau. Một tài nguyên thực sự ai cũng có thể tiếp cận, không thuộc sở hữu của ai và không chịu quy tắc nào, quả thật có thể sụp đổ; nhưng phần lớn tài nguyên chung trong lịch sử không hề như vậy. Qua nghiên cứu các hệ thống tưới tiêu, rừng và ngư trường trên khắp thế giới, Ostrom cho thấy nhiều cộng đồng đã quản lý tài nguyên chung bền vững suốt hàng thế kỷ. Họ không dựa vào tư nhân hóa hay chính quyền ở xa, mà vào quy tắc địa phương, chế tài đối với người lấy quá nhiều, cùng lòng tin và sự có đi có lại gắn kết hàng xóm với nhau.\n\nVì thế, bức tranh ngày nay hiện ra với nhiều sắc thái hơn đáng kể so với điều câu chuyện ngụ ngôn ban đầu gợi ra. Lô-gic của Hardin vẫn giúp lý giải số phận của những tài nguyên không được quản lý, từ biển khơi đến bầu khí quyển đang nóng lên. Tuy nhiên, giả định rằng sự hủy hoại ở đâu cũng không thể tránh khỏi nay có vẻ quá bao quát; cách quản lý tốt nhất cho từng tài nguyên chung phụ thuộc vào những hoàn cảnh mà không một quy tắc duy nhất nào có thể giải quyết hết.","practice_support":{"schema_version":1,"source_sha256":"520aef893b762c00f10f1f635e8bd1ab1869949da4dfb7a41310d2cf84430243","translation_sha256":"36a3a08e86cca0794cefac383dff3ec4ee12bbddffd1c8a9ec8bb458225bbd01","units":[{"id":"p1-s1","source":"In a short essay published in the journal Science in 1968, the ecologist Garrett Hardin offered a parable that would shape environmental thinking for decades.","translation_vi":"Trong một bài luận ngắn đăng trên tạp chí Science năm 1968, nhà sinh thái học Garrett Hardin đưa ra một câu chuyện ngụ ngôn có ảnh hưởng tới tư duy về môi trường suốt nhiều thập kỷ.","precision":"sentence","phrases":[{"source":"a parable","target":"một câu chuyện ngụ ngôn"},{"source":"would shape environmental thinking","target":"có ảnh hưởng tới tư duy về môi trường"}]},{"id":"p1-s2","source":"He imagined a pasture, held as a commons, on which several herders are free to graze their cattle.","translation_vi":"Ông hình dung một đồng cỏ được giữ làm tài nguyên chung, nơi một số người chăn nuôi được tự do cho gia súc của mình ăn cỏ.","precision":"sentence","phrases":[{"source":"a pasture","target":"một đồng cỏ"},{"source":"commons","target":"tài nguyên chung"},{"source":"graze their cattle","target":"cho gia súc của mình ăn cỏ"}]},{"id":"p1-s3","source":"Each herder reasons that adding one more animal brings a clear private gain, while the resulting damage to the land is shared by everyone, and so the same self-interested calculation pushes every herder toward expansion until the pasture is depleted and ruined.","translation_vi":"Mỗi người chăn nuôi tính rằng thêm một con vật sẽ đem lại lợi ích riêng rõ rệt, còn thiệt hại đối với đất thì mọi người cùng gánh chịu. Vì vậy, cùng một phép tính vì lợi ích cá nhân khiến ai cũng mở rộng đàn, cho đến khi đồng cỏ bị khai thác cạn kiệt và hủy hoại.","precision":"sentence","phrases":[{"source":"private gain","target":"lợi ích riêng"},{"source":"is shared by everyone","target":"mọi người cùng gánh chịu"},{"source":"self-interested calculation","target":"phép tính vì lợi ích cá nhân"},{"source":"depleted and ruined","target":"khai thác cạn kiệt và hủy hoại"}]},{"id":"p2-s1","source":"The force of the argument lies in its bleak logic.","translation_vi":"Sức thuyết phục của lập luận nằm ở lô-gic bi quan của nó.","precision":"sentence","phrases":[{"source":"bleak logic","target":"lô-gic bi quan"}]},{"id":"p2-s2","source":"Because each individual behaves in a perfectly rational way, the slow degradation of the shared resource appears not as a mistake but as an inevitable outcome that no single person can prevent alone.","translation_vi":"Vì mỗi cá nhân hành động hoàn toàn hợp lý, sự suy thoái dần dần của tài nguyên chung dường như là một kết cục tất yếu mà không ai có thể một mình ngăn chặn, thay vì một sai lầm.","precision":"sentence","phrases":[{"source":"perfectly rational","target":"hoàn toàn hợp lý"},{"source":"slow degradation","target":"sự suy thoái dần dần"},{"source":"an inevitable outcome","target":"một kết cục tất yếu"}]},{"id":"p2-s3","source":"Hardin concluded that ruin was the destination toward which all such commons were driven, and he insisted that only firm remedies could avert it.","translation_vi":"Hardin kết luận rằng mọi tài nguyên chung như vậy đều đi tới chỗ bị hủy hoại, và khẳng định chỉ những biện pháp quyết liệt mới có thể ngăn điều đó.","precision":"sentence","phrases":[{"source":"firm remedies","target":"những biện pháp quyết liệt"},{"source":"avert it","target":"ngăn điều đó"}]},{"id":"p2-s4","source":"Either the state should privatise the land into private holdings, or else society should accept a degree of mutual coercion, agreed upon by the majority, in order to restrain individual appetite.","translation_vi":"Hoặc nhà nước phải tư nhân hóa đất thành những phần sở hữu riêng, hoặc xã hội phải chấp nhận một mức độ cưỡng chế lẫn nhau do đa số đồng thuận, nhằm hạn chế ham muốn của từng cá nhân.","precision":"sentence","phrases":[{"source":"privatise the land","target":"tư nhân hóa đất"},{"source":"mutual coercion","target":"cưỡng chế lẫn nhau"},{"source":"agreed upon by the majority","target":"do đa số đồng thuận"}]},{"id":"p3-s1","source":"For two decades this gloomy verdict was widely accepted, yet empirical research gradually undermined it.","translation_vi":"Trong hai thập kỷ, kết luận bi quan này được chấp nhận rộng rãi, nhưng nghiên cứu thực nghiệm dần làm suy yếu nó.","precision":"sentence","phrases":[{"source":"empirical research","target":"nghiên cứu thực nghiệm"},{"source":"undermined it","target":"làm suy yếu nó"}]},{"id":"p3-s2","source":"The political economist Elinor Ostrom, who would later become the first woman to win the Nobel Prize in economics, argued that Hardin had quietly conflated two very different things.","translation_vi":"Nhà kinh tế chính trị Elinor Ostrom, người sau này trở thành phụ nữ đầu tiên giành giải Nobel Kinh tế, cho rằng Hardin đã ngầm đánh đồng hai điều rất khác nhau.","precision":"sentence","phrases":[{"source":"conflated","target":"đánh đồng"},{"source":"two very different things","target":"hai điều rất khác nhau"}]},{"id":"p3-s3","source":"A genuinely open-access resource, owned by nobody and governed by no rules, may indeed collapse, but most historical commons were nothing of the sort.","translation_vi":"Một tài nguyên thực sự ai cũng có thể tiếp cận, không thuộc sở hữu của ai và không chịu quy tắc nào, quả thật có thể sụp đổ; nhưng phần lớn tài nguyên chung trong lịch sử không hề như vậy.","precision":"sentence","phrases":[{"source":"open-access resource","target":"tài nguyên thực sự ai cũng có thể tiếp cận"},{"source":"governed by no rules","target":"không chịu quy tắc nào"},{"source":"nothing of the sort","target":"không hề như vậy"}]},{"id":"p3-s4","source":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together.","translation_vi":"Qua nghiên cứu các hệ thống tưới tiêu, rừng và ngư trường trên khắp thế giới, Ostrom cho thấy nhiều cộng đồng đã quản lý tài nguyên chung bền vững suốt hàng thế kỷ. Họ không dựa vào tư nhân hóa hay chính quyền ở xa, mà vào quy tắc địa phương, chế tài đối với người lấy quá nhiều, cùng lòng tin và sự có đi có lại gắn kết hàng xóm với nhau.","precision":"sentence","phrases":[{"source":"local norms","target":"quy tắc địa phương"},{"source":"sanctions","target":"chế tài"},{"source":"trust and reciprocity","target":"lòng tin và sự có đi có lại"},{"source":"sustainably","target":"bền vững"}]},{"id":"p4-s1","source":"The picture that emerges today is therefore considerably more nuanced than the original parable suggested.","translation_vi":"Vì thế, bức tranh ngày nay hiện ra với nhiều sắc thái hơn đáng kể so với điều câu chuyện ngụ ngôn ban đầu gợi ra.","precision":"sentence","phrases":[{"source":"more nuanced","target":"nhiều sắc thái hơn"}]},{"id":"p4-s2","source":"Hardin's logic still illuminates the fate of unregulated resources, from open seas to a warming atmosphere, yet the assumption that ruin is everywhere unavoidable now looks too sweeping, and how best to govern any particular commons appears to depend on circumstances that no single rule can settle.","translation_vi":"Lô-gic của Hardin vẫn giúp lý giải số phận của những tài nguyên không được quản lý, từ biển khơi đến bầu khí quyển đang nóng lên. Tuy nhiên, giả định rằng sự hủy hoại ở đâu cũng không thể tránh khỏi nay có vẻ quá bao quát; cách quản lý tốt nhất cho từng tài nguyên chung phụ thuộc vào những hoàn cảnh mà không một quy tắc duy nhất nào có thể giải quyết hết.","precision":"sentence","phrases":[{"source":"unregulated resources","target":"những tài nguyên không được quản lý"},{"source":"too sweeping","target":"quá bao quát"},{"source":"depend on circumstances","target":"phụ thuộc vào những hoàn cảnh"}]}],"illustrations":[],"question_evidence":{"1":{"question_sha256":"e5a6c337e161624287ba534a1888baf8a68f4b6bdba9e5739b9c671e97cb5df9","source":"Each herder reasons that adding one more animal brings a clear private gain, while the resulting damage to the land is shared by everyone, and so the same self-interested calculation pushes every herder toward expansion until the pasture is depleted and ruined.","precision":"quote","illustrations":[{"src":"/reading-illustrations/commons-review.svg","alt":"Lợi ích từ con vật thêm vào thuộc riêng một người; thiệt hại đồng cỏ được mọi người chia sẻ.","caption":"Sơ đồ lập luận của Hardin trong bài; nghiên cứu của Ostrom chỉ ra các cộng đồng cũng có thể quản lý bền vững bằng quy tắc chung."}]},"2":{"question_sha256":"aa9d8cfaf910045f3fe4e2ffe995a83bc6f71ba69890023d063e1dbaab81212e","source":"The picture that emerges today is therefore considerably more nuanced than the original parable suggested.","precision":"quote","illustrations":[]},"3":{"question_sha256":"6a26290d08a09b73a60dbecb2f70bddd0f587bf9c83e812bbdb30b02ad849858","source":"A genuinely open-access resource, owned by nobody and governed by no rules, may indeed collapse, but most historical commons were nothing of the sort.","precision":"quote","illustrations":[]},"4":{"question_sha256":"14ac0a91c8200a871c44869747c18b28bd947fc9abdb4f023dd9cd403ba13f5f","source":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together.","precision":"quote","illustrations":[]},"5":{"question_sha256":"7984e0dcab8d2199d5a40be3aa0b947498bfe06b5ae786e2108d0e759a1e81e4","source":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together.","precision":"quote","illustrations":[]},"6":{"question_sha256":"6fbf059e9c4a4ad21626c4293f70e71b3afae91c30b91468c9da5fc494bb356f","source":"Hardin's logic still illuminates the fate of unregulated resources, from open seas to a warming atmosphere, yet the assumption that ruin is everywhere unavoidable now looks too sweeping, and how best to govern any particular commons appears to depend on circumstances that no single rule can settle.","precision":"quote","illustrations":[{"src":"/reading-illustrations/commons-review.svg","alt":"Lợi ích từ con vật thêm vào thuộc riêng một người; thiệt hại đồng cỏ được mọi người chia sẻ.","caption":"Sơ đồ lập luận của Hardin trong bài; nghiên cứu của Ostrom chỉ ra các cộng đồng cũng có thể quản lý bền vững bằng quy tắc chung."}]}}}},"glossary":[{"ipa":"/ˈræʃnəl/","pos":"adj.","term":"rational","example":"The rational herder adds one more animal to the herd.","synonyms":["logical","self-interested"],"definition":"hợp lý, dựa trên lý trí (theo lợi ích cá nhân)"},{"ipa":"/ˌdeɡrəˈdeɪʃn/","pos":"n.","term":"degradation","example":"Each small gain hastens the degradation of the whole.","synonyms":["decline","deterioration"],"definition":"sự suy thoái, xuống cấp (của môi trường)"},{"ipa":"/ɪnˈevɪtəbl/","pos":"adj.","term":"inevitable","example":"Hardin treated ruin as an inevitable outcome.","synonyms":["unavoidable","certain"],"definition":"không thể tránh khỏi, tất yếu"},{"ipa":"/ˈpraɪvətaɪz/","pos":"v.","term":"privatise","example":"One remedy is to privatise the land into separate plots.","synonyms":["sell off"],"definition":"tư nhân hóa (chuyển sang sở hữu tư nhân)"},{"ipa":"/ˌəʊpən ˈækses/","pos":"adj.","term":"open-access","example":"A truly open-access resource has no rules at all.","synonyms":["unrestricted"],"definition":"ai cũng tiếp cận được (không có rào cản hay quy tắc)"},{"term":"commons","definition":"tài nguyên được nhiều người cùng sử dụng; cách quản lý có thể khác nhau tùy cộng đồng","aliases":[],"example":"He imagined a pasture, held as a commons, on which several herders are free to graze their cattle."},{"term":"graze","definition":"cho gia súc ăn cỏ","aliases":["graze their cattle"],"example":"He imagined a pasture, held as a commons, on which several herders are free to graze their cattle."},{"term":"deplete","definition":"làm cạn kiệt","aliases":["depleted"],"example":"Each herder reasons that adding one more animal brings a clear private gain, while the resulting damage to the land is shared by everyone, and so the same self-interested calculation pushes every herder toward expansion until the pasture is depleted and ruined."},{"term":"conflate","definition":"đánh đồng những điều khác nhau","aliases":["conflated"],"example":"The political economist Elinor Ostrom, who would later become the first woman to win the Nobel Prize in economics, argued that Hardin had quietly conflated two very different things."},{"term":"norm","definition":"quy tắc hay chuẩn mực được cộng đồng chấp nhận","aliases":["norms"],"example":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together."},{"term":"sanction","definition":"chế tài đối với người vi phạm","aliases":["sanctions"],"example":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together."},{"term":"reciprocity","definition":"sự có đi có lại","aliases":[],"example":"Studying irrigation systems, forests and fisheries across the world, Ostrom showed that communities had managed shared resources sustainably for centuries, relying neither on privatisation nor on distant government, but instead on local norms, on sanctions against those who took too much, and on the trust and reciprocity that bind neighbours together."},{"term":"empirical","definition":"dựa trên quan sát hoặc thực nghiệm","aliases":[],"example":"For two decades this gloomy verdict was widely accepted, yet empirical research gradually undermined it."},{"term":"coercion","definition":"sự cưỡng chế","aliases":[],"example":"Either the state should privatise the land into private holdings, or else society should accept a degree of mutual coercion, agreed upon by the majority, in order to restrain individual appetite."},{"term":"nuanced","definition":"có nhiều sắc thái, không đơn giản một chiều","aliases":[],"example":"The picture that emerges today is therefore considerably more nuanced than the original parable suggested."}],"image_url":"/reading-illustrations/commons-scene.svg","difficulty_level":"advanced","topic_tags":["economics","environment"],"skill_focus":null,"word_count":365,"estimated_minutes":9}],"questions":[{"id":"00d1b0ac-f7b9-4103-ad40-e95aa618f50a","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nProduced impossible dream-like images inspired by the unconscious mind.","payload":{"options":[{"text":"Realism","label":"A"},{"text":"Impressionism","label":"B"},{"text":"Cubism","label":"C"},{"text":"Surrealism","label":"D"},{"text":"Abstract Expressionism","label":"E"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph E says the Surrealists filled their canvases with 'dreamlike, impossible images drawn from the hidden workings of the unconscious mind'. Abstract Expressionism (E) is offered as an extra option but is not described in the passage.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"02d38aab-3180-48c7-906b-0cd6e0417ca8","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nSen argues that justice should assess people's real freedoms …","payload":{"options":[{"text":"from behind a veil that hides their own place in society","label":"i"},{"text":"according to what people are actually able to do and to be","label":"ii"},{"text":"by calculating the total amount of pleasure a policy produces","label":"iii"},{"text":"that fix in advance the precise pattern holdings should form","label":"iv"},{"text":"with the consent of an all-powerful central state","label":"v"},{"text":"in proportion to the inherited wealth each family holds","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph D reports Sen's capability approach, which directs us to 'the real freedoms they enjoy — what they are genuinely able to do and to be', matching ending (ii). Ending (i) is Rawls's device, a tempting overlap because Sen engages with Rawls, but it answers a different beginning.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"04a51aad-2d58-46d4-a892-3c0dd4468eb8","passage_id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed pointed arches and large windows to draw the eye upward and express religious devotion.","payload":{"options":[{"text":"Gothic architecture","label":"A"},{"text":"The Bauhaus","label":"B"},{"text":"Brutalism","label":"C"},{"text":"Postmodernism","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to the Gothic style the pointed arch and the soaring, light-filled window. The Bauhaus (B) is the half-correct trap, since paragraph C ties it to industrial materials and stripped-down form rather than verticality and stained glass.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"04b34285-15b1-4409-931c-1ad2747c00a8","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nChomsky challenged behaviourism by pointing out that …","payload":{"options":[{"text":"children routinely produce sentences they have never heard before.","label":"A"},{"text":"reinforcement alone could explain the entire course of development.","label":"B"},{"text":"adults rarely correct the small grammatical errors children make.","label":"C"},{"text":"the social context of speech is irrelevant to acquisition.","label":"D"},{"text":"every language relies on the same underlying rules.","label":"E"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph C reports that the behaviourist account faltered because children generate novel utterances they could not have been rewarded for, matching ending A. B reverses the critique; C, D and E are unused distractors drawn from neighbouring ideas.","skill_tag":"detail","sub_skill":"ending-match","order_num":4},{"id":"07194019-3cc2-4574-b3d0-64921f84826b","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":3,"question_type":"matching_information","prompt":"Which paragraph refers to an explorer who reached a place no person had stood before? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D states that Amundsen and his team were the first people ever to stand at the South Pole, in December 1911.","skill_tag":"scanning","sub_skill":"locate-information","order_num":3},{"id":"07d62891-8354-47fd-9cb6-284f1cf81543","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":6,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nMagellan's surviving crew …","payload":{"options":[{"text":"used fleets far larger than any in Europe at the time.","label":"i"},{"text":"completed the first voyage around the globe.","label":"ii"},{"text":"reached the southernmost point on the planet.","label":"iii"},{"text":"were recorded in a famous travel book.","label":"iv"},{"text":"discovered a sea route to the moon.","label":"v"},{"text":"mapped every river in Africa.","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph B says his crew completed the first voyage all the way around the world, matching ending ii.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":6},{"id":"09a448ee-cb28-4538-96fb-0d3396f1fe3d","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":1,"question_type":"matching_information","prompt":"Which paragraph mentions an explorer whose own journey was completed only after his death? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B explains that Magellan was killed in the Philippines in 1521, and only his surviving crew finished the voyage around the world in 1522.","skill_tag":"scanning","sub_skill":"locate-information","order_num":1},{"id":"0bd234d1-8952-4b9f-9215-9240f9ffae6b","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nReassembled geometric fragments to show several viewpoints at once.","payload":{"options":[{"text":"Realism","label":"A"},{"text":"Impressionism","label":"B"},{"text":"Cubism","label":"C"},{"text":"Surrealism","label":"D"},{"text":"Abstract Expressionism","label":"E"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D says in Cubism 'objects were broken into geometric facets and reassembled so that several viewpoints appeared at once'. This detail points only to Cubism.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"0cada37c-b82f-4c90-909c-bff2aced76f3","passage_id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","q_num":5,"question_type":"matching_information","prompt":"Which paragraph describes a technique in which paint was applied without the artist touching the canvas with a brush?","payload":{},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph E describes how Jackson Pollock laid his canvas on the floor and dripped or poured paint onto it, working without a brush against the surface. The other paragraphs describe subject matter or viewpoint rather than this method of applying paint.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"0cbebe5d-149b-4329-8013-5d1c4be74778","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nShowed that tiny organisms could cause illness and developed gentle heating to kill microbes in liquids.","payload":{"options":[{"text":"Louis Pasteur","label":"A"},{"text":"Joseph Lister","label":"B"},{"text":"Florence Nightingale","label":"C"},{"text":"Alexander Fleming","label":"D"},{"text":"Edward Jenner","label":"E"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Pasteur demonstrated that illnesses were caused 'not by bad air but by tiny living organisms', the principle of germ theory. Lister (B) applied this idea to surgery rather than discovering it, so attributing the discovery to him is a half-correct trap.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"0dc10f55-8f6e-46f3-a60b-18c0c7b29645","passage_id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDemonstrated that a steam-powered passenger boat could earn a steady profit.","payload":{"options":[{"text":"Karl Benz","label":"A"},{"text":"George Stephenson","label":"B"},{"text":"Robert Fulton","label":"C"},{"text":"John Kemp Starley","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C says Fulton's steamboat carried fare-paying passengers up the Hudson River and was the first to make a steady profit. Stephenson (B) moved carriages on land by rail, not boats on a river.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"131b3058-496b-4b99-bc1e-3f490ca99f4e","passage_id":"927626aa-24cb-4cd8-967e-60613afb4cb0","q_num":3,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nClassical economists assume that individuals …","payload":{"options":[{"text":"respond mainly to changes in the money supply","label":"i"},{"text":"behave as broadly rational, self-interested agents","label":"ii"},{"text":"should be guided by government spending","label":"iii"},{"text":"often make predictable errors of judgement","label":"iv"},{"text":"ignore prices altogether","label":"v"},{"text":"cannot be studied scientifically","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph B says the classical model rests on individuals who are 'rational and self-interested'. Ending (iv) describes behavioural economics, a reversed trap; (iii) describes Keynesian policy; (i) describes monetarism.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":3},{"id":"13cc9b3e-1a84-483c-9e00-1b3bcc2b7bba","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":5,"question_type":"table_completion","prompt":"Gap 5: the positive electrode is also known as the __________. (ONE WORD ONLY) — see the table above.","payload":{},"answer":{"answer":"cathode","alternatives":[]},"explanation":"Paragraph 2 explicitly names the positive electrode the cathode.","skill_tag":"detail","sub_skill":"table-gap","order_num":5},{"id":"157675f1-9fe5-4748-b471-4b5d8bdd6059","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":7,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nEarlier biologists were reluctant to believe that animals could use …","payload":{"options":[{"text":"true, structured communication.","label":"i"},{"text":"a sense of direction underground.","label":"ii"},{"text":"the ability to recognise human faces.","label":"iii"},{"text":"any reaction to danger at all.","label":"iv"},{"text":"a preference for warmer climates.","label":"v"},{"text":"narrower than once believed.","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph A says researchers long hesitated to credit animals with genuine, structured communication, matching ending i.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":7},{"id":"178ef5cb-e458-437a-9227-1890f0567f74","passage_id":"fe692d52-7c82-4e24-b983-2dfacf506795","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nLeft gaps in an arrangement of elements that later discoveries filled.","payload":{"options":[{"text":"Isaac Newton","label":"A"},{"text":"Charles Darwin","label":"B"},{"text":"Marie Curie","label":"C"},{"text":"Dmitri Mendeleev","label":"D"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph E credits Mendeleev with a table in which gaps allowed him to forecast undiscovered elements. Newton (A) worked on forces and light, not chemical elements, so attributing the periodic pattern to him would be a category error.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"1b86f415-bfe5-4f5e-8f68-3461bc670899","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nVygotsky's account holds that …","payload":{"options":[{"text":"children routinely produce sentences they have never heard before.","label":"A"},{"text":"reinforcement alone could explain the entire course of development.","label":"B"},{"text":"adults rarely correct the small grammatical errors children make.","label":"C"},{"text":"the social context of speech is irrelevant to acquisition.","label":"D"},{"text":"thought itself takes shape through dialogue with more capable partners.","label":"E"}]},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph D explains that, for Vygotsky, cognition is built through guided interaction with abler companions, matching ending E. D contradicts his emphasis on social context and serves as a trap.","skill_tag":"detail","sub_skill":"ending-match","order_num":5},{"id":"1f67d7cb-59fb-495e-ac3f-419a5c34588a","passage_id":"927626aa-24cb-4cd8-967e-60613afb4cb0","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nMade the amount of money circulating in the economy the main lever over prices.","payload":{"options":[{"text":"Classical economics","label":"A"},{"text":"Keynesian economics","label":"B"},{"text":"Monetarism","label":"C"},{"text":"Behavioural economics","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D presents monetarism's central claim that controlling the money supply is the key to managing inflation. Keynesianism (B) stresses spending and demand instead, a common confusion. Behavioural economics is an extra option not linked to this claim.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"2464c56e-2964-4a3a-adca-71127a81cdb6","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":6,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nFamilies celebrating Diwali …","payload":{"options":[{"text":"throw bright powder and water over one another.","label":"i"},{"text":"light small lamps to welcome good fortune.","label":"ii"},{"text":"remember and honour relatives who have died.","label":"iii"},{"text":"follow a date that is set by the moon.","label":"iv"},{"text":"fast quietly from sunrise until sunset.","label":"v"},{"text":"give one another expensive gold jewellery.","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph B says people light rows of small lamps to welcome good luck and a fresh start, matching ending ii.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":6},{"id":"2561147d-987f-424c-9f56-c2ee7530820d","passage_id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","q_num":5,"question_type":"matching_information","prompt":"Which paragraph notes that a once-dominant position was undermined by a difficulty about how two different things could interact?","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B records that Cartesian dualism was weakened by the puzzle of how an immaterial mind could act on a physical body. Paragraph C describes functionalism's alternative rather than a flaw, while D and E concern experience, not interaction.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"273945e8-f49b-4487-b1a1-87357eff3609","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":2,"question_type":"matching_information","prompt":"Which paragraph describes a wonder whose existence is still doubted? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B notes that no firm trace of the Hanging Gardens has been found and that some historians doubt whether they existed at all.","skill_tag":"scanning","sub_skill":"locate-information","order_num":2},{"id":"3253fef6-5dcf-42f3-85f2-0f9f2234ca0a","passage_id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nSolar panels …","payload":{"options":[{"text":"depend on a large river and a high dam","label":"i"},{"text":"contain no moving parts and can be fitted to buildings that already stand","label":"ii"},{"text":"only work where the ground is volcanically active","label":"iii"},{"text":"release carbon dioxide that regrowth must absorb","label":"iv"},{"text":"produce a steady output regardless of weather","label":"v"},{"text":"store energy for several weeks at a time","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph B says solar panels have no moving parts and can be fitted onto rooftops that already exist, matching ending (ii). Ending (i) describes hydropower, (iii) geothermal and (iv) biomass; ending (v) is reversed, since solar output varies with sunlight.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"33b54b7b-9665-48ff-b8b4-52a077ecb2f3","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nProposed an innate universal grammar to explain children's ability to create unfamiliar sentences.","payload":{"options":[{"text":"Skinner","label":"A"},{"text":"Chomsky","label":"B"},{"text":"Vygotsky","label":"C"},{"text":"Tomasello","label":"D"},{"text":"Piaget","label":"E"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C credits Chomsky with the nativist claim of a 'universal grammar' present from birth, an inborn blueprint shared by all languages. The match is B.","skill_tag":"detail","sub_skill":"feature-match","order_num":2},{"id":"3760595e-ae40-48d9-9bde-f61d622e5924","passage_id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","q_num":3,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe Bauhaus argued that an object's appearance should …","payload":{"options":[{"text":"follow directly from its function and its materials","label":"i"},{"text":"imitate the cathedrals of the medieval past","label":"ii"},{"text":"conceal the structure behind decorative surfaces","label":"iii"},{"text":"quote freely from many earlier styles at once","label":"iv"},{"text":"avoid any use of modern industrial techniques","label":"v"},{"text":"be decided by the client rather than the designer","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph C says the Bauhaus held that form should follow function and arise from the honest use of materials, matching ending (i). Ending (iv) describes Postmodernism; (iii) is the opposite of Bauhaus honesty; (ii) describes the Gothic revival.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":3},{"id":"38c4c1b3-d073-4344-b9d3-c16174b26c22","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":3,"question_type":"matching_information","prompt":"Which paragraph mentions an inventor who improved an existing idea rather than starting from nothing? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B states that Edison did not invent the first electric light but made an earlier idea work for ordinary homes — improving an existing idea.","skill_tag":"scanning","sub_skill":"locate-information","order_num":3},{"id":"3c7b90ee-e669-417e-b565-b3c025e6a544","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed records and diagrams to argue that improved hospital sanitation could save lives.","payload":{"options":[{"text":"Louis Pasteur","label":"A"},{"text":"Joseph Lister","label":"B"},{"text":"Florence Nightingale","label":"C"},{"text":"Alexander Fleming","label":"D"},{"text":"Edward Jenner","label":"E"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D credits Nightingale with recording deaths and using statistics in clear diagrams to argue that sanitation could save soldiers' lives. The military-hospital and statistics detail points only to her.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"3db27d40-55a4-427f-b73e-9d91d553d8ff","passage_id":"91b89f32-5d37-4408-924b-392a904cbd3a","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed new computer tools to make sweeping forms possible and became the first woman to win the Pritzker Prize.","payload":{"options":[{"text":"Antoni Gaudí","label":"A"},{"text":"Frank Lloyd Wright","label":"B"},{"text":"Zaha Hadid","label":"C"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D states that Hadid relied on new computer tools to realise her swooping, fluid shapes that earlier builders could not have constructed. Gaudí (A) worked by hand without such tools, making him the wrong match here.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"3e72d359-6cb1-400c-973c-433e1fcefcbd","passage_id":"927626aa-24cb-4cd8-967e-60613afb4cb0","q_num":5,"question_type":"matching_information","prompt":"Which paragraph notes that an economic school rose to prominence in response to a specific historical crisis?","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C ties the rise of Keynesian thinking to the mass unemployment of the 1930s Depression. Paragraph D mentions inflation in general terms but not a single defining crisis, while B and E describe assumptions rather than a triggering event.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"3e7b9a7b-3e22-4772-b4c6-8c3f8dc7b2d0","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":4,"question_type":"true_false_not_given","prompt":"Elinor Ostrom found that successful management of the commons always required either privatisation or central government control.","payload":{},"answer":{"answer":"FALSE","alternatives":["F","false"]},"explanation":"The text states Ostrom documented communities governing resources successfully without privatisation or state control, the opposite of the statement, so it is FALSE.","skill_tag":"detail","sub_skill":"locate-fact","order_num":4},{"id":"3ead49f0-0c16-4197-95f0-2f4e0b57ee23","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nMade careful maps of New Zealand and eastern Australia that remained useful after his death.","payload":{"options":[{"text":"Zheng He","label":"A"},{"text":"Ferdinand Magellan","label":"B"},{"text":"James Cook","label":"C"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D says Cook drew careful maps of the coasts of New Zealand and eastern Australia, matching explorer C.","skill_tag":"detail","sub_skill":"match-feature","order_num":3},{"id":"3f9de739-1196-40c9-9f4d-f464566ba52c","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":6,"question_type":"matching_information","prompt":"The passage has six paragraphs, A–F. Which paragraph contains the following information? Write the correct letter, A–F. NB You may use any letter more than once.","payload":{},"answer":{"answer":"F","alternatives":["F"]},"explanation":"Paragraph F closes by suggesting that the rival accounts may each illuminate a different facet of acquisition rather than excluding one another. The information sits in paragraph F.","skill_tag":"scanning","sub_skill":"locate-info","order_num":6},{"id":"3fc13bf9-3a5b-46af-9dd1-8bfade6c2048","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":7,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nAmundsen and his companions …","payload":{"options":[{"text":"used fleets far larger than any in Europe at the time.","label":"i"},{"text":"completed the first voyage around the globe.","label":"ii"},{"text":"reached the southernmost point on the planet.","label":"iii"},{"text":"were recorded in a famous travel book.","label":"iv"},{"text":"discovered a sea route to the moon.","label":"v"},{"text":"mapped every river in Africa.","label":"vi"}]},"answer":{"answer":"iii","alternatives":[]},"explanation":"Paragraph D explains that Amundsen reached the South Pole, the most southern point on Earth, matching ending iii. (Endings iv, v and vi are unused distractors.)","skill_tag":"detail","sub_skill":"sentence-ending","order_num":7},{"id":"40f28a01-850c-4388-8470-44cedc8e3f90","passage_id":"fe692d52-7c82-4e24-b983-2dfacf506795","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nConnected the fall of an apple and the movement of planets through one law.","payload":{"options":[{"text":"Isaac Newton","label":"A"},{"text":"Charles Darwin","label":"B"},{"text":"Marie Curie","label":"C"},{"text":"Dmitri Mendeleev","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Newton's law of gravitation tied together an apple's fall and the orbits of planets under one rule. Mendeleev (D) unified chemistry, not motion, so he is a tempting but wrong match here.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"413f867d-59c3-496b-882b-c4cfd63acd5a","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nDuring Holi, participants …","payload":{"options":[{"text":"throw bright powder and water over one another.","label":"i"},{"text":"light small lamps to welcome good fortune.","label":"ii"},{"text":"remember and honour relatives who have died.","label":"iii"},{"text":"follow a date that is set by the moon.","label":"iv"},{"text":"fast quietly from sunrise until sunset.","label":"v"},{"text":"give one another expensive gold jewellery.","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph A says that at Holi people cover each other in clouds of coloured powder and splash water, matching ending i.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":5},{"id":"4182d024-4d35-4213-8ca8-3e2bf4a89a41","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":8,"question_type":"flow_chart_completion","prompt":"Gap 8: once the chemicals are used up, the battery goes __________. (ONE WORD ONLY) — see the flow-chart above.","payload":{},"answer":{"answer":"flat","alternatives":["dead"]},"explanation":"Paragraph 4 calls the battery flat, or dead in everyday speech, when the reaction can no longer push electrons around the circuit.","skill_tag":"detail","sub_skill":"process-step","order_num":8},{"id":"431c1040-ef60-4fe6-8f05-a5672a86328f","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":7,"question_type":"matching_information","prompt":"See the instruction above. Which paragraph contains the following information? Write the correct letter, A–F.","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B illustrates the behaviourist mechanism with the example of a toddler praised for saying 'milk', a concrete case of learning through reward. The information sits in paragraph B.","skill_tag":"scanning","sub_skill":"locate-info","order_num":7},{"id":"44df9eb4-c629-4e23-8b9b-0e89152984d7","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":6,"question_type":"matching_information","prompt":"Which paragraph describes a voyage measured to last almost exactly one thousand and eighty days? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C states the round-the-world voyage took about 1,080 days, the only paragraph that gives that figure.","skill_tag":"scanning","sub_skill":"locate-information","order_num":6},{"id":"46ca745d-1e2c-4f8b-8942-0b50da536249","passage_id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUses falling water to turn turbines, although large dams may displace communities.","payload":{"options":[{"text":"Solar power","label":"A"},{"text":"Hydropower","label":"B"},{"text":"Geothermal power","label":"C"},{"text":"Biomass energy","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C states that hydropower has been generating electricity on a large scale for longer than any other renewable source. Solar (A) is described as newer and fast-growing, which is the contrast the question targets.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"48bd09a9-8fc2-4825-8803-4928eb240abe","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":4,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nStudied a parrot that used spoken labels for objects, colours and shapes.","payload":{"options":[{"text":"Karl von Frisch","label":"A"},{"text":"Irene Pepperberg","label":"B"},{"text":"Con Slobodchikoff","label":"C"},{"text":"Katy Payne","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C credits Irene Pepperberg, whose parrot Alex learned to label objects, colours and small numbers.","skill_tag":"detail","sub_skill":"match-feature","order_num":4},{"id":"498097d4-2ee5-49e2-a591-6db64957a5be","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":3,"question_type":"short_answer","prompt":"According to critics, which two kinds of resource did Hardin wrongly treat as the same? Give the term for the type with no rules. (one word, hyphenated)","payload":{},"answer":{"answer":"open-access","alternatives":[]},"explanation":"The passage says Hardin conflated genuinely open-access resources with managed common property; 'open-access' appears verbatim.","skill_tag":"detail","sub_skill":"locate-fact","order_num":3},{"id":"498b6815-4285-4f34-8150-1054da07f593","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":5,"question_type":"matching_information","prompt":"Which paragraph mentions a method that lowered the risk of infection during operations?","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C describes Lister spraying carbolic acid on instruments and dressings, after which death rates following surgery 'fell sharply'. This is the only paragraph about reducing infection in the operating theatre.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"4a60f8fb-8203-42a9-8095-b207f1a215e0","passage_id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nExplained conscious emotion as the mind's reading of a bodily reaction that has already begun.","payload":{"options":[{"text":"James-Lange theory","label":"A"},{"text":"Cannon-Bard theory","label":"B"},{"text":"Schachter-Singer two-factor theory","label":"C"},{"text":"Lazarus appraisal theory","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to the James-Lange position the claim that the felt emotion follows, rather than causes, the physical reaction. The Cannon-Bard view (B) is the half-correct trap, since paragraph C insists the bodily response and the feeling occur at the same moment rather than one after the other.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"4b763bad-8006-4802-82a9-3105e9ed4bdf","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":2,"question_type":"matching_information","prompt":"Which paragraph mentions a festival that honours family members who have died? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C explains that during the Day of the Dead families remember relatives who have passed away, honouring those who have died.","skill_tag":"scanning","sub_skill":"locate-information","order_num":2},{"id":"4bc9b245-5971-43cb-9d04-48958bce67ec","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nZheng He's expeditions …","payload":{"options":[{"text":"used fleets far larger than any in Europe at the time.","label":"i"},{"text":"completed the first voyage around the globe.","label":"ii"},{"text":"reached the southernmost point on the planet.","label":"iii"},{"text":"were recorded in a famous travel book.","label":"iv"},{"text":"discovered a sea route to the moon.","label":"v"},{"text":"mapped every river in Africa.","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph A says Zheng He's fleets were far bigger than anything Europe could build then, matching ending i.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":5},{"id":"4f85cd86-c111-45e7-8ff7-fccb985e3f6e","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":1,"question_type":"matching_information","prompt":"Which paragraph contains the following information? An example of communication that travels over long distances and is largely inaudible to humans. (Write the correct letter A–E. NB You may use any letter only once here.)","payload":{},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph E describes Katy Payne's discovery that elephants use very low-frequency infrasound, which carries for kilometres and lies mostly below human hearing.","skill_tag":"scanning","sub_skill":"locate-information","order_num":1},{"id":"4fb65191-dbaa-409e-becf-23675928445f","passage_id":"91b89f32-5d37-4408-924b-392a904cbd3a","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nBased flowing architectural curves on natural forms such as plants and shells.","payload":{"options":[{"text":"Antoni Gaudí","label":"A"},{"text":"Frank Lloyd Wright","label":"B"},{"text":"Zaha Hadid","label":"C"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Gaudí drew his flowing shapes from plants, shells and skeletons so that his buildings look almost grown rather than built. Wright (B) worked with the land but in long, level lines, not organic curves, so attributing the plant-and-bone forms to him is a half-correct trap.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"5197b1b5-7e29-4862-94d6-13c79f2a08b6","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":5,"question_type":"matching_information","prompt":"Which paragraph describes a theory that judges an arrangement by the total amount of welfare it produces?","payload":{},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph E sets out the utilitarian tradition, for which 'the justice of an arrangement turns simply on the sum of welfare it generates'. Paragraph A frames the general problem and B–D describe rival principles that reject this aggregative test.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"52a73560-4514-46f5-99be-07bf8904e75a","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":2,"question_type":"matching_information","prompt":"Which paragraph describes a traveller who wrote a long record of the places he visited? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C says Ibn Battuta dictated a famous book describing the many lands he had seen across roughly 30 years of travel.","skill_tag":"scanning","sub_skill":"locate-information","order_num":2},{"id":"52eaf50b-bc0f-453d-8567-3747ce3bfd71","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":2,"question_type":"matching_information","prompt":"Which paragraph contains a reference to communication that conveys detailed descriptions of a threat?","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D explains Con Slobodchikoff's finding that prairie-dog alarm calls encode the type, size and even colour of an approaching predator.","skill_tag":"scanning","sub_skill":"locate-information","order_num":2},{"id":"54c646c2-99a6-4beb-aa4d-8fe20a243ea0","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":1,"question_type":"matching_information","prompt":"Which paragraph mentions an invention that was first thought to be useless? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C says many people at first saw little use for Bell's telephone, treating it as a toy, which matches 'first thought to be useless'.","skill_tag":"scanning","sub_skill":"locate-information","order_num":1},{"id":"55784747-e886-41e6-ac2b-31e52ccc68ec","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":5,"question_type":"matching_information","prompt":"Which paragraph mentions ships that carried gifts to make friends with distant lands? (Write the correct letter A–D. NB You may use any letter more than once.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B explains that Zheng He's treasure ships carried gifts to build friendship with faraway kingdoms; this is the 'gifts to distant lands' detail.","skill_tag":"scanning","sub_skill":"locate-information","order_num":5},{"id":"59f8ca7c-2e89-403c-b68a-d04e53b87731","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":1,"question_type":"mcq_single","prompt":"In Hardin's model, why does the shared pasture end up ruined?","payload":{"options":[{"text":"Because the climate suddenly changes","label":"A"},{"text":"Because each herder gains by adding animals while all share the cost","label":"B"},{"text":"Because the government takes the land away","label":"C"},{"text":"Because herders cannot afford more animals","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"B is correct: in Hardin's model each rational herder keeps adding animals because the gain is private while the cost of degradation is shared by all, so the pasture is ruined. A (the climate suddenly changes) is out-of-scope, the model blames behaviour, not weather. C (the government takes the land) is out-of-scope and reversed, the problem is unmanaged open access, not seizure. D (herders cannot afford more animals) is reversed, the tragedy arises precisely because they keep adding more.","skill_tag":"detail","sub_skill":"locate-fact","order_num":1},{"id":"5aefffe9-0fa6-4c14-b8ab-fbaa4d201d35","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":7,"question_type":"flow_chart_completion","prompt":"Gap 7: the electrons moving along the wire create an electric __________. (ONE WORD ONLY) — see the flow-chart above.","payload":{},"answer":{"answer":"current","alternatives":[]},"explanation":"Paragraph 3 explains that this steady flow of electrons is an electric current; 'current' appears verbatim.","skill_tag":"detail","sub_skill":"process-step","order_num":7},{"id":"5e04c52d-8cc2-4698-b332-9b2312f9cbcd","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":7,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nDuring the Day of the Dead, families …","payload":{"options":[{"text":"throw bright powder and water over one another.","label":"i"},{"text":"light small lamps to welcome good fortune.","label":"ii"},{"text":"remember and honour relatives who have died.","label":"iii"},{"text":"follow a date that is set by the moon.","label":"iv"},{"text":"fast quietly from sunrise until sunset.","label":"v"},{"text":"give one another expensive gold jewellery.","label":"vi"}]},"answer":{"answer":"iii","alternatives":[]},"explanation":"Paragraph C says families gather to remember relatives who have passed away, matching ending iii. (Endings iv, v and vi are unused distractors.)","skill_tag":"detail","sub_skill":"sentence-ending","order_num":7},{"id":"5e4d1346-3e27-4682-b89a-246603d7144d","passage_id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","q_num":3,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nFunctionalists define a mental state in terms of …","payload":{"options":[{"text":"the immaterial soul that supposedly inhabits it","label":"i"},{"text":"the role it plays in a wider system of inputs and outputs","label":"ii"},{"text":"an inner glow that physics can never capture","label":"iii"},{"text":"a confusion that careful analysis will dissolve","label":"iv"},{"text":"the precise chemistry of the brain that produces it","label":"v"},{"text":"a question science should refuse to ask","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph C says functionalists define a mental state by 'the job it does' in a network of inputs, outputs and other states, matching ending (ii). Ending (i) describes Cartesian dualism; (iii) describes Chalmers; (iv) describes Dennett.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":3},{"id":"6429f38d-66c1-4a7e-a3c6-3c01036ec74e","passage_id":"927626aa-24cb-4cd8-967e-60613afb4cb0","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nExpected temporary market disruptions to correct themselves without outside intervention.","payload":{"options":[{"text":"Classical economics","label":"A"},{"text":"Keynesian economics","label":"B"},{"text":"Monetarism","label":"C"},{"text":"Behavioural economics","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to the classical tradition the view that, without interference, markets move back towards balance on their own. Keynesianism (B) is the half-correct trap, since paragraph C explicitly rejects this self-correction in the short run.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"64792d09-856b-422b-91e7-22e7ebe1a1c3","passage_id":"59bd33e8-ead5-4edf-8d3f-8c480eb04348","q_num":2,"question_type":"mcq_single","prompt":"What can be inferred about why blue is common in offices and hospitals?","payload":{"options":[{"text":"Blue is the cheapest paint to produce","label":"A"},{"text":"People associate blue with calm and focus","label":"B"},{"text":"Blue improves eyesight in bright rooms","label":"C"},{"text":"Blue is legally required in workplaces","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph 2 links blue to feeling 'calmer and better able to concentrate', so its use in workplaces is implied to rest on these associations. A (cost) and D (law) are out of scope — never mentioned. C distorts the text, which discusses mood and attention, not eyesight.","skill_tag":"inference","sub_skill":"cause-effect","order_num":2},{"id":"66188e1c-42da-4199-966d-e38b8ae9f1df","passage_id":"59bd33e8-ead5-4edf-8d3f-8c480eb04348","q_num":3,"question_type":"mcq_multi","prompt":"Choose TWO points the passage makes about colour responses.","payload":{"options":[{"text":"They can be shaped by a person's culture","label":"A"},{"text":"They are identical across the whole world","label":"B"},{"text":"They may depend on the situation","label":"C"},{"text":"They are fixed from birth","label":"D"},{"text":"They have no effect on behaviour","label":"E"}]},"answer":{"answer":"A, C","alternatives":[]},"explanation":"Paragraph 4 states meanings 'shift from one culture to another' (A) and that the same colour 'can pull in different directions depending on where it appears' (C). B and D are reversed — the passage stresses variation, not uniformity or innateness. E contradicts the whole text, which describes measurable effects.","skill_tag":"detail","sub_skill":"multi-select","order_num":3},{"id":"6757ffc2-bd16-4888-bd73-c7779d847e1d","passage_id":"145f4430-a780-4988-b3bd-f977f2c73704","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nArgued that separate parts of an aircraft could provide lift, propulsion and control.","payload":{"options":[{"text":"George Cayley","label":"A"},{"text":"Otto Lilienthal","label":"B"},{"text":"The Wright brothers","label":"C"},{"text":"Alberto Santos-Dumont","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Cayley set out the forces a flying machine must deal with — lift, weight, thrust and drag — early in the nineteenth century, well before engines made flight possible. Lilienthal (B) tested gliders later; the item targets the theory of forces, which is Cayley's contribution.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"67a32191-e6fa-4a3b-8fe8-5ffdaf7c496a","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":3,"question_type":"matching_information","prompt":"Which paragraph contains a statement about how a discovery was initially received with doubt?","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B notes that von Frisch's claim about the bees' dance was at first met with scepticism before later being confirmed.","skill_tag":"scanning","sub_skill":"locate-information","order_num":3},{"id":"687f71d7-2287-4f1d-86b6-2814f5444027","passage_id":"b2fb439b-2bc7-4316-9ea0-9c0011c0238a","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions a commander who led a very large fleet of ships? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A says Zheng He commanded huge fleets of hundreds of ships carrying thousands of men across the Indian Ocean.","skill_tag":"scanning","sub_skill":"locate-information","order_num":4},{"id":"6a5e9dcd-6e21-4010-bf18-f95be41fd134","passage_id":"59bd33e8-ead5-4edf-8d3f-8c480eb04348","q_num":1,"question_type":"mcq_single","prompt":"What does the passage imply about the claim that wearing red helps combat athletes win?","payload":{"options":[{"text":"It has been disproved by later studies","label":"A"},{"text":"It should be treated with some caution","label":"B"},{"text":"It applies only to professional athletes","label":"C"},{"text":"It is the strongest finding in the field","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph 3 says the effect 'has not always reappeared when other researchers repeat the experiment', which implies the finding is uncertain and should be treated carefully. A is too extreme — the text says results are mixed, not that the claim is disproved. C is a half-correct trap: athletes are the example, not a stated limit. D is out of scope and reversed; the passage presents this finding as shaky, not the strongest.","skill_tag":"inference","sub_skill":"writer-view","order_num":1},{"id":"6c90d322-5804-4cfa-85ba-18e47ade20a2","passage_id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nPostmodern architects were willing to …","payload":{"options":[{"text":"follow directly from its function and its materials","label":"i"},{"text":"imitate the cathedrals of the medieval past","label":"ii"},{"text":"conceal the structure behind decorative surfaces","label":"iii"},{"text":"quote freely from many earlier styles at once","label":"iv"},{"text":"avoid any use of modern industrial techniques","label":"v"},{"text":"be decided by the client rather than the designer","label":"vi"}]},"answer":{"answer":"iv","alternatives":[]},"explanation":"Paragraph E reports that Postmodernism playfully borrowed and mixed motifs from many past styles, matching ending (iv). Ending (i) is the modernist creed Postmodernism rejected, making it a reversed distractor.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"6f120207-70b6-4b41-a6cf-b0c08ca17a83","passage_id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nArgued that explaining brain mechanisms leaves the feeling of experience unexplained.","payload":{"options":[{"text":"René Descartes","label":"A"},{"text":"The functionalists","label":"B"},{"text":"David Chalmers","label":"C"},{"text":"Daniel Dennett","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D presents Chalmers's claim that explaining felt experience is a distinct 'hard problem' untouched by accounts of physical function. Dennett (D) is the reversed distractor, since paragraph E reports his view that no such residue remains once function is explained.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"73dfab7c-abb2-4b80-a402-780df35a5ba2","passage_id":"927626aa-24cb-4cd8-967e-60613afb4cb0","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nBehavioural economists argue that individuals …","payload":{"options":[{"text":"respond mainly to changes in the money supply","label":"i"},{"text":"behave as broadly rational, self-interested agents","label":"ii"},{"text":"should be guided by government spending","label":"iii"},{"text":"often make predictable errors of judgement","label":"iv"},{"text":"ignore prices altogether","label":"v"},{"text":"cannot be studied scientifically","label":"vi"}]},"answer":{"answer":"iv","alternatives":[]},"explanation":"Paragraph E reports that behavioural work documented 'systematic, repeatable mistakes', matching ending (iv). Ending (ii) is exactly the assumption behavioural economists rejected, making it a reversed distractor.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"7622711c-c0a7-49d0-a996-b6d055424b2b","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":5,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDiscovered that a dance communicates both the direction and the distance of food.","payload":{"options":[{"text":"Karl von Frisch","label":"A"},{"text":"Irene Pepperberg","label":"B"},{"text":"Con Slobodchikoff","label":"C"},{"text":"Katy Payne","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B credits von Frisch with decoding the honeybee 'waggle dance', which signals the direction and distance of food.","skill_tag":"detail","sub_skill":"match-feature","order_num":5},{"id":"76935be2-932b-46b7-9804-82542c2c111f","passage_id":"91b89f32-5d37-4408-924b-392a904cbd3a","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions a building that is still unfinished today?","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B notes that Gaudí's great church, the Sagrada Família, remains incomplete more than a century after work began. Other paragraphs describe Wright's finished houses (C) or Hadid's career (D), not an unfinished building.","skill_tag":"scanning","sub_skill":null,"order_num":4},{"id":"770fe181-4969-48f0-9410-5c831b1e031a","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":3,"question_type":"matching_information","prompt":"Which paragraph mentions a wonder that was destroyed by an earthquake? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D explains that an earthquake snapped the Colossus of Rhodes at the knees and brought it crashing down.","skill_tag":"scanning","sub_skill":"locate-information","order_num":3},{"id":"78e35aeb-a9eb-443c-9e52-93bf00e3e9b2","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":2,"question_type":"yes_no_not_given","prompt":"The writer regards Hardin's conclusion as the final word on shared resources.","payload":{},"answer":{"answer":"NO","alternatives":["N","no"]},"explanation":"The writer presents Ostrom's evidence against Hardin and calls the modern view more nuanced, so treating Hardin's conclusion as final contradicts the author, giving NO.","skill_tag":"writer_view_TFNG","sub_skill":null,"order_num":2},{"id":"79f4ae9c-cf5c-4c5c-9eb9-5bbda724df7c","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":4,"question_type":"matching_information","prompt":"Which paragraph describes a discovery that came about largely by chance?","payload":{},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph E says the turning point 'came almost by accident', when Fleming returned from holiday to find a mould had drifted into a dish of bacteria. The other paragraphs describe deliberate experiments or methods, not a chance discovery.","skill_tag":"scanning","sub_skill":null,"order_num":4},{"id":"7a6e0e2a-f162-4453-b073-15a03f319c6e","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nNoticed that mould in a dish had killed nearby bacterial colonies.","payload":{"options":[{"text":"Louis Pasteur","label":"A"},{"text":"Joseph Lister","label":"B"},{"text":"Florence Nightingale","label":"C"},{"text":"Alexander Fleming","label":"D"},{"text":"Edward Jenner","label":"E"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph E says Fleming found that a mould had killed bacteria and was producing a substance he named penicillin. Pasteur and Jenner worked on vaccines, not on a mould-derived antibiotic, so they are distractors here.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"7d400558-0554-457f-8eb0-9da84b299167","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":1,"question_type":"matching_information","prompt":"Which paragraph describes a festival where people throw coloured powder at one another? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A says that during Holi crowds cover each other in clouds of bright coloured powder, which matches throwing coloured powder.","skill_tag":"scanning","sub_skill":"locate-information","order_num":1},{"id":"7e7e7065-331a-413b-ac41-28baf1e674bb","passage_id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nLeft concrete bare so that a building's structure was plainly visible.","payload":{"options":[{"text":"Gothic architecture","label":"A"},{"text":"The Bauhaus","label":"B"},{"text":"Brutalism","label":"C"},{"text":"Postmodernism","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D presents Brutalism's signature use of bare concrete and openly displayed structure. The Bauhaus (B) is a plausible confusion because both prize honesty of materials, but the raw-concrete emphasis is specifically Brutalist.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"84298b60-4ebe-4adc-bb9d-3c161e6b8af7","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":5,"question_type":"sentence_completion","prompt":"Communities often keep a shared resource healthy by imposing __________ on members who take more than their share. (one word)","payload":{},"answer":{"answer":"sanctions","alternatives":["sanction"]},"explanation":"The passage describes communities imposing sanctions on those who overuse the resource; the word appears verbatim.","skill_tag":"detail","sub_skill":"locate-fact","order_num":5},{"id":"8a1da86b-a228-4424-81d8-02c020ff82d1","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe Wright brothers developed an aircraft that could …","payload":{"options":[{"text":"stay in the air under a pilot's control.","label":"i"},{"text":"be sold cheaply to every household.","label":"ii"},{"text":"fight off harmful bacteria in the body.","label":"iii"},{"text":"carry a human voice over a wire.","label":"iv"},{"text":"be powered only by the sun.","label":"v"},{"text":"replace the printing press completely.","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph A says the brothers showed a powered machine could rise and be steered by a pilot, matching ending i.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":5},{"id":"8c92f317-36c6-46ce-ba30-57fb317db545","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDied before the ships he sent out completed their voyage around the world.","payload":{"options":[{"text":"Zheng He","label":"A"},{"text":"Ferdinand Magellan","label":"B"},{"text":"James Cook","label":"C"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C says the ships started by Magellan became the first fleet ever to sail right around the world, matching explorer B.","skill_tag":"detail","sub_skill":"match-feature","order_num":1},{"id":"8e59bbe0-b2ef-4a81-8206-125879332720","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nJudged a distribution by legitimate acquisition and voluntary transfer rather than its overall pattern.","payload":{"options":[{"text":"Rawls","label":"A"},{"text":"Nozick","label":"B"},{"text":"Sen","label":"C"},{"text":"Utilitarianism","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C states Nozick's entitlement theory: a distribution is just if 'it arose through legitimate steps — fair acquisition and voluntary transfer — regardless of the overall shape it produces'. Utilitarianism (D) is an extra option, judging by total welfare rather than history, and is not linked to this claim.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"8f196a92-3261-4204-9191-20ada90a32db","passage_id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed loose brushstrokes to capture the light on an outdoor scene at one fleeting moment.","payload":{"options":[{"text":"Impressionism","label":"A"},{"text":"Cubism","label":"B"},{"text":"Surrealism","label":"C"},{"text":"Abstract Expressionism","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says the Impressionists painted outdoors to record how light fell on a scene at a single instant. Cubism (B) is the trap, since paragraph C is about showing several viewpoints at once rather than fleeting light. Abstract Expressionism is an option not linked to this aim.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"8ff3483c-663b-494c-936c-3341f7bf2ad7","passage_id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions an inventor who became known as the 'Father of Railways'? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B says George Stephenson built some of the world's first public railways and is often called the 'Father of Railways'.","skill_tag":"scanning","sub_skill":"locate-information","order_num":4},{"id":"91c465ea-0d90-4b1d-93b2-13030b9e483d","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":4,"question_type":"matching_information","prompt":"Which paragraph describes a festival in which homes are decorated with many small lamps? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B says that during Diwali people light rows of small oil lamps around their homes, matching the decoration with small lamps.","skill_tag":"scanning","sub_skill":"locate-information","order_num":4},{"id":"9224847b-0efd-492c-aaf5-168f69016383","passage_id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nBuilt an early petrol-powered three-wheeled motor car.","payload":{"options":[{"text":"Karl Benz","label":"A"},{"text":"George Stephenson","label":"B"},{"text":"Robert Fulton","label":"C"},{"text":"John Kemp Starley","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A credits Benz with the first true motor car, driven by a petrol engine, which his wife proved reliable on a 100-kilometre drive. Fulton (C) used steam on water, not a petrol engine, making him a half-correct trap.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"959ffced-7866-4b2f-93e4-26ef1369e0f0","passage_id":"91b89f32-5d37-4408-924b-392a904cbd3a","q_num":5,"question_type":"matching_information","prompt":"Which paragraph mentions an architect who was the first woman to receive a major prize?","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D says Hadid became the first woman to win the field's most respected award, the Pritzker Prize. The other paragraphs do not mention any prize being awarded for the first time to a woman.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"962fec56-34a8-409c-83bb-2e882c6d3609","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":4,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nBegan an exceptionally dangerous voyage in 1519, after which only a small number of his crew returned home.","payload":{"options":[{"text":"Zheng He","label":"A"},{"text":"Ferdinand Magellan","label":"B"},{"text":"James Cook","label":"C"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C says Magellan was killed before the journey was over and only some of his crew came home, matching explorer B.","skill_tag":"detail","sub_skill":"match-feature","order_num":4},{"id":"97822be9-7726-4537-94a8-98cb1386d990","passage_id":"e8bdd9b3-2ad6-4bf6-be03-769ac8c27f50","q_num":6,"question_type":"matching_information","prompt":"Which paragraph mentions a vaccine that was developed decades before a modern understanding of disease existed?","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A notes that Edward Jenner introduced a smallpox vaccine 'as early as 1796', but adds that 'a modern understanding of disease was still decades away' at that point. No other paragraph mentions Jenner or this early date.","skill_tag":"scanning","sub_skill":null,"order_num":6},{"id":"9906a71f-3f85-4c67-87e9-090641b29524","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":1,"question_type":"matching_information","prompt":"Which paragraph mentions the only wonder that is still standing today? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A says the Great Pyramid of Giza is the only one of the seven wonders that has survived into modern times.","skill_tag":"scanning","sub_skill":"locate-information","order_num":1},{"id":"9a11b89e-923c-4b55-bf7e-98028bfb245c","passage_id":"fe692d52-7c82-4e24-b983-2dfacf506795","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDeveloped an explanation of natural selection after about twenty years of observation.","payload":{"options":[{"text":"Isaac Newton","label":"A"},{"text":"Charles Darwin","label":"B"},{"text":"Marie Curie","label":"C"},{"text":"Dmitri Mendeleev","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C describes Darwin collecting observations for roughly two decades before setting out natural selection. Curie (C) also worked slowly, but her field was physics and chemistry rather than biology, making her the half-correct trap here; Newton (A) and Mendeleev (D) are the answers to earlier items, not matches for this statement.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"9a2226ea-081e-46c3-aff6-686250d21b2e","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":7,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nPenicillin was found to …","payload":{"options":[{"text":"stay in the air under a pilot's control.","label":"i"},{"text":"be sold cheaply to every household.","label":"ii"},{"text":"fight off harmful bacteria in the body.","label":"iii"},{"text":"carry a human voice over a wire.","label":"iv"},{"text":"be powered only by the sun.","label":"v"},{"text":"replace the printing press completely.","label":"vi"}]},"answer":{"answer":"iii","alternatives":[]},"explanation":"Paragraph D explains that penicillin could kill the bacteria that cause infections, matching ending iii. (Endings ii, v and vi are unused distractors.)","skill_tag":"detail","sub_skill":"sentence-ending","order_num":7},{"id":"9a34e8c2-64a8-4195-8beb-41a54f9c9d1b","passage_id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions a movement that was first met with mockery before being accepted?","payload":{},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph B notes that the Impressionists were ridiculed by early critics, and that their name began as an insult. Paragraph E mentions controversy over Abstract Expressionism but stresses debate over its value rather than open mockery at a debut.","skill_tag":"scanning","sub_skill":null,"order_num":4},{"id":"9c9ff861-18f7-40b8-a714-9ae4608a913c","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":6,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nSurrealist imagery drew on …","payload":{"options":[{"text":"the everyday lives of ordinary people.","label":"A"},{"text":"the title of one of Monet's paintings.","label":"B"},{"text":"the hidden workings of the unconscious mind.","label":"C"},{"text":"the strict rules of classical geometry.","label":"D"},{"text":"a return to medieval religious themes.","label":"E"},{"text":"the bright colours of modern advertising.","label":"F"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph E says the Surrealists filled their canvases with images 'drawn from the hidden workings of the unconscious mind', the ending that matches this beginning.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":6},{"id":"9cd84032-fa6f-42d7-82c8-f5db9896fb84","passage_id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nCounts as renewable only when regrowing plants absorb a similar amount of the carbon dioxide released.","payload":{"options":[{"text":"Solar power","label":"A"},{"text":"Hydropower","label":"B"},{"text":"Geothermal power","label":"C"},{"text":"Biomass energy","label":"D"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph F explains that biomass releases carbon when burned but is counted as renewable only if new plants regrow to absorb a similar amount. Solar (A) produces no such emissions, so attributing burning to it would be wrong.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"9d409be5-3607-4984-a89e-47077ead1de9","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nExplained language learning through imitation and reinforcement.","payload":{"options":[{"text":"Skinner","label":"A"},{"text":"Chomsky","label":"B"},{"text":"Vygotsky","label":"C"},{"text":"Tomasello","label":"D"},{"text":"Piaget","label":"E"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to Skinner the behaviourist view that speech is shaped by reinforcement — adults rewarding utterances that approximate their own. The match is A. Piaget (E) is the unused distractor, named nowhere in the passage.","skill_tag":"detail","sub_skill":"feature-match","order_num":1},{"id":"a18d2735-499b-46fd-b49b-24cf25e68744","passage_id":"fe692d52-7c82-4e24-b983-2dfacf506795","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions a scientist being honoured twice in two different fields?","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D states that Marie Curie won Nobel Prizes in both physics and chemistry, the only person at the time honoured in two separate sciences. Other paragraphs cover forces (B), biology (C) or the periodic table (E), none of which mention a double honour.","skill_tag":"scanning","sub_skill":null,"order_num":4},{"id":"a2bbdde5-ad6e-4921-b833-aee3f3e2c1be","passage_id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nBroke subjects into angular shapes and presented several viewpoints at the same time.","payload":{"options":[{"text":"Impressionism","label":"A"},{"text":"Cubism","label":"B"},{"text":"Surrealism","label":"C"},{"text":"Abstract Expressionism","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C explains that Cubist painters split a subject into angular fragments showing several views together. Impressionism (A) is the trap, as it kept the everyday appearance of its subjects. Surrealism is an unused option for this statement.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"a496aeab-ff8a-4aaf-98c2-97774396e498","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed quick brushstrokes outdoors to record changing natural light.","payload":{"options":[{"text":"Realism","label":"A"},{"text":"Impressionism","label":"B"},{"text":"Cubism","label":"C"},{"text":"Surrealism","label":"D"},{"text":"Abstract Expressionism","label":"E"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C says the Impressionists 'abandoned the studio to paint outdoors, trying to capture the shifting effects of natural light'. Realism (A) painted everyday life, not light effects, so it is a distractor here.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"a6239c83-9dd7-4336-8186-4c95dc831bed","passage_id":"fa34aa45-7083-495c-9c81-0a141987a9f6","q_num":3,"question_type":"matching_information","prompt":"Which paragraph refers to a festival whose date changes according to the moon? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D says the date of Chinese New Year follows the moon and so falls on a different day each year.","skill_tag":"scanning","sub_skill":"locate-information","order_num":3},{"id":"a74c2b37-62c9-4385-970e-49a6497c7c58","passage_id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nLarge hydroelectric dams can …","payload":{"options":[{"text":"depend on a large river and a high dam","label":"i"},{"text":"have no moving parts and can sit on existing rooftops","label":"ii"},{"text":"only work where the ground is volcanically active","label":"iii"},{"text":"release carbon dioxide that regrowth must absorb","label":"iv"},{"text":"flood valleys and force communities to move","label":"v"},{"text":"store energy for several weeks at a time","label":"vi"}]},"answer":{"answer":"v","alternatives":[]},"explanation":"Paragraph C notes that a large dam can drown valleys and displace the people living there, matching ending (v). Ending (iv) describes biomass, while (i), (ii), (iii) and (vi) describe features of other sources, making them distractors.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":5},{"id":"a7f6ec2d-d070-4367-8c05-250a421c9dc0","passage_id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","q_num":5,"question_type":"matching_information","prompt":"Which paragraph describes a journey made in order to prove that an invention was reliable? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A explains that, to prove the noisy car was reliable, Bertha Benz drove it more than 100 kilometres — the first long car journey in history.","skill_tag":"scanning","sub_skill":"locate-information","order_num":5},{"id":"a9215d8d-e3e4-4315-8ade-9f080e9a7016","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":6,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nBell's telephone was designed to …","payload":{"options":[{"text":"stay in the air under a pilot's control.","label":"i"},{"text":"be sold cheaply to every household.","label":"ii"},{"text":"fight off harmful bacteria in the body.","label":"iii"},{"text":"carry a human voice over a wire.","label":"iv"},{"text":"be powered only by the sun.","label":"v"},{"text":"replace the printing press completely.","label":"vi"}]},"answer":{"answer":"iv","alternatives":[]},"explanation":"Paragraph C says Bell's telephone sent the sound of a human voice along a wire, matching ending iv.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":6},{"id":"ab5a5ca7-fc7f-44e4-b400-7b40d275bcbc","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nPermitted inequalities only when they benefit the least well-off.","payload":{"options":[{"text":"Rawls","label":"A"},{"text":"Nozick","label":"B"},{"text":"Sen","label":"C"},{"text":"Utilitarianism","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to Rawls the 'difference principle', under which rational choosers 'would permit inequalities only where these work to the advantage of the least well-off'. Nozick (B) is the half-correct trap, since paragraph C has him reject patterned outcomes of just this kind.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"b36085d8-85b4-4b21-9f79-825f7d23d804","passage_id":"7ecb7e37-0a16-4b57-a123-7d10fafed24d","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nConnected language development with understanding the shared intentions behind another person's actions.","payload":{"options":[{"text":"Skinner","label":"A"},{"text":"Chomsky","label":"B"},{"text":"Vygotsky","label":"C"},{"text":"Tomasello","label":"D"},{"text":"Piaget","label":"E"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph E presents Tomasello's usage-based account, in which language grows from a child reading the shared goals behind others' actions. The match is D.","skill_tag":"detail","sub_skill":"feature-match","order_num":3},{"id":"b39cb5f1-fcce-46f0-b34c-bc36812b0bdd","passage_id":"145f4430-a780-4988-b3bd-f977f2c73704","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDeveloped a way to steer an aircraft about three axes.","payload":{"options":[{"text":"George Cayley","label":"A"},{"text":"Otto Lilienthal","label":"B"},{"text":"The Wright brothers","label":"C"},{"text":"Alberto Santos-Dumont","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D states the Wright brothers' key advance was a system for controlling an aircraft on three axes, making steady flight possible. Santos-Dumont (D) flew publicly but the control breakthrough is the Wrights'. Cayley (A) and Lilienthal (B) are the answers to earlier items, not matches for this statement.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"b3b04ac0-5077-4f4b-806b-6042b0e3efb3","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":8,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe researchers' findings suggest that the gap between human and animal communication may be …","payload":{"options":[{"text":"true, structured communication.","label":"i"},{"text":"a sense of direction underground.","label":"ii"},{"text":"the ability to recognise human faces.","label":"iii"},{"text":"any reaction to danger at all.","label":"iv"},{"text":"a preference for warmer climates.","label":"v"},{"text":"narrower than once believed.","label":"vi"}]},"answer":{"answer":"vi","alternatives":[]},"explanation":"The closing paragraph argues that, taken together, the discoveries narrow the supposed gap between human and animal communication, matching ending vi. (Endings ii, iii, iv and v are unused distractors.)","skill_tag":"detail","sub_skill":"sentence-ending","order_num":8},{"id":"b49bb389-e6fc-4ace-ac47-1473839205cf","passage_id":"acaf1dbd-bd86-41c8-83a0-6ab4dd7d8e28","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nIntroduced a safer bicycle with two equal wheels and a chain.","payload":{"options":[{"text":"Karl Benz","label":"A"},{"text":"George Stephenson","label":"B"},{"text":"Robert Fulton","label":"C"},{"text":"John Kemp Starley","label":"D"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D says Starley's 'safety bicycle' was far safer and easier to balance than the dangerous earlier bicycles with one huge wheel. Stephenson (B) worked on railways, not bicycles, so he is a wrong match.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"b4eb6caa-5fdb-4029-9a03-6b13c1827598","passage_id":"d4db5c3d-5e07-421b-ad8c-5302bcde7ae2","q_num":3,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDepicted dream-like scenes that did not obey ordinary logic.","payload":{"options":[{"text":"Impressionism","label":"A"},{"text":"Cubism","label":"B"},{"text":"Surrealism","label":"C"},{"text":"Abstract Expressionism","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D links Surrealism to dreams and the unconscious, producing images that defy ordinary logic. Cubism (B) is the trap because it too departed from realistic appearance, but through geometry rather than dream imagery.","skill_tag":"detail","sub_skill":"matching-features","order_num":3},{"id":"b71eeb29-b51c-4b39-8548-d662467a2316","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe Great Pyramid of Giza was built to …","payload":{"options":[{"text":"serve as the tomb of a king.","label":"i"},{"text":"help ships find the harbour at night.","label":"ii"},{"text":"celebrate a victory in war.","label":"iii"},{"text":"store the city's grain supply.","label":"iv"},{"text":"honour the goddess of hunting.","label":"v"},{"text":"supply fresh water to the whole city.","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph A says the Great Pyramid was built as a tomb for a king, matching ending i.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":5},{"id":"bcd49d16-8697-471d-9d65-1ac9d3382b7b","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":2,"question_type":"summary_completion","prompt":"Gap 2: the freed particles that carry the charge are called __________. (ONE WORD ONLY) — see the summary above.","payload":{},"answer":{"answer":"electrons","alternatives":[]},"explanation":"Paragraph 3 explains that the reaction releases electrons, which flow through the wire; 'electrons' appears verbatim.","skill_tag":"detail","sub_skill":"summary-gap","order_num":2},{"id":"be4a79c1-d2a7-4fa7-9dfe-5a96ff3f53fd","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":2,"question_type":"matching_information","prompt":"Which paragraph describes an invention discovered partly by accident? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D explains that Fleming found penicillin by chance after mould appeared on a forgotten dish, an accidental discovery.","skill_tag":"scanning","sub_skill":"locate-information","order_num":2},{"id":"bf87161a-b1b9-43cb-99bd-c28e75807bda","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":3,"question_type":"summary_completion","prompt":"Gap 3: the first true battery was built in the year __________. (ONE NUMBER ONLY) — see the summary above.","payload":{},"answer":{"answer":"1800","alternatives":[]},"explanation":"Paragraph 1 says Alessandro Volta built the first true battery in 1800; the date appears verbatim.","skill_tag":"detail","sub_skill":"summary-gap","order_num":3},{"id":"c1970e9e-b928-40f4-8c09-f04109d320bf","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":6,"question_type":"flow_chart_completion","prompt":"Complete the flow-chart. Choose NO MORE THAN TWO WORDS from the passage for each gap.\n\nWHAT HAPPENS WHEN A BATTERY POWERS A DEVICE\nA circuit connects the battery to a device such as a torch\n      ↓\nAt the anode, a chemical reaction releases (6) __________\n      ↓\nThese particles travel along the wire and through the device, creating a (7) __________\n      ↓\nThe moving charge powers the device, then returns to the cathode\n      ↓\nWhen the chemicals are used up, the battery goes (8) __________","payload":{},"answer":{"answer":"electrons","alternatives":[]},"explanation":"Paragraph 3 says the reaction at the anode releases electrons; 'electrons' appears verbatim. (Same answer as gap 2, here in the process flow.)","skill_tag":"detail","sub_skill":"process-step","order_num":6},{"id":"c38898e1-c9aa-4cc2-9f65-e24de60a6948","passage_id":"91b89f32-5d37-4408-924b-392a904cbd3a","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nDesigned low buildings intended to blend with the surrounding landscape.","payload":{"options":[{"text":"Antoni Gaudí","label":"A"},{"text":"Frank Lloyd Wright","label":"B"},{"text":"Zaha Hadid","label":"C"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C credits Wright with long, low homes that sit close to the ground and echo the prairie around them. Gaudí (A) reached upward with towers, so the low, horizontal style belongs to Wright.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"c62cc073-07c1-4e08-82db-1d2fbbecc25d","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":5,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe name Impressionism was taken from …","payload":{"options":[{"text":"the everyday lives of ordinary people.","label":"A"},{"text":"the title of one of Monet's paintings.","label":"B"},{"text":"the hidden workings of the unconscious mind.","label":"C"},{"text":"the strict rules of classical geometry.","label":"D"},{"text":"a return to medieval religious themes.","label":"E"},{"text":"the bright colours of modern advertising.","label":"F"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C says the movement 'owed its name to mockery: a critic borrowed the title of one of Monet's paintings'. The name therefore came from a painting's title.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":5},{"id":"c692e8a3-a896-4b9b-a5e0-e67c996423c5","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":7,"question_type":"matching_information","prompt":"Which paragraph explains why later sailors no longer feared falling off the edge of the world? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C says the first voyage around the globe proved the Earth was round, so sailors stopped fearing they might fall off its edge.","skill_tag":"scanning","sub_skill":"locate-information","order_num":7},{"id":"ca19529b-dbc6-445e-85d5-9edbb08037dd","passage_id":"145f4430-a780-4988-b3bd-f977f2c73704","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nMade about two thousand glider flights and recorded how curved wings behaved.","payload":{"options":[{"text":"George Cayley","label":"A"},{"text":"Otto Lilienthal","label":"B"},{"text":"The Wright brothers","label":"C"},{"text":"Alberto Santos-Dumont","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"Paragraph C credits Lilienthal with around two thousand glider flights and detailed measurements that influenced others. Cayley (A) built only one late glider, so attributing the large number of flights to him is a half-correct trap.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"cbfb710c-b3f8-4500-b98b-0ca4b94d39b7","passage_id":"136fda06-cba5-4e1a-881d-bc821f0312ff","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUsed large ships and gifts to display his country's wealth and build friendly relations.","payload":{"options":[{"text":"Zheng He","label":"A"},{"text":"Ferdinand Magellan","label":"B"},{"text":"James Cook","label":"C"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Zheng He led a huge fleet of 'treasure ships' for the Chinese emperor, matching explorer A.","skill_tag":"detail","sub_skill":"match-feature","order_num":2},{"id":"cc8f0521-2fd6-4395-ae3b-0f628c27ae0b","passage_id":"91fc723e-d9c0-41bd-82cb-da04de6b2516","q_num":4,"question_type":"matching_information","prompt":"Which paragraph refers to an invention that helped people travel further from home? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph A says the Wright brothers' flying machine let people cross distances that had once taken days, helping them travel far from home.","skill_tag":"scanning","sub_skill":"locate-information","order_num":4},{"id":"d647e31d-7348-403d-99a2-1b3f148c0aa2","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":7,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe Colossus of Rhodes was erected to …","payload":{"options":[{"text":"serve as the tomb of a king.","label":"i"},{"text":"help ships find the harbour at night.","label":"ii"},{"text":"celebrate a victory in war.","label":"iii"},{"text":"store the city's grain supply.","label":"iv"},{"text":"honour the goddess of hunting.","label":"v"},{"text":"supply fresh water to the whole city.","label":"vi"}]},"answer":{"answer":"iii","alternatives":[]},"explanation":"Paragraph D says the Colossus was built to celebrate a victory over an invading army, matching ending iii. (Endings iv, v and vi are unused distractors.)","skill_tag":"detail","sub_skill":"sentence-ending","order_num":7},{"id":"d6aad9a8-d180-4e43-b888-79f76301b755","passage_id":"723850ff-85db-4ecd-b43e-992a6d1ee340","q_num":6,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nIdentified sounds too low for humans to hear that help distant herds coordinate their movements.","payload":{"options":[{"text":"Karl von Frisch","label":"A"},{"text":"Irene Pepperberg","label":"B"},{"text":"Con Slobodchikoff","label":"C"},{"text":"Katy Payne","label":"D"}]},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph E credits Katy Payne with discovering elephant infrasound, sound too low for human ears.","skill_tag":"detail","sub_skill":"match-feature","order_num":6},{"id":"d70584e5-76d8-4907-81a2-fc6c29edde1a","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":4,"question_type":"matching_information","prompt":"Which paragraph refers to a wonder that helped people travel safely? (Write the correct letter A–D.)","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C says the Lighthouse of Alexandria guided ships safely into the busy harbour, helping travellers at sea.","skill_tag":"scanning","sub_skill":"locate-information","order_num":4},{"id":"d75cb0d6-0e27-430c-9df9-e98f85bffe20","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":3,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nRawls asks people to choose society's basic rules …","payload":{"options":[{"text":"from behind a veil that hides their own place in society","label":"i"},{"text":"according to what people are actually able to do and to be","label":"ii"},{"text":"by calculating the total amount of pleasure a policy produces","label":"iii"},{"text":"that fix in advance the precise pattern holdings should form","label":"iv"},{"text":"with the consent of an all-powerful central state","label":"v"},{"text":"in proportion to the inherited wealth each family holds","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph B says choosers select rules 'from behind a veil of ignorance, knowing nothing of the talents, wealth or social position we will end up with', matching ending (i). Ending (ii) describes Sen; (iii) describes utilitarianism; (iv) is the patterned approach Nozick rejects.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":3},{"id":"d97c73f6-22a5-48b4-adf3-89172b484af5","passage_id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","q_num":3,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nCannon pointed out that a similar bodily upheaval …","payload":{"options":[{"text":"accompanies several emotions that feel quite different","label":"i"},{"text":"must be labelled before any emotion is felt","label":"ii"},{"text":"is shaped by an earlier appraisal of the event","label":"iii"},{"text":"is the source of the emotion rather than its result","label":"iv"},{"text":"has no measurable effect on behaviour","label":"v"},{"text":"can be switched off through conscious effort","label":"vi"}]},"answer":{"answer":"i","alternatives":[]},"explanation":"Paragraph C reports Cannon's objection that fear and rage share much the same physiological signature, so arousal cannot, on its own, tell the emotions apart: ending (i). Ending (iv) restates James-Lange; (ii) restates the two-factor view; (iii) restates appraisal theory.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":3},{"id":"d9adecbb-a082-4874-aab8-52163dff5178","passage_id":"9ec8a8a9-d561-4d84-96fc-9c4af4e23940","q_num":6,"question_type":"mcq_single","prompt":"Which statement best captures the passage's overall position?","payload":{"options":[{"text":"Shared resources are always destroyed unless privatised","label":"A"},{"text":"Hardin's model fits some cases, but communities can also govern commons well","label":"B"},{"text":"Ostrom proved that resources can never be overused","label":"C"},{"text":"Self-interest plays no part in how people use resources","label":"D"}]},"answer":{"answer":"B","alternatives":[]},"explanation":"The passage accepts that Hardin's logic captures unregulated cases yet shows, through Ostrom, that communities often manage commons effectively, matching B. A, C and D are too extreme.","skill_tag":"main_idea","sub_skill":null,"order_num":6},{"id":"dc161cc1-6f58-497e-87da-d26dd7aba7cf","passage_id":"06cd15d3-56c0-4f1f-aa46-6a50256e77b2","q_num":6,"question_type":"matching_information","prompt":"Which paragraph argues that protecting individual liberty will always disturb any fixed distribution?","payload":{},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph C reports Nozick's warning that imposing a preferred pattern 'is to license constant interference, since liberty will always upset such patterns'. Paragraph E concerns aggregate welfare, not liberty, and B treats inequality through the difference principle rather than through liberty's disruptive effect.","skill_tag":"scanning","sub_skill":null,"order_num":6},{"id":"dfa1b3f0-34a0-4f0e-b0ba-dc070e73b8ae","passage_id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nIn Lazarus's account, the initial bodily reaction …","payload":{"options":[{"text":"accompanies several emotions that feel quite different","label":"i"},{"text":"must be labelled before any emotion is felt","label":"ii"},{"text":"is shaped by an earlier appraisal of the event","label":"iii"},{"text":"is the source of the emotion rather than its result","label":"iv"},{"text":"has no measurable effect on behaviour","label":"v"},{"text":"can be switched off through conscious effort","label":"vi"}]},"answer":{"answer":"iii","alternatives":[]},"explanation":"Paragraph E states that, for Lazarus, the body's response itself depends on a quick evaluation of what an event means for the individual, so arousal follows from that judgement: ending (iii). Ending (i) belongs to Cannon-Bard and (iv) to James-Lange, both reversed traps.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"e099a82f-ba89-49e3-9243-803b1cdc2d2f","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":4,"question_type":"table_completion","prompt":"Complete the table. Choose NO MORE THAN TWO WORDS from the passage for each gap.\n\n| Part of a cell | What it does |\n| --- | --- |\n| Negative electrode, or (4) __________ | gives off electrons during the reaction |\n| Positive electrode, or (5) __________ | receives the electrons from the circuit |\n| Electrolyte | lets charged particles move between the two electrodes |","payload":{},"answer":{"answer":"anode","alternatives":[]},"explanation":"Paragraph 2 names the negative electrode the anode; paragraph 3 says the reaction that releases electrons begins there.","skill_tag":"detail","sub_skill":"table-gap","order_num":4},{"id":"e1249ae5-5f69-4972-ad37-c7a8e3bc2dc4","passage_id":"071dd482-c2d5-48ac-9e58-2bc2f55ad26c","q_num":5,"question_type":"matching_information","prompt":"Which paragraph notes that a style came to be widely disliked despite the intentions behind it?","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D records that Brutalism, conceived as honest and democratic, was later condemned by many as bleak. Paragraph C describes Bauhaus aims without noting later public rejection, while B and E concern principles and reactions rather than a reputation that soured.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"e25f0edc-00fe-4e3c-90a6-8a16d7cf6647","passage_id":"87726f17-4efc-48db-b08b-d4fea2de8efe","q_num":1,"question_type":"summary_completion","prompt":"Complete the summary. Choose NO MORE THAN TWO WORDS from the passage for each gap.\n\nA battery stores energy in chemical form and releases it as electricity. Inside every cell there are two terminals, or electrodes, separated by a chemical paste or liquid called the (1) __________. When the cell is connected in a circuit, a chemical reaction frees tiny particles known as (2) __________, which carry the electric charge. The first true battery was built in the year (3) __________ by the Italian scientist Alessandro Volta.","payload":{},"answer":{"answer":"electrolyte","alternatives":[]},"explanation":"Paragraph 2 states that the two electrodes sit in a substance called the electrolyte; the word appears verbatim.","skill_tag":"detail","sub_skill":"summary-gap","order_num":1},{"id":"e5c89c73-9ad9-4935-b28e-774cbcf8a882","passage_id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nDennett regards the apparent unexplained residue of experience as …","payload":{"options":[{"text":"the immaterial soul that supposedly inhabits it","label":"i"},{"text":"the role it plays in a wider system of inputs and outputs","label":"ii"},{"text":"an inner glow that physics can never capture","label":"iii"},{"text":"a confusion that careful analysis will dissolve","label":"iv"},{"text":"the precise chemistry of the brain that produces it","label":"v"},{"text":"a question science should refuse to ask","label":"vi"}]},"answer":{"answer":"iv","alternatives":[]},"explanation":"Paragraph E reports Dennett's view that the supposed mystery of experience is a muddle that dissolves under analysis, matching ending (iv). Ending (iii) states the very position Dennett rejects, making it a reversed distractor.","skill_tag":"detail","sub_skill":"sentence-completion","order_num":4},{"id":"ec415213-2971-4421-a49b-07ac0fb49391","passage_id":"d12e5cb5-7414-4499-b929-ca82b4c77fb4","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nUses heat held deep inside the Earth to produce steam for turbines.","payload":{"options":[{"text":"Solar power","label":"A"},{"text":"Hydropower","label":"B"},{"text":"Geothermal power","label":"C"},{"text":"Biomass energy","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph E describes geothermal power as tapping the heat held beneath the surface of the Earth to raise steam and spin turbines. Hydropower (B) also drives turbines but uses falling water, making it a half-correct trap; the source of energy here is underground heat.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"eef85d94-d690-4c11-be2c-0b2269c49167","passage_id":"a1f51245-c0ce-4e4c-9f02-9b6917e86b54","q_num":6,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nThe Lighthouse of Alexandria used a fire to …","payload":{"options":[{"text":"serve as the tomb of a king.","label":"i"},{"text":"help ships find the harbour at night.","label":"ii"},{"text":"celebrate a victory in war.","label":"iii"},{"text":"store the city's grain supply.","label":"iv"},{"text":"honour the goddess of hunting.","label":"v"},{"text":"supply fresh water to the whole city.","label":"vi"}]},"answer":{"answer":"ii","alternatives":[]},"explanation":"Paragraph C says the lighthouse guided ships safely into the harbour, with a great fire burning at its top, matching ending ii.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":6},{"id":"f4b6a0eb-88bd-4dc2-970a-0783359ab72e","passage_id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","q_num":5,"question_type":"matching_information","prompt":"Which paragraph describes an experiment in which participants were given the same physiological stimulus yet reported contrasting feelings?","payload":{},"answer":{"answer":"D","alternatives":[]},"explanation":"Paragraph D recounts the Schachter-Singer study in which volunteers injected with the same stimulant felt either euphoric or irritable depending on the company they were placed in. Paragraph C discusses Cannon's reasoning rather than a study of his own, while B and E describe positions rather than a single shared-stimulus experiment.","skill_tag":"scanning","sub_skill":null,"order_num":5},{"id":"f514fef4-716b-4200-856e-8a1a182c9ae7","passage_id":"145f4430-a780-4988-b3bd-f977f2c73704","q_num":4,"question_type":"matching_information","prompt":"Which paragraph mentions a flight that crowds in Europe were able to watch?","payload":{},"answer":{"answer":"E","alternatives":[]},"explanation":"Paragraph E describes Santos-Dumont flying the 14-bis in Paris in 1906 before witnesses, the first powered flight publicly seen in Europe. Other paragraphs describe theory (B), gliding (C) or the Wrights' quiet trials (D), not a public European flight.","skill_tag":"scanning","sub_skill":null,"order_num":4},{"id":"f92157ca-74ad-4a22-9b03-a29ee7206a62","passage_id":"8a655492-c0a6-4b2d-a7b7-55ddeb860090","q_num":1,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nRegarded mind and body as two different kinds of substance.","payload":{"options":[{"text":"René Descartes","label":"A"},{"text":"The functionalists","label":"B"},{"text":"David Chalmers","label":"C"},{"text":"Daniel Dennett","label":"D"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B attributes to Descartes the view that thought and matter are fundamentally separate substances. Functionalism (B) is the opposing distractor, since paragraph C explicitly defines mind by organisational role rather than by being a separate kind of substance at all.","skill_tag":"detail","sub_skill":"matching-features","order_num":1},{"id":"fbf397a9-85f2-4585-99ab-b22dc8a48ae4","passage_id":"f4e7809b-7d09-435c-b5ba-99a3650846e1","q_num":2,"question_type":"matching_features","prompt":"Match the statement with the correct option. Choose one letter.\n\nRequired both physiological arousal and a cognitive label supplied by the situation.","payload":{"options":[{"text":"James-Lange theory","label":"A"},{"text":"Cannon-Bard theory","label":"B"},{"text":"Schachter-Singer two-factor theory","label":"C"},{"text":"Lazarus appraisal theory","label":"D"}]},"answer":{"answer":"C","alternatives":[]},"explanation":"Paragraph D sets out the two-factor account, in which the same undifferentiated arousal is labelled as fear, anger or joy according to the surrounding situation. The James-Lange view (A) is the trap, since it ties each distinct emotion to a distinct bodily pattern rather than to interpretation. The Cannon-Bard theory is an unused option here.","skill_tag":"detail","sub_skill":"matching-features","order_num":2},{"id":"fe35b172-7f35-40f7-b8ae-ec2eec38c3f1","passage_id":"2ade381b-2d88-4870-92f0-f278734ff2a4","q_num":4,"question_type":"matching_sentence_endings","prompt":"Complete the sentence with the correct ending. Choose one letter.\n\nRealist painters chose to portray …","payload":{"options":[{"text":"the everyday lives of ordinary people.","label":"A"},{"text":"the title of one of Monet's paintings.","label":"B"},{"text":"the hidden workings of the unconscious mind.","label":"C"},{"text":"the strict rules of classical geometry.","label":"D"},{"text":"a return to medieval religious themes.","label":"E"},{"text":"the bright colours of modern advertising.","label":"F"}]},"answer":{"answer":"A","alternatives":[]},"explanation":"Paragraph B says Realism 'turned instead to the everyday lives of ordinary people'. Endings D, E and F are not supported anywhere in the passage.","skill_tag":"detail","sub_skill":"sentence-ending","order_num":4}]}$staging_copy$::jsonb; row jsonb;
BEGIN
  FOR row IN SELECT value FROM jsonb_array_elements(packet->'passages') LOOP
    IF EXISTS (SELECT 1 FROM public.reading_passages WHERE id=(row->>'id')::uuid OR slug=row->>'slug')
      THEN RAISE EXCEPTION 'Staging Reading copy would overwrite existing content: %',row->>'slug'; END IF;
    INSERT INTO public.reading_passages(id,slug,title,library,status,body_markdown,metadata,glossary,image_url,difficulty_level,topic_tags,skill_focus,word_count,estimated_minutes)
    VALUES((row->>'id')::uuid,row->>'slug',row->>'title',row->>'library','published',row->>'body_markdown',row->'metadata',COALESCE(NULLIF(row->'glossary','null'::jsonb),'[]'::jsonb),row->>'image_url',row->>'difficulty_level',ARRAY(SELECT jsonb_array_elements_text(COALESCE(NULLIF(row->'topic_tags','null'::jsonb),'[]'::jsonb))),row->>'skill_focus',(row->>'word_count')::integer,(row->>'estimated_minutes')::integer);
  END LOOP;
  FOR row IN SELECT value FROM jsonb_array_elements(packet->'questions') LOOP
    INSERT INTO public.reading_questions(id,passage_id,q_num,question_type,prompt,payload,answer,explanation,skill_tag,sub_skill,order_num)
    VALUES((row->>'id')::uuid,(row->>'passage_id')::uuid,(row->>'q_num')::integer,row->>'question_type',row->>'prompt',row->'payload',row->'answer',row->>'explanation',row->>'skill_tag',row->>'sub_skill',(row->>'order_num')::integer);
  END LOOP;
END $seed$;
COMMIT;
